# These phrases often appear in condolence statements, employee-support copy, and
# public-safety stories without making healthcare the article's central visual
# subject. They are ignored only for health-pool matching; all other topic signals
# remain available to the classifier.
EDITORIAL_INCIDENTAL_HEALTH_CONTEXT_PATTERN = re.compile(
    r"\b(?:mental\s+)?health\s+and\s+well[- ]?being\b"
    r"|\bhealth\s+of\s+(?:personnel|employees|staff|first responders?)\b",
    re.I,
)


def _editorial_topic_rule_matches(folder, pattern, text):
    candidate = str(text or "")
    if folder == "topics/health":
        candidate = EDITORIAL_INCIDENTAL_HEALTH_CONTEXT_PATTERN.sub(" ", candidate)
    return bool(pattern.search(candidate))


def _editorial_image_inventory(refresh=False):
    """Discover approved image files from ``images/editorial``.

    Placeholder files, desktop metadata, and duplicate file stems are excluded.
    Topic-level ``og-*`` graphics are approved rotation assets. When optimized WebP
    and larger source formats share a stem, WebP is preferred deterministically.
    """
    global _EDITORIAL_IMAGE_INVENTORY_CACHE
    with _EDITORIAL_IMAGE_LOCK:
        if _EDITORIAL_IMAGE_INVENTORY_CACHE is not None and not refresh:
            return _EDITORIAL_IMAGE_INVENTORY_CACHE

        grouped = defaultdict(list)
        excluded = []
        if EDITORIAL_IMAGE_ROOT.exists():
            for path in sorted(EDITORIAL_IMAGE_ROOT.rglob("*"), key=lambda value: value.as_posix().lower()):
                if not path.is_file():
                    continue
                rel = path.relative_to(EDITORIAL_IMAGE_ROOT)
                suffix = path.suffix.lower()
                if suffix not in EDITORIAL_IMAGE_EXTENSIONS:
                    excluded.append({"path": rel.as_posix(), "reason": "non-image-or-placeholder"})
                    continue
                grouped[(rel.parent.as_posix(), path.stem.casefold())].append(path)

        pools = defaultdict(list)
        for (folder, _stem), candidates in sorted(grouped.items()):
            candidates.sort(key=lambda path: (
                EDITORIAL_IMAGE_EXTENSION_PRIORITY.get(path.suffix.lower(), 99),
                path.name.casefold(),
            ))
            chosen = candidates[0]
            for duplicate in candidates[1:]:
                excluded.append({
                    "path": duplicate.relative_to(EDITORIAL_IMAGE_ROOT).as_posix(),
                    "reason": "duplicate-stem-alternate-format",
                    "preferred": chosen.relative_to(EDITORIAL_IMAGE_ROOT).as_posix(),
                })
            rel = chosen.relative_to(EDITORIAL_IMAGE_ROOT).as_posix()
            pools[folder].append(f"/images/editorial/{rel}")

        normalized_pools = {
            folder: sorted(images, key=lambda value: value.casefold())
            for folder, images in sorted(pools.items())
            if images
        }
        _EDITORIAL_IMAGE_INVENTORY_CACHE = {
            "root": str(EDITORIAL_IMAGE_ROOT),
            "pools": normalized_pools,
            "image_count": sum(len(images) for images in normalized_pools.values()),
            "excluded": sorted(excluded, key=lambda row: row.get("path", "").casefold()),
        }
        return _EDITORIAL_IMAGE_INVENTORY_CACHE


def _round_robin_pool_images(folder_ids, pools):
    """Combine folders while preserving each folder's own sequential order."""
    folder_lists = [list(pools.get(folder, [])) for folder in folder_ids if pools.get(folder)]
    if not folder_lists:
        return []
    combined = []
    for index in range(max(len(images) for images in folder_lists)):
        for images in folder_lists:
            if index < len(images):
                combined.append(images[index])
    return combined


def _fallback_story_subject_blob(headline="", item=None):
    """Return the editorial subject signal used for topic-image selection.

    Topic routing intentionally uses only the headline and concise summary fields.
    Full article bodies commonly mention roads, airports, hospitals, schools, or
    weather incidentally; allowing those references to control the image pool caused
    unrelated business and public-safety stories to receive transportation photos.
    """
    item = item if isinstance(item, dict) else {}
    return " ".join(filter(None, [
        str(headline or ""),
        str(item.get("headline") or item.get("title") or ""),
        str(item.get("teaser") or item.get("summary") or ""),
    ]))


def _fallback_story_blob(headline="", item=None):
    """Return broader location evidence while keeping body text out of topic routing."""
    item = item if isinstance(item, dict) else {}
    return " ".join(filter(None, [
        _fallback_story_subject_blob(headline, item),
        str(item.get("body") or "")[:1600],
        str(item.get("article_text") or "")[:1200],
    ]))


def _detect_editorial_city(text, category_key=""):
    lower = str(text or "").lower()
    for city, pattern in EDITORIAL_CITY_PATTERNS:
        if not re.search(pattern, lower, re.I):
            continue
        # Stuart and Sebastian are also personal names. Require a county context or
        # an explicit geographic phrase before treating them as city evidence.
        if city == "stuart" and category_key != "martin":
            if not re.search(
                r"\b(?:in|near|downtown|city of|police in|officials in)\s+stuart\b|"
                r"\bstuart,?\s+(?:florida|fla[.]?|fl)\b|\bstuart\s+(?:city|police|fire|road|bridge|business|restaurant|school)\b",
                lower,
            ):
                continue
        if city == "sebastian" and category_key != "indian_river":
            if not re.search(
                r"\b(?:in|near|downtown|city of|police in|officials in)\s+sebastian\b|"
                r"\bsebastian,?\s+(?:florida|fla[.]?|fl)\b|\bsebastian\s+(?:city|police|river|inlet|road|business|restaurant|school)\b",
                lower,
            ):
                continue
        return city
    return ""


def _detect_high_specificity_editorial_topic(text):
    """Return a subject pool that should visually outrank a named city.

    These rules intentionally avoid bare geographic words such as ``beach`` and
    ``river`` so place names like Vero Beach and Indian River do not accidentally
    become weather/environment stories.
    """
    for folder, pattern in EDITORIAL_HIGH_SPECIFICITY_TOPIC_RULES:
        if _editorial_topic_rule_matches(folder, pattern, text):
            return folder
    return ""


def _detect_editorial_topic(text):
    for folder, pattern in EDITORIAL_TOPIC_RULES:
        if _editorial_topic_rule_matches(folder, pattern, text):
            return folder
    return ""


def _editorial_pool_for_story(category_key, headline="", item=None, inventory=None):
    inventory = inventory or _editorial_image_inventory()
    pools = inventory.get("pools", {})
    subject_text = _fallback_story_subject_blob(headline, item)
    location_text = _fallback_story_blob(headline, item)

    # Schools, infrastructure/traffic operations, health, and weather/environment
    # describe the visual subject more precisely than a city name. Topic routing uses
    # headline/summary evidence only so incidental body references cannot hijack it.
    specific_topic = _detect_high_specificity_editorial_topic(subject_text)
    if specific_topic and pools.get(specific_topic):
        return specific_topic, list(pools[specific_topic]), "specific-topic-before-city"

    city = _detect_editorial_city(location_text, category_key)
    city_pool = f"cities/{city}" if city else ""
    if city_pool and pools.get(city_pool):
        return city_pool, list(pools[city_pool]), "exact-city"

    detected_topic = _detect_editorial_topic(subject_text)
    # Broad category pools yield to an exact city, but remain stronger than county
    # and regional fallbacks.
    if category_key in {"crime", "business", "sports", "things_to_do", "local_gov"}:
        category_topic = EDITORIAL_CATEGORY_TOPIC.get(category_key, "")
        if pools.get(category_topic):
            return category_topic, list(pools[category_topic]), "category-topic"
    elif detected_topic and pools.get(detected_topic):
        return detected_topic, list(pools[detected_topic]), "detected-topic"

    county_folder = EDITORIAL_COUNTY_FOLDER.get(category_key, "")
    if county_folder and pools.get(county_folder):
        return county_folder, list(pools[county_folder]), "county-folder"
    if category_key in EDITORIAL_COUNTY_CITY_FOLDERS:
        county_images = _round_robin_pool_images(
            EDITORIAL_COUNTY_CITY_FOLDERS[category_key], pools
        )
        if county_images:
            return f"county/{category_key}", county_images, "county-city-round-robin"

    general_pool = "general/treasure-coast"
    if pools.get(general_pool):
        return general_pool, list(pools[general_pool]), "regional-general"
    return "", [], "no-editorial-pool"


def _fallback_story_key(category_key, headline="", item=None):
    item = item if isinstance(item, dict) else {}
    identity = ""
    for key in (
        "editorial_story_id", "_editorial_story_id", "_archived_slug", "slug",
        "_current_custom_publication_slug", "source_url", "link",
    ):
        value = str(item.get(key) or "").strip()
        if value:
            identity = f"{key}:{value}"
            break
    if not identity:
        normalized = re.sub(r"\s+", " ", str(headline or item.get("headline") or "").strip().lower())
        identity = f"headline:{normalized}|category:{category_key}"
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()[:32]


def _load_editorial_image_rotation_state():
    global _EDITORIAL_IMAGE_ROTATION_STATE
    with _EDITORIAL_IMAGE_LOCK:
        if _EDITORIAL_IMAGE_ROTATION_STATE is not None:
            return _EDITORIAL_IMAGE_ROTATION_STATE
        payload = {}
        if EDITORIAL_IMAGE_ROTATION_PATH.exists():
            try:
                payload = json.loads(EDITORIAL_IMAGE_ROTATION_PATH.read_text(encoding="utf-8"))
            except Exception as exc:
                print(f"  Editorial image rotation state reset after parse error: {exc}")
                payload = {}
        if not isinstance(payload, dict):
            payload = {}
        _EDITORIAL_IMAGE_ROTATION_STATE = {
            "schema_version": EDITORIAL_IMAGE_SCHEMA_VERSION,
            "selection_policy_version": EDITORIAL_IMAGE_SELECTION_POLICY_VERSION,
            "pool_cursors": payload.get("pool_cursors") if isinstance(payload.get("pool_cursors"), dict) else {},
            "pool_last_image": payload.get("pool_last_image") if isinstance(payload.get("pool_last_image"), dict) else {},
            "global_last_image": str(payload.get("global_last_image") or ""),
            "story_assignments": payload.get("story_assignments") if isinstance(payload.get("story_assignments"), dict) else {},
            "archive_migration_policy_version": int(payload.get("archive_migration_policy_version") or 0),
        }
        return _EDITORIAL_IMAGE_ROTATION_STATE


def _editorial_image_file_exists(url):
    raw = str(url or "").strip()
    if not raw:
        return False
    path = urlsplit(raw).path if "://" in raw else raw
    if not path.startswith("/images/editorial/"):
        return False
    return (OUTPUT_DIR / path.lstrip("/")).is_file()


def _select_editorial_fallback(category_key, headline="", item=None, force_new=False, avoid_url=""):
    global _EDITORIAL_IMAGE_ROTATION_DIRTY
    inventory = _editorial_image_inventory()
    pool_id, images, basis = _editorial_pool_for_story(
        category_key, headline, item, inventory=inventory
    )
    if not images:
        return None

    state = _load_editorial_image_rotation_state()
    story_key = _fallback_story_key(category_key, headline, item)
    with _EDITORIAL_IMAGE_LOCK:
        assignment = state["story_assignments"].get(story_key)
        if not force_new and isinstance(assignment, dict):
            assigned_url = str(assignment.get("image_url") or "")
            assigned_path = urlsplit(assigned_url).path if assigned_url else ""
            # Preserve stable assignments only while they still belong to the pool
            # selected by the current policy. This deliberately reclassifies older
            # city assignments when a school, road, health, or weather pool is now
            # the more accurate visual match.
            if (
                str(assignment.get("pool_id") or "") == pool_id
                and assigned_path in images
                and _editorial_image_file_exists(assigned_url)
            ):
                selection = dict(assignment)
                selection.update({"story_key": story_key, "reused": True})
                _EDITORIAL_IMAGE_LAST_SELECTION[story_key] = selection
                return selection

        try:
            cursor = int(state["pool_cursors"].get(pool_id, 0) or 0)
        except Exception:
            cursor = 0
        index = cursor % len(images)
        selected = images[index]
        last_image = str(state["pool_last_image"].get(pool_id) or "")
        global_last_image = str(state.get("global_last_image") or "")
        avoid = str(avoid_url or "")
        if len(images) > 1:
            attempts = 0
            while selected in {last_image, global_last_image, avoid} and attempts < len(images) - 1:
                index = (index + 1) % len(images)
                selected = images[index]
                attempts += 1

        state["pool_cursors"][pool_id] = index + 1
        state["pool_last_image"][pool_id] = selected
        state["global_last_image"] = selected
        selection = {
            "story_key": story_key,
            "headline": str(headline or (item or {}).get("headline") or "")[:180],
            "category_key": category_key,
            "selection_policy_version": EDITORIAL_IMAGE_SELECTION_POLICY_VERSION,
            "pool_id": pool_id,
            "selection_basis": basis,
            "image_url": f"{SITE_URL}{selected}",
            "assigned_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "reused": False,
        }
        state["story_assignments"][story_key] = {
            key: value for key, value in selection.items() if key != "reused"
        }
        _EDITORIAL_IMAGE_LAST_SELECTION[story_key] = selection
        _EDITORIAL_IMAGE_RUN_ASSIGNMENTS.append(selection)
        _EDITORIAL_IMAGE_ROTATION_DIRTY = True
        return selection


def _branded_fallback_image(category_key):
    base_names = BRANDED_FALLBACK_IMAGE_MAP.get(
        category_key, BRANDED_FALLBACK_IMAGE_MAP["top_news"]
    )
    for base in base_names:
        if (OUTPUT_DIR / base).exists():
            return f"{SITE_URL}/{base}", ""
    generic = "og-image.png"
    if (OUTPUT_DIR / generic).exists():
        return f"{SITE_URL}/{generic}", ""
    return "", ""


def get_fallback_image(category_key, headline="", sequential=False, item=None, force_new=False, avoid_url=""):
    """Return a stable, sequentially rotated editorial fallback image.

    The ``sequential`` argument remains for call-site compatibility; all new story
    assignments now rotate sequentially by pool. Existing story assignments remain
    stable across pages and workflow runs. Topic-level OG graphics participate in
    their folder rotation; root OG graphics remain the final emergency fallback when
    no eligible editorial pool exists.
    """
    del sequential
    selection = _select_editorial_fallback(
        category_key, headline, item=item, force_new=force_new, avoid_url=avoid_url
    )
    if selection:
        return selection["image_url"], ""
    return _branded_fallback_image(category_key)


def _is_managed_editorial_fallback_image(url):
    """Return True for TCT-owned images managed by the editorial fallback pool."""
    raw = str(url or "").strip()
    if not raw:
        return False
    parsed = urlsplit(raw)
    if parsed.netloc and "treasurecoast.today" not in parsed.netloc.lower():
        return False
    path = parsed.path if parsed.path else raw
    return path.startswith("/images/editorial/")


def _is_legacy_or_branded_fallback_image(url):
    raw = str(url or "").strip()
    if not raw:
        return True
    parsed = urlsplit(raw)
    if parsed.netloc and "treasurecoast.today" not in parsed.netloc.lower():
        return False
    path = parsed.path.lower() if parsed.path else raw.lower()
    if "/images/fallback/" in path:
        return True
    return bool(re.fullmatch(
        r"/(?:og-(?:image|local_gov|crime|business|sports|things_to_do|florida|martin|st_lucie|indian_river)\.png)",
        path,
    ))


def _is_real_source_image_url(url):
    """Return True only for a non-fallback image supplied by a real story source."""
    raw = str(url or "").strip()
    return bool(
        raw
        and not _is_legacy_or_branded_fallback_image(raw)
        and not _is_managed_editorial_fallback_image(raw)
        and not _source_image_rejection_reason(raw)
    )


def _absolute_image_url(url):
    """Return one absolute image URL without changing publisher query parameters."""
    raw = html_lib.unescape(str(url or "").strip())
    if raw.startswith("//"):
        return "https:" + raw
    if raw.startswith("/"):
        return f"{SITE_URL}{raw}"
    return raw



def _normalize_article_slug(value):
    """Return one article slug from a slug, permalink, href, or archive field."""
    raw = html_lib.unescape(str(value or "").strip())
    if not raw:
        return ""
    try:
        parsed = urlsplit(raw)
        path = parsed.path or raw
    except Exception:
        path = raw
    path = path.split("?", 1)[0].split("#", 1)[0].rstrip("/")
    if "/articles/" in path:
        path = path.rsplit("/articles/", 1)[-1]
    else:
        path = path.rsplit("/", 1)[-1]
    if path.endswith(".html"):
        path = path[:-5]
    return path.strip()


def _load_article_content_overrides(path=None):
    override_path = Path(path or ARTICLE_CONTENT_OVERRIDES_PATH)
    if not override_path.is_file():
        return {}
    try:
        payload = json.loads(override_path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    rows = payload.get("overrides", payload) if isinstance(payload, dict) else {}
    return {
        _normalize_article_slug(k): dict(v)
        for k, v in rows.items()
        if _normalize_article_slug(k) and isinstance(v, dict)
    }


def _apply_article_content_overrides_to_outputs(output_root=None):
    root = Path(output_root or OUTPUT_DIR)
    overrides = _load_article_content_overrides(root / "data" / "article-content-overrides.json")
    if not overrides:
        return 0
    changed = 0
    archive_path = root / "archive.json"
    archive = load_archive(archive_path)
    for row in archive:
        slug = _normalize_article_slug(row.get("slug") or row.get("link") or row.get("permalink"))
        ov = overrides.get(slug)
        if not ov:
            continue
        for field in ("headline", "teaser", "body", "image_url", "updated", "date_modified", "meaningful_update_at"):
            if ov.get(field):
                row[field] = ov[field]
        row["is_meaningful_update"] = True
        row["update_status"] = ov.get("update_status", "resolved")
        changed += 1
    if changed:
        archive_path.write_text(json.dumps(archive, indent=2, ensure_ascii=False), encoding="utf-8")

    data_path = root / "data.json"
    if data_path.is_file():
        try:
            data_payload = json.loads(data_path.read_text(encoding="utf-8"))
            def _patch_payload(node):
                if isinstance(node, dict):
                    node_slug = ""
                    for key in ("slug", "canonical_slug", "link", "href", "url", "permalink"):
                        node_slug = _normalize_article_slug(node.get(key))
                        if node_slug:
                            break
                    ov = overrides.get(node_slug)
                    if ov:
                        for field in ("headline", "teaser", "body", "image_url", "updated", "date_modified", "meaningful_update_at"):
                            if ov.get(field):
                                node[field] = ov[field]
                        node["is_meaningful_update"] = True
                        node["update_status"] = ov.get("update_status", "resolved")
                    for value in node.values():
                        _patch_payload(value)
                elif isinstance(node, list):
                    for value in node:
                        _patch_payload(value)
            _patch_payload(data_payload)
            data_path.write_text(json.dumps(data_payload, indent=2, ensure_ascii=False), encoding="utf-8")
        except Exception:
            pass

    for slug, ov in overrides.items():
        page = root / "articles" / f"{slug}.html"
        if not page.is_file():
            continue
        text = page.read_text(encoding="utf-8")
        old_h1 = re.search(r'<h1 class="article-headline">(.*?)</h1>', text, re.S)
        old_headline = html_lib.unescape(re.sub(r'<[^>]+>', '', old_h1.group(1))) if old_h1 else ''
        headline = str(ov.get("headline") or old_headline)
        teaser = str(ov.get("teaser") or '')
        body = str(ov.get("body") or '')
        image_url = str(ov.get("image_url") or '')
        modified = str(ov.get("updated") or ov.get("date_modified") or '')
        update_label = str(ov.get("update_label") or 'UPDATE — Aug. 5, 2026, 11:44 p.m.:')
        update_text = str(ov.get("update_text") or '')
        original_label = str(ov.get("original_label") or 'Original report:')
        esc_headline = html_lib.escape(headline, quote=True)
        esc_teaser = html_lib.escape(teaser, quote=True)
        text = re.sub(r'<title>.*?</title>', f'<title>{esc_headline} | Treasure Coast Today</title>', text, count=1, flags=re.S)
        text = re.sub(r'<meta name="description" content="[^"]*">', f'<meta name="description" content="{esc_teaser}">', text, count=1)
        text = re.sub(r'<meta property="og:title" content="[^"]*">', f'<meta property="og:title" content="{esc_headline} | Treasure Coast Today">', text, count=1)
        text = re.sub(r'<meta property="og:description" content="[^"]*">', f'<meta property="og:description" content="{esc_teaser}">', text, count=1)
        if modified:
            text = re.sub(r'<meta property="article:modified_time" content="[^"]*">', f'<meta property="article:modified_time" content="{html_lib.escape(modified, quote=True)}">', text, count=1)
        text = re.sub(r'<h1 class="article-headline">.*?</h1>', f'<h1 class="article-headline">{html_lib.escape(headline)}</h1>', text, count=1, flags=re.S)
        if image_url:
            text = re.sub(r'(<figure class="article-hero-image"><img src=")[^"]+', r'\1'+image_url, text, count=1)
            text = re.sub(r'(<meta property="og:image" content=")[^"]+', r'\1'+image_url, text, count=1)
            text = re.sub(r'(<meta name="twitter:image" content=")[^"]+', r'\1'+image_url, text, count=1)
        update_html = f'<div class="article-update"><p><strong>{html_lib.escape(update_label)}</strong> {html_lib.escape(update_text)}</p></div>'
        original_html = ''.join(f'<p>{html_lib.escape(x.strip())}</p>' for x in body.split('\n\n') if x.strip())
        replacement = f'<div class="article-body">{update_html}<p><strong>{html_lib.escape(original_label)}</strong></p>{original_html}</div>'
        # Article pages may already be transformed into the membership preview/paywall
        # shell from a previous production run. Replacing only the first closing
        # ``</div>`` is not safe because the preview/paywall region contains nested
        # divs. That old behavior left the remainder of the prior body behind and
        # appended another copy on every run. Replace the complete article-content
        # region, stopping only at the stable newsletter/share boundary.
        article_region = re.compile(
            r'<div class="article-body(?:\s+[^"]*)?"[^>]*>.*?\s*'
            r'(?=(?:<aside class="newsletter-inline-slot[^>]*>.*?</aside>\s*)?'
            r'<div class="article-share">)',
            re.I | re.S,
        )
        text = article_region.sub(replacement + "\n", text, count=1)
        # JSON-LD
        m = re.search(r'<script type="application/ld\+json">(.*?)</script>', text, re.S)
        if m:
            try:
                ld=json.loads(m.group(1)); ld['headline']=headline; ld['description']=teaser
                if image_url: ld['image']=[image_url]
                if modified: ld['dateModified']=modified
                text=text[:m.start(1)]+json.dumps(ld, ensure_ascii=False)+text[m.end(1):]
            except Exception:
                pass
        page.write_text(text, encoding="utf-8")
    return changed


def _load_article_image_overrides(path=None):
    """Load deterministic, article-specific image assignments.

    These overrides are editorial authority. They are intentionally keyed by the
    canonical article slug so a future feed refresh, fallback rotation, archive
    recovery, or social-image rebuild cannot replace the selected image.
    """
    override_path = Path(path or ARTICLE_IMAGE_OVERRIDES_PATH)
    if not override_path.is_file():
        return {}
    try:
        payload = json.loads(override_path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    rows = payload.get("overrides", payload) if isinstance(payload, dict) else payload
    result = {}
    if isinstance(rows, dict):
        iterator = rows.items()
    elif isinstance(rows, list):
        iterator = ((row.get("slug") or row.get("permalink"), row) for row in rows if isinstance(row, dict))
    else:
        iterator = ()
    for raw_slug, raw_value in iterator:
        slug = _normalize_article_slug(raw_slug)
        if not slug:
            continue
        if isinstance(raw_value, str):
            image_url = raw_value
        elif isinstance(raw_value, dict):
            image_url = raw_value.get("image_url") or raw_value.get("url") or ""
        else:
            image_url = ""
        image_url = _absolute_image_url(image_url)
        if image_url and not _source_image_rejection_reason(image_url):
            result[slug] = image_url
    return result


def _article_image_override_for_item(item=None, *, slug="", overrides=None):
    article = item if isinstance(item, dict) else {}
    target_slug = _normalize_article_slug(slug)
    if not target_slug:
        for field in (
            "slug", "canonical_slug", "_archived_slug", "_resolved_permalink_slug",
            "link", "permalink", "url",
        ):
            target_slug = _normalize_article_slug(article.get(field))
            if target_slug:
                break
    mapping = overrides if isinstance(overrides, dict) else _load_article_image_overrides()
    return target_slug, str(mapping.get(target_slug) or "").strip()


def _apply_article_image_override(item, *, slug="", overrides=None):
    """Apply one editorially selected image to visible and social image fields."""
    if not isinstance(item, dict):
        return False
    target_slug, image_url = _article_image_override_for_item(
        item, slug=slug, overrides=overrides
    )
    if not target_slug or not image_url:
        return False
    changed = False
    values = {
        "image_url": image_url,
        "source_image_url": image_url,
        "image_credit": "",
        "image_source": "manual_article_image_override",
        "is_fallback_image": False,
        "rss_social_image_url": image_url,
        "rss_social_image_kind": "source",
        "rss_social_image_source": "manual_article_image_override",
        "social_image_is_source": True,
        "article_image_override": True,
    }
    for field, value in values.items():
        if item.get(field) != value:
            item[field] = value
            changed = True
    return changed


def _apply_article_image_overrides_to_archive(archive, overrides=None):
    mapping = overrides if isinstance(overrides, dict) else _load_article_image_overrides()
    changed = 0
    for row in archive or []:
        if isinstance(row, dict) and _apply_article_image_override(row, overrides=mapping):
            changed += 1
    return changed


def _apply_article_image_overrides_to_categories(all_categories, top_cat=None, overrides=None):
    mapping = overrides if isinstance(overrides, dict) else _load_article_image_overrides()
    changed = 0
    seen = set()
    categories = list(all_categories or [])
    if isinstance(top_cat, dict):
        categories.append(top_cat)
    for category in categories:
        if not isinstance(category, dict):
            continue
        for item in [category.get("hero")] + list(category.get("cards") or []):
            if not isinstance(item, dict) or id(item) in seen:
                continue
            seen.add(id(item))
            if _apply_article_image_override(item, overrides=mapping):
                changed += 1
    return changed

def _canonical_social_category_key(*values):
    """Resolve labels and keys to one stable social-image category key."""
    aliases = {
        "top news": "top_news",
        "news": "top_news",
        "local government": "local_gov",
        "crime safety": "crime",
        "crime and safety": "crime",
        "business development": "business",
        "business and development": "business",
        "sports": "sports",
        "things to do": "things_to_do",
        "florida": "florida",
        "martin county": "martin",
        "st lucie county": "st_lucie",
        "saint lucie county": "st_lucie",
        "indian river county": "indian_river",
    }
    for value in values:
        raw = str(value or "").strip()
        if raw in BRANDED_FALLBACK_IMAGE_MAP:
            return raw
        normalized = re.sub(r"[^a-z0-9]+", " ", raw.lower()).strip()
        mapped = aliases.get(normalized)
        if mapped in BRANDED_FALLBACK_IMAGE_MAP:
            return mapped
    return "top_news"


def _category_social_og_image_url(category_key):
    """Return the branded green OG card for one category.

    Social syndication must never inherit the reusable editorial photographs used to
    keep article pages visually distinct. When a story has no verified source image,
    its category OG card is the single deterministic fallback for RSS, Open Graph,
    Twitter cards, and structured data.
    """
    key = _canonical_social_category_key(category_key)
    names = BRANDED_FALLBACK_IMAGE_MAP.get(
        key, BRANDED_FALLBACK_IMAGE_MAP["top_news"]
    )
    filename = names[0] if names else BRANDED_FALLBACK_IMAGE_MAP["top_news"][0]
    return f"{SITE_URL}/{filename}"


def _social_syndication_image_url(item, category_key=""):
    """Choose the only image allowed in RSS/social metadata.

    Priority is intentionally strict:

    1. A verified real source image already attached to this exact article.
    2. The green branded category OG card.

    Managed editorial fallback photos and legacy placeholders are article-display
    assets only. They must never leak into RSS or social previews.
    """
    article = item if isinstance(item, dict) else {}
    key = _canonical_social_category_key(
        category_key, article.get("category_key"), article.get("category")
    )
    for field in ("source_image_url", "image_url"):
        candidate = _absolute_image_url(article.get(field))
        if _is_real_source_image_url(candidate):
            return candidate
    return _category_social_og_image_url(key)


def _archive_entry_for_exact_live_item(item, archive):
    """Resolve an archive row without fuzzy headline/image cross-contamination."""
    if not isinstance(item, dict) or not isinstance(archive, list):
        return None

    slug_candidates = {
        str(item.get(key) or "").strip()
        for key in (
            "_archived_slug", "slug", "_current_custom_publication_slug",
            "_resolved_permalink_slug",
        )
        if str(item.get(key) or "").strip()
    }
    if slug_candidates:
        for row in archive:
            if isinstance(row, dict) and str(row.get("slug") or "").strip() in slug_candidates:
                return row

    story_ids = {
        str(item.get(key) or "").strip()
        for key in ("editorial_story_id", "_editorial_story_id")
        if str(item.get(key) or "").strip()
    }
    if story_ids:
        matches = [
            row for row in archive
            if isinstance(row, dict)
            and str(row.get("editorial_story_id") or "").strip() in story_ids
        ]
        if len(matches) == 1:
            return matches[0]

    exact_headline = re.sub(
        r"\s+", " ", str(item.get("headline") or item.get("title") or "").strip()
    ).casefold()
    if exact_headline:
        matches = [
            row for row in archive
            if isinstance(row, dict)
            and re.sub(r"\s+", " ", str(row.get("headline") or "").strip()).casefold()
            == exact_headline
        ]
        if len(matches) == 1:
            return matches[0]
    return None


def _restore_archive_source_image(item, archive):
    """Restore a previously published source image before assigning any fallback."""
    if not isinstance(item, dict):
        return False
    current = str(item.get("image_url") or "").strip()
    if _is_real_source_image_url(current):
        return False

    row = _archive_entry_for_exact_live_item(item, archive)
    if not isinstance(row, dict):
        return False
    candidate = str(row.get("image_url") or "").strip()
    if not _is_real_source_image_url(candidate):
        return False

    item["image_url"] = candidate
    item["image_credit"] = str(row.get("image_credit") or "")
    item["image_source"] = str(row.get("image_source") or "archive_source_restore")
    item["is_fallback_image"] = False
    return True


def restore_live_source_images_from_archive(categories, archive):
    """Restore real archived source images on heroes/cards that lost image metadata."""
    restored = 0
    seen = set()
    for category in categories or []:
        if not isinstance(category, dict):
            continue
        for item in [category.get("hero")] + list(category.get("cards") or []):
            if not isinstance(item, dict) or id(item) in seen:
                continue
            seen.add(id(item))
            restored += int(_restore_archive_source_image(item, archive))
    return restored


def _replace_article_fallback_references(article_path, old_urls, new_url):
    """Replace only known fallback image references in one existing article page."""
    if not article_path.is_file() or not new_url:
        return False
    try:
        html = article_path.read_text(encoding="utf-8")
    except Exception:
        return False
    updated = html
    for old in old_urls:
        old = str(old or "").strip()
        if not old:
            continue
        updated = updated.replace(old, new_url)
        old_path = urlsplit(old).path if "://" in old else old
        if old_path:
            updated = updated.replace(old_path, urlsplit(new_url).path)
    if updated == html:
        return False
    article_path.write_text(updated, encoding="utf-8")
    return True


def repair_archive_publisher_logo_images(output_root=None):
    """Replace rejected publisher branding in archive rows and permanent pages.

    This migration does not depend on the affected story being selected live. It
    guarantees that an already-published article with a cached publisher logo is
    repaired during the next normal production run.
    """
    root = Path(output_root or OUTPUT_DIR)
    archive_path = root / "archive.json"
    articles_dir = root / "articles"
    if not archive_path.is_file():
        return {"updated": 0, "article_pages_updated": 0}

    archive = load_archive(archive_path)
    updated = 0
    article_pages_updated = 0
    for entry in archive:
        if not isinstance(entry, dict):
            continue
        if entry.get("is_custom") or entry.get("authoritative_custom"):
            continue
        old_url = str(entry.get("image_url") or "").strip()
        if not old_url:
            continue
        reason = _source_image_rejection_reason(
            old_url,
            source_url=str(entry.get("source_url") or ""),
        )
        if not reason:
            continue
        _record_source_image_rejection(
            old_url,
            reason,
            stage="archive_publisher_logo_migration",
            headline=str(entry.get("headline") or ""),
            source_url=str(entry.get("source_url") or ""),
        )
        replacement, credit = get_fallback_image(
            str(entry.get("category_key") or "local_gov"),
            str(entry.get("headline") or ""),
            item=entry,
        )
        if not replacement or replacement == old_url:
            continue
        entry["image_url"] = replacement
        entry["image_credit"] = credit
        entry["image_source"] = "publisher_logo_rejected_archive_migration"
        entry["rejected_image_url"] = old_url
        entry["image_rejection_reason"] = reason
        updated += 1
        slug = str(entry.get("slug") or "").strip()
        if slug and _replace_article_fallback_references(
            articles_dir / f"{slug}.html", [old_url], replacement
        ):
            article_pages_updated += 1

    if updated:
        archive_path.write_text(
            json.dumps(archive, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )
        print(
            "  Publisher-logo archive migration: "
            f"{updated} archive image(s) replaced; "
            f"{article_pages_updated} article page(s) updated"
        )
    return {
        "updated": updated,
        "article_pages_updated": article_pages_updated,
    }


def refresh_archive_editorial_fallbacks(output_root=None, force=False):
    """Migrate managed fallbacks once for each image-selection policy version.

    A full archive pass is necessary when the selection policy changes, but repeating
    that pass on every normal production run needlessly reopens hundreds of permanent
    pages and advances large numbers of fallback assignments. The completed policy
    version is stored with the rotation state and persisted only after all production
    gates pass.
    """
    global _EDITORIAL_IMAGE_ROTATION_DIRTY

    root = Path(output_root or OUTPUT_DIR)
    report_path = root / "data" / "editorial-image-migration.json"
    state = _load_editorial_image_rotation_state()
    completed_version = int(state.get("archive_migration_policy_version") or 0)
    if not force and completed_version >= EDITORIAL_IMAGE_SELECTION_POLICY_VERSION:
        report = {
            "schema_version": EDITORIAL_IMAGE_SCHEMA_VERSION,
            "selection_policy_version": EDITORIAL_IMAGE_SELECTION_POLICY_VERSION,
            "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "updated": 0,
            "article_pages_updated": 0,
            "skipped_custom": 0,
            "skipped": True,
            "reason": "policy-version-already-migrated",
            "updates": [],
        }
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        print(
            "  Editorial fallback migration skipped: "
            f"policy v{EDITORIAL_IMAGE_SELECTION_POLICY_VERSION} already completed"
        )
        return report

    archive_path = root / "archive.json"
    archive = load_archive(archive_path)
    if not isinstance(archive, list):
        return {
            "updated": 0,
            "article_pages_updated": 0,
            "skipped_custom": 0,
            "skipped": False,
            "reason": "archive-unavailable",
        }

    updated_rows = []
    article_pages_updated = 0
    skipped_custom = 0
    for entry in archive:
        if not isinstance(entry, dict) or not entry.get("headline") or not entry.get("slug"):
            continue
        if entry.get("is_custom") or entry.get("authoritative_custom"):
            skipped_custom += 1
            continue

        old_url = str(entry.get("image_url") or "").strip()
        is_managed_editorial = _is_managed_editorial_fallback_image(old_url)
        if (
            old_url
            and not _is_legacy_or_branded_fallback_image(old_url)
            and not is_managed_editorial
        ):
            # Real source images are authoritative and never enter fallback migration.
            continue

        category_key = str(entry.get("category_key") or "top_news")
        new_url, new_credit = get_fallback_image(
            category_key, entry.get("headline", ""), item=entry
        )
        if not new_url or new_url == old_url:
            continue

        old_candidates = [
            old_url,
            f"{SITE_URL}/og-{category_key}.png",
            f"{SITE_URL}/og-image.png",
        ]
        entry["image_url"] = new_url
        entry["image_credit"] = new_credit
        entry["image_source"] = "editorial_fallback"
        entry["is_fallback_image"] = True
        updated_rows.append({
            "slug": entry.get("slug", ""),
            "headline": entry.get("headline", ""),
            "category_key": category_key,
            "previous_image_url": old_url,
            "image_url": new_url,
        })
        article_path = root / "articles" / f"{entry['slug']}.html"
        if _replace_article_fallback_references(article_path, old_candidates, new_url):
            article_pages_updated += 1

    if updated_rows:
        temporary = archive_path.with_suffix(".json.tmp")
        temporary.write_text(
            json.dumps(archive, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        temporary.replace(archive_path)

    # Mark the policy complete in memory. The state writer commits this only after the
    # remaining publication and presentation gates pass.
    state["archive_migration_policy_version"] = EDITORIAL_IMAGE_SELECTION_POLICY_VERSION
    _EDITORIAL_IMAGE_ROTATION_DIRTY = True

    report = {
        "schema_version": EDITORIAL_IMAGE_SCHEMA_VERSION,
        "selection_policy_version": EDITORIAL_IMAGE_SELECTION_POLICY_VERSION,
        "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "updated": len(updated_rows),
        "article_pages_updated": article_pages_updated,
        "skipped_custom": skipped_custom,
        "skipped": False,
        "updates": updated_rows,
    }
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(
        json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
    )
    print(
        "  Editorial fallback migration: "
        f"{len(updated_rows)} archive record(s), "
        f"{article_pages_updated} article page(s) updated for "
        f"policy v{EDITORIAL_IMAGE_SELECTION_POLICY_VERSION}"
    )
    return report


def _save_editorial_image_rotation_state():
    """Persist rotation only after all publication and presentation gates pass."""
    global _EDITORIAL_IMAGE_ROTATION_DIRTY
    state = _load_editorial_image_rotation_state()
    assignments = state.get("story_assignments", {})
    if len(assignments) > EDITORIAL_IMAGE_MAX_ASSIGNMENTS:
        ordered = sorted(
            assignments.items(),
            key=lambda pair: str((pair[1] or {}).get("assigned_at") or ""),
            reverse=True,
        )[:EDITORIAL_IMAGE_MAX_ASSIGNMENTS]
        state["story_assignments"] = dict(ordered)
        _EDITORIAL_IMAGE_ROTATION_DIRTY = True

    EDITORIAL_IMAGE_ROTATION_PATH.parent.mkdir(parents=True, exist_ok=True)
    if _EDITORIAL_IMAGE_ROTATION_DIRTY or not EDITORIAL_IMAGE_ROTATION_PATH.exists():
        payload = {
            "schema_version": EDITORIAL_IMAGE_SCHEMA_VERSION,
            "selection_policy_version": EDITORIAL_IMAGE_SELECTION_POLICY_VERSION,
            "updated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "pool_cursors": state.get("pool_cursors", {}),
            "pool_last_image": state.get("pool_last_image", {}),
            "global_last_image": state.get("global_last_image", ""),
            "story_assignments": state.get("story_assignments", {}),
            "archive_migration_policy_version": int(
                state.get("archive_migration_policy_version") or 0
            ),
        }
        temporary = EDITORIAL_IMAGE_ROTATION_PATH.with_suffix(".json.tmp")
        temporary.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
        temporary.replace(EDITORIAL_IMAGE_ROTATION_PATH)
        _EDITORIAL_IMAGE_ROTATION_DIRTY = False

    inventory = _editorial_image_inventory()
    pool_usage = defaultdict(int)
    for row in _EDITORIAL_IMAGE_RUN_ASSIGNMENTS:
        pool_usage[row.get("pool_id", "")] += 1
    report = {
        "schema_version": EDITORIAL_IMAGE_SCHEMA_VERSION,
        "selection_policy_version": EDITORIAL_IMAGE_SELECTION_POLICY_VERSION,
        "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "editorial_image_count": inventory.get("image_count", 0),
        "pool_count": len(inventory.get("pools", {})),
        "pools": {key: len(value) for key, value in inventory.get("pools", {}).items()},
        "excluded": inventory.get("excluded", []),
        "new_assignments_this_run": len(_EDITORIAL_IMAGE_RUN_ASSIGNMENTS),
        "reused_story_assignments": max(
            0, len(_EDITORIAL_IMAGE_LAST_SELECTION) - len(_EDITORIAL_IMAGE_RUN_ASSIGNMENTS)
        ),
        "pool_usage_this_run": dict(sorted(pool_usage.items())),
        "assignments_this_run": _EDITORIAL_IMAGE_RUN_ASSIGNMENTS,
        "persistent_assignment_count": len(state.get("story_assignments", {})),
        "rotation_contract": "specific-topic-before-city-stable-per-current-pool-sequential-no-immediate-repeat",
    }
    EDITORIAL_IMAGE_REPORT_PATH.write_text(
        json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
    )
    print(
        "  Editorial image rotation saved: "
        f"{inventory.get('image_count', 0)} images across "
        f"{len(inventory.get('pools', {}))} pools; "
        f"{len(_EDITORIAL_IMAGE_RUN_ASSIGNMENTS)} new assignment(s)"
    )
    return report

def upscale_image_url(url):
    """Upscale BBC CDN images by replacing the size segment with 1024."""
    if not url or "ichef.bbci.co.uk" not in url:
        return url
    return re.sub(r"/\d{2,3}/", "/1024/", url, count=1)


def extract_image(entry):
    """Try every known location for an image in an RSS entry."""
    def valid(u):
        if not u or len(u) < 15:
            return False
        if any(x in u.lower() for x in ["1x1", "pixel", "spacer", "tracking", "data:"]):
            return False
        reason = _source_image_rejection_reason(u)
        if reason:
            _record_source_image_rejection(
                u, reason, stage="rss_image_extraction",
                headline=str(entry.get("title", "") or ""),
                source_url=str(entry.get("link", "") or ""),
            )
            return False
        return True
    for t in (getattr(entry,"media_thumbnail",None) or []):
        if isinstance(t,dict) and valid(t.get("url","")): return upscale_image_url(t["url"])
    for m in (getattr(entry,"media_content",None) or []):
        if not isinstance(m,dict): continue
        u = m.get("url","")
        if valid(u) and ("image" in m.get("type","") or any(u.lower().endswith(e) for e in (".jpg",".jpeg",".png",".webp"))): return upscale_image_url(u)
    for enc in (getattr(entry,"enclosures",None) or []):
        if isinstance(enc,dict) and "image" in enc.get("type",""):
            u = enc.get("href",enc.get("url",""))
            if valid(u): return u
    html = ""
    for field in ["description","summary"]:
        val = entry.get(field,"") or getattr(entry,field,"")
        if isinstance(val,list) and val:
            html = val[0].get("value","") if isinstance(val[0],dict) else str(val[0])
        elif isinstance(val,str):
            html = val
        if html: break
    for match in re.finditer(r'<img[^>]+src=["\']([^"\']{20,})["\']', html):
        u = match.group(1)
        if valid(u): return u
    return ""


def extract_publisher_url(entry):
    """Extract actual publisher URL from a Google News RSS entry."""
    link = entry.get("link", "") or getattr(entry, "link", "")
    if "news.google.com" not in link:
        return link
    for field in ["summary", "description"]:
        val = entry.get(field, "") or getattr(entry, field, "")
        if isinstance(val, list) and val:
            html = val[0].get("value", "") if isinstance(val[0], dict) else str(val[0])
        elif isinstance(val, str):
            html = val
        else:
            continue
        matches = re.findall(r'href=["\']?(https?://(?!news\.google)[^"\'>]+)', html)
        if matches:
            return matches[0]
    return link


def sanitize_text(text):
    if not text: return ""
    return text.replace("\\", " ").replace('"', "'").replace("\n", " ").replace("\r", " ").replace("\t", " ").strip()



def fetch_og_image(url, headline=""):
    """Return a story-specific social image while rejecting publisher branding.

    News sites sometimes expose their masthead or station logo as ``og:image``.
    Candidate URLs, image-alt metadata, and declared dimensions are validated before
    acceptance. When the primary Open Graph image is branding, a valid Twitter image
    can still be used. Returns ``""`` on failure or when every candidate is rejected.
    """
    if not url:
        return ""
    try:
        from urllib.parse import urljoin
        import re as _re_og

        resp = requests.get(
            url,
            timeout=10,
            headers={"User-Agent": "Mozilla/5.0 (compatible; TCTBot/1.0)"},
        )
        if resp.status_code != 200:
            return ""
        page = resp.text[:200000]

        def _meta_values(key, attr="property"):
            patterns = [
                rf'<meta[^>]+{attr}=["\']{_re_og.escape(key)}["\'][^>]+content=["\']([^"\']+)',
                rf'<meta[^>]+content=["\']([^"\']+)["\'][^>]+{attr}=["\']{_re_og.escape(key)}["\']',
            ]
            values = []
            for pattern in patterns:
                values.extend(_re_og.findall(pattern, page, _re_og.IGNORECASE))
            return [html_lib.unescape(str(value).strip()) for value in values if str(value).strip()]

        width_values = _meta_values("og:image:width")
        height_values = _meta_values("og:image:height")
        og_alt_text = " ".join(_meta_values("og:image:alt"))
        twitter_alt_text = " ".join(_meta_values("twitter:image:alt", "name"))
        width = width_values[0] if width_values else None
        height = height_values[0] if height_values else None

        candidates = []
        candidates.extend((candidate, "og:image") for candidate in _meta_values("og:image"))
        candidates.extend((candidate, "twitter:image") for candidate in _meta_values("twitter:image", "name"))
        seen = set()
        for candidate, source in candidates:
            image_url = urljoin(url, candidate)
            if image_url in seen:
                continue
            seen.add(image_url)
            reason = _source_image_rejection_reason(
                image_url,
                source_url=url,
                alt_text=og_alt_text if source == "og:image" else twitter_alt_text,
                width=width if source == "og:image" else None,
                height=height if source == "og:image" else None,
            )
            if reason:
                _record_source_image_rejection(
                    image_url,
                    reason,
                    stage="og_image_fetch",
                    headline=headline,
                    source_url=url,
                )
                continue
            return image_url
        return ""
    except Exception:
        return ""



_EVENT_LINK_CACHE = {}


def _event_link_root_host(host):
    host = (host or "").lower().split(":", 1)[0].strip(".")
    parts = [p for p in host.split(".") if p]
    return ".".join(parts[-2:]) if len(parts) >= 2 else host


def find_official_event_link(source_url, headline=""):
    """Find a high-confidence official event/ticket/registration link in a source page.

    The source article itself is never returned. Only real hrefs present on that page
    are considered; no URL is guessed or fabricated. Low-confidence results are omitted.
    """
    if not source_url or not source_url.startswith("http"):
        return "", ""
    cache_key = (source_url, headline)
    if cache_key in _EVENT_LINK_CACHE:
        return _EVENT_LINK_CACHE[cache_key]

    try:
        from urllib.parse import urljoin, urlparse, parse_qs, unquote
        import html as _html

        resp = requests.get(
            source_url,
            timeout=10,
            headers={"User-Agent": "Mozilla/5.0 (compatible; TCTBot/1.0)"},
        )
        if resp.status_code != 200:
            _EVENT_LINK_CACHE[cache_key] = ("", "")
            return "", ""

        source_host = urlparse(source_url).netloc.lower().replace("www.", "")
        source_root = _event_link_root_host(source_host)
        page = resp.text[:600000]
        candidates = []
        stops = {
            "this", "that", "with", "from", "will", "your", "about", "event",
            "events", "week", "weekend", "local", "florida", "treasure", "coast",
        }
        headline_tokens = {
            w for w in re.findall(r"[a-z0-9]+", (headline or "").lower())
            if len(w) >= 5 and w not in stops
        }
        blocked_hosts = {
            "facebook.com", "instagram.com", "twitter.com", "x.com", "youtube.com",
            "linkedin.com", "tiktok.com", "pinterest.com", "google.com", "apple.com",
        }
        preferred_hosts = {
            "eventbrite.com", "ticketmaster.com", "tickets.com", "etix.com",
            "showclix.com", "universe.com", "simpletix.com", "humanitix.com",
        }

        anchor_pattern = r"<a\b[^>]*?href=[\"']([^\"']+)[\"'][^>]*>(.*?)</a>"
        for match in re.finditer(anchor_pattern, page, re.IGNORECASE | re.DOTALL):
            href = _html.unescape(match.group(1).strip())
            anchor_html = match.group(2)
            anchor = _html.unescape(re.sub(r"<[^>]+>", " ", anchor_html))
            anchor = re.sub(r"\s+", " ", anchor).strip()
            if not href or href.startswith(("#", "mailto:", "tel:", "javascript:")):
                continue

            url = urljoin(source_url, href)
            parsed = urlparse(url)
            host = parsed.netloc.lower().replace("www.", "")
            if _event_link_root_host(host) == source_root:
                query = parse_qs(parsed.query)
                redirect_value = ""
                for key in ("url", "u", "target", "redirect", "destination"):
                    vals = query.get(key)
                    if vals and vals[0].startswith("http"):
                        redirect_value = unquote(vals[0])
                        break
                if redirect_value:
                    url = redirect_value
                    parsed = urlparse(url)
                    host = parsed.netloc.lower().replace("www.", "")

            root = _event_link_root_host(host)
            if not host or root == source_root:
                continue
            if any(root == b or root.endswith("." + b) for b in blocked_hosts):
                continue
            lower_url = url.lower()
            lower_anchor = anchor.lower()
            if any(x in lower_url for x in (
                "/privacy", "/terms", "/contact", "/advertis", "/author/",
                "doubleclick", "googlesyndication", "utm_source=syndication",
            )):
                continue

            score = 0
            if root in preferred_hosts:
                score += 7
            if host.endswith(".gov") or root.endswith(".gov"):
                score += 5
            elif host.endswith(".org") or root.endswith(".org"):
                score += 3

            if any(term in lower_anchor for term in (
                "official event", "event website", "official website", "visit website",
            )):
                score += 8
            if any(term in lower_anchor for term in (
                "buy tickets", "get tickets", "tickets", "register", "registration",
                "rsvp", "reserve", "sign up",
            )):
                score += 7
            if any(term in lower_anchor for term in (
                "event details", "more information", "learn more", "full schedule",
                "event page", "festival website", "details here",
            )):
                score += 5

            candidate_tokens = set(re.findall(r"[a-z0-9]+", (anchor + " " + url).lower()))
            overlap = len(headline_tokens & candidate_tokens)
            score += min(overlap, 4)

            if score >= 7:
                label = anchor if 3 <= len(anchor) <= 80 else "Visit the official event page"
                if lower_anchor in {"click here", "here", "website", "learn more"}:
                    label = "Visit the official event page"
                candidates.append((score, url, label))

        if candidates:
            candidates.sort(key=lambda x: x[0], reverse=True)
            _, url, label = candidates[0]
            result = (url, label)
        else:
            result = ("", "")
    except Exception:
        result = ("", "")

    _EVENT_LINK_CACHE[cache_key] = result
    return result


FEED_PREFETCH_WORKERS = 16
FEED_CONNECT_TIMEOUT_SECONDS = 3.05
FEED_READ_TIMEOUT_SECONDS = 8
FEED_USER_AGENT = "TreasureCoastToday/1.0 (+https://treasurecoast.today)"


def _empty_feed_document():
    return feedparser.parse(b"")


def _fetch_feed_document(url):
    """Download one RSS document with explicit network bounds.

    ``feedparser.parse(url)`` can block for minutes on a slow or half-open server.
    Requests provides deterministic connect/read timeouts, and parsing bytes keeps
    every feed fetch inside the same bounded concurrent prefetch stage.
    """
    try:
        response = requests.get(
            url,
            headers={"User-Agent": FEED_USER_AGENT, "Accept": "application/rss+xml, application/xml, text/xml, */*"},
            timeout=(FEED_CONNECT_TIMEOUT_SECONDS, FEED_READ_TIMEOUT_SECONDS),
        )
        response.raise_for_status()
        return feedparser.parse(response.content)
    except Exception as exc:
        print(f"  Feed error ({url[:60]}): {exc}")
        return _empty_feed_document()


def _prefetch_feed_documents(urls):
    """Fetch all unique RSS documents once, concurrently and with hard timeouts."""
    ordered_urls = sorted({str(url).strip() for url in urls if str(url).strip()})
    documents = {url: _empty_feed_document() for url in ordered_urls}
    if not ordered_urls:
        return documents
    with ThreadPoolExecutor(max_workers=min(FEED_PREFETCH_WORKERS, len(ordered_urls))) as executor:
        future_to_url = {executor.submit(_fetch_feed_document, url): url for url in ordered_urls}
        for future in as_completed(future_to_url):
            url = future_to_url[future]
            try:
                documents[url] = future.result()
            except Exception as exc:
                print(f"  Feed worker error ({url[:60]}): {exc}")
    return documents


def build_image_bank(feed_documents=None):
    """Build the image bank from already-prefetched RSS documents."""
    bank = []
    feed_documents = feed_documents or {}
    for url in IMAGE_BANK_FEEDS:
        try:
            feed = feed_documents[url] if url in feed_documents else _fetch_feed_document(url)
            for entry in getattr(feed, "entries", [])[:60]:
                title = entry.get("title", "").strip()
                link = extract_publisher_url(entry)
                if _is_excluded_source_entry(entry, title=title, link=link):
                    continue
                img = extract_image(entry)
                if title and img:
                    bank.append({"title": title, "image_url": img, "source": url})
        except Exception as e:
            print(f"  Image bank feed error ({url[:50]}): {e}")
    print(f"  Image bank built: {len(bank)} entries with images")
    return bank


def match_image(headline, image_bank, cat_key="", used_images=None):
    """Fuzzy-match a headline against the image bank with geographic and category conflict detection."""
    used_images = used_images or set()
    stops = {"that","this","with","from","have","been","after","over","into","says","said","will","than","more","also","when","were","they","their","about"}
    geo_words = {"ukraine","ukrainian","russia","russian","china","chinese","israel","israeli","gaza","iran","iranian",
                 "france","french","germany","german","australia","australian","india","indian","pakistan","pakistani",
                 "korea","korean","japan","japanese","mexico","mexican","brazil","brazilian","cuba","cuban"}

    # Category-to-source mapping — prevent cross-category image mismatches
    cat_source_hints = {
        "sports":       ["sport", "espn"],
        "crime":        ["police", "sheriff", "crime"],
        "local_gov":    ["commission", "council", "government"],
    }
    # Sources that should NOT be used for certain categories
    cat_source_blocks = {
        "local_gov":    [],
        "crime":        [],
        "business":     [],
        "sports":       [],
        "things_to_do": [],
        "florida":      [],
        "martin":       [],
        "st_lucie":     [],
        "indian_river": [],
    }

    def tokens(text):
        return set(w.lower().strip(".,;:()") for w in text.split() if len(w) > 3 and w.lower() not in stops)

    hw = tokens(headline)
    hl_geo = hw & geo_words
    blocked_sources = cat_source_blocks.get(cat_key, [])
    best_score, best_img, best_credit = 0, "", ""

    for entry in image_bank:
        img_url = entry.get("image_url", "")
        if canonical_image_url(img_url) in used_images:
            continue
        source = entry.get("source", "").lower()
        # Block sports images on non-sports categories
        if any(b in source for b in blocked_sources):
            continue
        entry_tokens = tokens(entry["title"])
        overlap = len(hw & entry_tokens)
        if overlap > best_score and overlap >= 3:
            entry_geo = entry_tokens & geo_words
            if hl_geo and entry_geo and not (hl_geo & entry_geo):
                continue
            best_score   = overlap
            best_img     = upscale_image_url(entry["image_url"])
            best_credit  = get_image_credit(entry.get("source", ""))

    # Fallback pass: if no 3-token match, try distinctive long tokens (>=6 chars).
    # Two shared distinctive terms (e.g. "longview"+"mill", "frankie"+"valli") are a
    # confident match even when the rewritten headline shares few common words.
    if not best_img:
        distinctive = {w for w in hw if len(w) >= 7}
        if distinctive:
            for entry in image_bank:
                source = entry.get("source", "").lower()
                if any(b in source for b in blocked_sources):
                    continue
                entry_tokens = {w for w in tokens(entry["title"]) if len(w) >= 7}
                overlap = len(distinctive & entry_tokens)
                if overlap > best_score and overlap >= 3:
                    entry_geo = tokens(entry["title"]) & geo_words
                    if hl_geo and entry_geo and not (hl_geo & entry_geo):
                        continue
                    best_score  = overlap
                    best_img    = upscale_image_url(entry["image_url"])
                    best_credit = get_image_credit(entry.get("source", ""))

    return best_img, best_credit


PLACEHOLDER_URL_PATTERNS = [
    "brand-icons", "brand_icons",
    "default-image", "default_image", "defaultimage",
    "top_image", "top-image",
    "htv_default", "htv-default",
    "news-slate", "news_slate",
    "og-image.png", "og_image.png",
    "eenewslogo", "site-logo", "site_logo",
    "station-logo", "stationlogo",
    "publisher-logo", "publisher_logo",
    "header-logo", "header_logo",
    "masthead-logo", "masthead_logo",
    "favicon", "apple-touch-icon",
    "wpec-16x9",
    "aolfp/images", "cbsnewsstatic.com/hub",
    "yimg.com/cv/apiv2",
    "foxtv.com/img",
    "gray.tv/gray/arc-fusion-assets",
    "townnews.com/content/tncms/custom",
    "/content/tncms/custom/",
]

_SOURCE_IMAGE_REJECTIONS = []
_SOURCE_IMAGE_REJECTION_KEYS = set()


def _coerce_image_dimension(value):
    try:
        return int(float(str(value or "").strip()))
    except Exception:
        return 0


def _source_image_rejection_reason(
    img_url, *, source_url="", alt_text="", width=None, height=None
):
    """Return a deterministic rejection reason for branding/non-story imagery."""
    raw = html_lib.unescape(str(img_url or "").strip())
    if not raw:
        return "missing_image_url"
    if raw.startswith("//"):
        raw = "https:" + raw
    if not raw.startswith(("http://", "https://", "/")):
        return "invalid_image_url"

    parsed = urlsplit(raw)
    host = parsed.netloc.lower()
    path = parsed.path.lower()
    blob = f"{host}{path}".lower()

    # TCT-managed editorial and user-supplied assets are not publisher branding.
    if host and "treasurecoast.today" in host:
        if _is_managed_editorial_fallback_image(raw):
            return ""
        if not _is_legacy_or_branded_fallback_image(raw):
            return ""

    if any(pattern in blob for pattern in PLACEHOLDER_URL_PATTERNS):
        return "publisher_logo_or_placeholder_url"

    filename_tokens = re.split(r"[/_.?=&%+-]+", blob)
    branding_tokens = {
        "logo", "logotype", "wordmark", "masthead", "brandmark",
        "siteicon", "stationlogo", "publisherlogo", "favicon",
    }
    if branding_tokens.intersection(filename_tokens):
        return "publisher_logo_url_token"

    alt = re.sub(r"\s+", " ", str(alt_text or "").strip().lower())
    if re.search(r"\b(?:logo|logotype|wordmark|masthead|brand mark|site icon)\b", alt):
        return "publisher_logo_alt_text"

    w = _coerce_image_dimension(width)
    h = _coerce_image_dimension(height)
    if w and h:
        ratio = w / max(h, 1)
        if w < 400 or h < 200:
            return "undersized_social_image"
        if ratio > 3.2 or ratio < 0.32:
            return "publisher_logo_aspect_ratio"

    return ""


def _record_source_image_rejection(
    img_url, reason, *, stage="", headline="", source_url=""
):
    key = (str(img_url or ""), str(reason or ""), str(stage or ""), str(headline or ""))
    if key in _SOURCE_IMAGE_REJECTION_KEYS:
        return
    _SOURCE_IMAGE_REJECTION_KEYS.add(key)
    _SOURCE_IMAGE_REJECTIONS.append({
        "image_url": str(img_url or ""),
        "reason": str(reason or ""),
        "stage": str(stage or ""),
        "headline": str(headline or ""),
        "source_url": str(source_url or ""),
    })


def is_placeholder_image(img_url):
    return bool(_source_image_rejection_reason(img_url))


def _sanitize_publisher_logo_image(item, *, stage="live_item"):
    if not isinstance(item, dict):
        return False
    if item.get("is_custom") or item.get("authoritative_custom"):
        return False
    image_url = str(item.get("image_url") or "").strip()
    if not image_url:
        return False
    reason = _source_image_rejection_reason(
        image_url,
        source_url=str(item.get("source_url") or item.get("link") or ""),
        alt_text=str(item.get("image_alt") or ""),
    )
    if not reason:
        return False
    _record_source_image_rejection(
        image_url,
        reason,
        stage=stage,
        headline=str(item.get("headline") or item.get("title") or ""),
        source_url=str(item.get("source_url") or item.get("link") or ""),
    )
    item["rejected_image_url"] = image_url
    item["image_rejection_reason"] = reason
    item["image_url"] = ""
    item["image_credit"] = ""
    item["image_source"] = "publisher_logo_rejected"
    item["is_fallback_image"] = False
    return True


def _sanitize_category_source_images(category, *, stage="category"):
    rejected = 0
    if not isinstance(category, dict):
        return rejected
    for item in [category.get("hero")] + list(category.get("cards") or []):
        rejected += int(_sanitize_publisher_logo_image(item, stage=stage))
    return rejected


def _write_source_image_quality_report(output_path=None):
    path = Path(output_path or SOURCE_IMAGE_QUALITY_REPORT_PATH)
    path.parent.mkdir(parents=True, exist_ok=True)
    reason_counts = defaultdict(int)
    stage_counts = defaultdict(int)
    for row in _SOURCE_IMAGE_REJECTIONS:
        reason_counts[row.get("reason", "unknown")] += 1
        stage_counts[row.get("stage", "unknown")] += 1
    report = {
        "schema_version": 1,
        "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "rejected_count": len(_SOURCE_IMAGE_REJECTIONS),
        "reason_counts": dict(sorted(reason_counts.items())),
        "stage_counts": dict(sorted(stage_counts.items())),
        "rejections": _SOURCE_IMAGE_REJECTIONS,
    }
    path.write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
    return report


def find_image(headline, entries):
    """Match headline back to RSS entry for image, link, and publish time."""
    h = headline.lower()[:50]
    for entry in entries:
        t = entry.get("title", "").lower()[:50]
        if h in t or t in h:
            return {
                "image_url": entry.get("image_url", ""),
                "link":      entry.get("link", ""),
                "published": entry.get("published", ""),
            }
    return {"image_url": "", "link": "", "published": ""}


def _trusted_publisher_identity(entry, title=""):
    """Return normalized publisher name and allowed domains for a trusted RSS item."""
    values = []
    source = entry.get("source", {}) if isinstance(entry, dict) else {}
    if isinstance(source, dict):
        values.extend([source.get("title", ""), source.get("href", "")])
    elif source:
        values.append(str(source))
    title = str(title or entry.get("title", "") or "")
    if " - " in title:
        values.append(title.rsplit(" - ", 1)[-1])
    blob = " ".join(str(v or "") for v in values).lower()
    for publisher, domains in TRUSTED_AGGREGATOR_PUBLISHERS.items():
        if publisher in blob or any(domain in blob for domain in domains):
            return publisher, tuple(domains)
    return "", ()


def _google_news_resolution_cache_key(url):
    return _cache_hash({"google_news_url": _normalize_cache_url(url), "resolver": "batchexecute-v1"})


def _google_news_token(url):
    try:
        path = urlsplit(str(url or "")).path
    except Exception:
        return ""
    match = re.search(r"/(?:rss/)?articles/([^/?#]+)", path)
    return match.group(1) if match else ""


def _extract_google_rpc_url(text):
    """Extract the publisher URL from a Google News batchexecute response."""
    raw = str(text or "")
    # Normal response: JSON appears after an anti-XSSI prefix and blank line. The
    # third value contains another JSON string: ["garturlres", "https://..."]
    for chunk in reversed([part.strip() for part in raw.split("\n\n") if part.strip()]):
        try:
            payload = json.loads(chunk)
        except Exception:
            continue
        stack = [payload]
        while stack:
            value = stack.pop()
            if isinstance(value, list):
                if len(value) >= 3 and isinstance(value[2], str):
                    try:
                        inner = json.loads(value[2])
                    except Exception:
                        inner = None
                    if (
                        isinstance(inner, list) and len(inner) >= 2
                        and inner[0] == "garturlres"
                        and str(inner[1]).startswith("http")
                    ):
                        return html_lib.unescape(str(inner[1]))
                stack.extend(value)
            elif isinstance(value, dict):
                stack.extend(value.values())
    # Defensive fallback for slightly different RPC framing.
    match = re.search(r'\\?"garturlres\\?"\s*,\s*\\?"(https?[^"\\]+(?:\\.[^"\\]*)*)', raw)
    if not match:
        return ""
    candidate = match.group(1).replace(r"\/", "/").replace(r"\u0026", "&")
    return html_lib.unescape(candidate)


def resolve_google_news_url(url, expected_domains=()):
    """Resolve a modern Google News RSS wrapper to its original publisher URL.

    Positive results are cached for seven days. Negative results use a short cache so
    a transient Google response cannot permanently hide an important local story.
    """
    raw_url = str(url or "").strip()
    if "news.google.com" not in raw_url:
        return raw_url
    cache_key = _google_news_resolution_cache_key(raw_url)
    cached = GENERATION_CACHE.get("source_resolutions", cache_key)
    if cached is not _CACHE_MISS:
        return str((cached or {}).get("resolved_url", ""))
    token = _google_news_token(raw_url)
    if not token:
        GENERATION_CACHE.put("source_resolutions", cache_key, {"resolved_url": "", "reason": "missing_token"}, ttl_seconds=7200)
        return ""
    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; TCTBot/1.0; +https://treasurecoast.today)",
        "Accept-Language": "en-US,en;q=0.9",
    }
    try:
        landing = requests.get(
            f"https://news.google.com/rss/articles/{token}",
            timeout=6,
            headers=headers,
            allow_redirects=True,
        )
        # Older wrappers may redirect directly to the publisher.
        direct = str(getattr(landing, "url", "") or "")
        if direct and "news.google.com" not in direct:
            resolved = direct
        else:
            body = str(getattr(landing, "text", "") or "")
            sig = re.search(r'data-n-a-sg=["\']([^"\']+)', body)
            ts = re.search(r'data-n-a-ts=["\']([^"\']+)', body)
            if not sig or not ts:
                raise ValueError("google_resolution_metadata_missing")
            inner = (
                '["garturlreq",[["X","X",["X","X"],null,null,1,1,'
                '"US:en",null,1,null,null,null,null,null,0,1],"X","X",1,'
                f'[1,1,1],1,1,null,0,0,null,0],"{token}",{ts.group(1)},'
                f'"{sig.group(1)}"]'
            )
            payload = ["Fbv4je", inner]
            rpc = requests.post(
                "https://news.google.com/_/DotsSplashUi/data/batchexecute",
                timeout=6,
                headers={**headers, "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8"},
                data=f"f.req={quote(json.dumps([[payload]]))}",
            )
            resolved = _extract_google_rpc_url(getattr(rpc, "text", ""))
        domain = get_domain(resolved)
        allowed = tuple(str(d).lower() for d in expected_domains if d)
        if not resolved or "news.google.com" in domain:
            raise ValueError("publisher_url_not_resolved")
        if allowed and not any(domain == d or domain.endswith("." + d) for d in allowed):
            raise ValueError(f"resolved_domain_not_trusted:{domain}")
        GENERATION_CACHE.put(
            "source_resolutions", cache_key,
            {"resolved_url": resolved, "domain": domain}, ttl_seconds=7 * 86400,
        )
        return resolved
    except Exception as exc:
        GENERATION_CACHE.put(
            "source_resolutions", cache_key,
            {"resolved_url": "", "reason": str(exc)[:180]}, ttl_seconds=7200,
        )
        return ""


def _record_trusted_source_recovery(row):
    with TRUSTED_SOURCE_RECOVERY_LOCK:
        TRUSTED_SOURCE_RECOVERY_ROWS.append(copy.deepcopy(row))


def write_trusted_source_recovery_report(output_path=None):
    path = Path(output_path or TRUSTED_SOURCE_RECOVERY_REPORT_PATH)
    with TRUSTED_SOURCE_RECOVERY_LOCK:
        rows = copy.deepcopy(TRUSTED_SOURCE_RECOVERY_ROWS)
    recovered = sum(1 for row in rows if row.get("result") == "recovered")
    report = {
        "schema_version": 1,
        "generated_at": _utc_now_iso(),
        "attempted": len(rows),
        "recovered": recovered,
        "failed": len(rows) - recovered,
        "rows": rows,
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"  Trusted source recovery: {recovered}/{len(rows)} resolved to usable publisher pages")
    return report


def extract_publisher_url(entry):
    """Extract actual publisher URL from a Google News RSS entry.
    Google News embeds the publisher URL as an href in the description HTML.
    Falls back to entry link for non-Google feeds.
    """
    link = entry.get("link", "")
    if "news.google.com" not in link:
        return link  # Already a direct publisher URL
    desc = entry.get("summary", entry.get("description", ""))
    if isinstance(desc, list):
        desc = desc[0].get("value", "") if desc else ""
    matches = re.findall(r'href="(https?://(?!news\.google)[^"]+)"', desc)
    if matches:
        return matches[0]
    return link


def sanitize_text(text):
    """Remove characters that break JSON parsing."""
    if not text:
        return ""
    return text.replace("\\", " ").replace('"', "'").replace("\n", " ").replace("\r", " ").replace("\t", " ").strip()



def get_domain(url):
    """Return a normalized domain for source classification."""
    try:
        from urllib.parse import urlparse
        return urlparse(url).netloc.lower().replace("www.", "")
    except Exception:
        return ""


def _is_excluded_source_entry(entry, title="", link=""):
    """Return True for publishers TCT has intentionally retired from ingestion.

    Check direct publisher URLs plus Google News ``source`` metadata / terminal
    publisher suffixes. Do not scan article body text, where a blocked publisher
    could be mentioned incidentally.
    """
    entry = entry if isinstance(entry, dict) else {}
    urls = [str(link or ""), str(entry.get("link") or "")]
    labels = []
    source = entry.get("source", {})
    if isinstance(source, dict):
        urls.append(str(source.get("href") or ""))
        labels.append(str(source.get("title") or ""))
    elif source:
        labels.append(str(source))

    rendered_title = str(title or entry.get("title") or "")
    if " - " in rendered_title:
        labels.append(rendered_title.rsplit(" - ", 1)[-1])

    for value in urls:
        domain = get_domain(value)
        if any(domain == blocked or domain.endswith("." + blocked) for blocked in EXCLUDED_SOURCE_DOMAINS):
            return True

    normalized_labels = [re.sub(r"\s+", " ", label).strip().casefold() for label in labels if label]
    for label in normalized_labels:
        if any(marker in label for marker in EXCLUDED_SOURCE_PUBLISHER_MARKERS):
            return True
    return False


def classify_source(link):
    """Classify a source so the writer knows whether it has usable body text."""
    domain = get_domain(link)
    if any(d in domain for d in THIN_SOURCE_DOMAINS):
        return "discovery_only"
    if any(d in domain for d in FULL_TEXT_DOMAINS):
        return "full_source"
    if "news.google.com" in domain or "yahoo.com" in domain:
        return "aggregator"
    return "unknown"


def extract_rss_text(entry):
    """Prefer the richest text field in an RSS entry."""
    best = ""
    for field in ["content", "summary", "description"]:
        val = entry.get(field, "") or getattr(entry, field, "")
        if isinstance(val, list) and val:
            candidate = val[0].get("value", "") if isinstance(val[0], dict) else str(val[0])
        elif isinstance(val, str):
            candidate = val
        else:
            candidate = ""
        candidate = clean_summary(candidate)
        if len(candidate) > len(best):
            best = candidate
    return best


def clean_summary(text):
    """Strip navigation text, bylines, HTML tags, and noise from RSS summaries."""
    if not text:
        return ""
    import re as _re
    # Remove HTML tags
    text = _re.sub(r"<[^>]+>", " ", text)
    # Remove URLs
    text = _re.sub(r"https?://\S+", "", text)
    # Remove common RSS noise patterns
    noise_patterns = [
        r"(?i)read more.*$",
        r"(?i)click here.*$",
        r"(?i)continue reading.*$",
        r"(?i)\[\+\d+ chars\].*$",
        r"(?i)^by [A-Z][a-z]+ [A-Z][a-z]+",
        r"(?i)related articles?:.*$",
        r"(?i)also read:.*$",
        r"(?i)share this:.*$",
        r"(?i)follow us.*$",
        r"&amp;|&lt;|&gt;|&quot;|&#\d+;",
    ]
    for pattern in noise_patterns:
        text = _re.sub(pattern, "", text, flags=_re.MULTILINE)
    # Remove characters that break JSON parsing
    text = text.replace("\\", " ").replace('"', "'").replace("\n", " ").replace("\r", " ").replace("\t", " ")
    # Collapse whitespace
    text = _re.sub(r"\s+", " ", text).strip()
    return text


_OBITUARY_LISTING_STRONG_SIGNALS = [
    "funeral home", "funeral and cremation", "funeral & cremation",
    "cremation service", "cremation services", "in lieu of flowers",
    "celebration of life", "laid to rest", "visitation will",
    "services are being handled", "services being handled",
    "arrangements by", "arrangements are", "arrangements entrusted",
    "passed away peacefully", "entered into rest", "went to be with the lord",
]

def _looks_like_obituary_listing(title, text):
    """Distinguish obituary listings from reported news about a person's death.

    A reported death may legitimately say someone is survived by family. That phrase
    alone must never suppress a public-safety or public-service news story.
    """
    title_blob = str(title or "").lower()
    body_blob = str(text or "").lower()
    if re.search(r"\bobituar(?:y|ies)\b", title_blob):
        return True
    strong_hits = sum(1 for signal in _OBITUARY_LISTING_STRONG_SIGNALS if signal in body_blob)
    if strong_hits >= 2:
        return True
    if strong_hits >= 1 and ("survived by" in body_blob or "passed away" in body_blob):
        return True
    return False


def fetch_headlines(feeds, limit=HEADLINES_PER_CATEGORY, feed_cache=None):
    """Pull headlines, dedupe, fetch usable full article text for open sources, then limit."""

    def fetch_one_feed(url):
        # Use cache if available
        if feed_cache is not None and url in feed_cache:
            return url, feed_cache[url]
        try:
            import socket
            old_timeout = socket.getdefaulttimeout()
            socket.setdefaulttimeout(8)
            feed = feedparser.parse(url)
            socket.setdefaulttimeout(old_timeout)
            return url, feed.entries
        except Exception as e:
            print(f"  Feed error ({url[:60]}): {e}")
            return url, []

    # Fetch all feeds in parallel — a slow/blocked feed won't stall the others
    feed_results = []
    with ThreadPoolExecutor(max_workers=6) as ex:
        futures = {ex.submit(fetch_one_feed, url): url for url in feeds}
        try:
            for fut in as_completed(futures, timeout=25):
                try:
                    url, feed_entries = fut.result(timeout=10)
                    feed_results.append((url, feed_entries))
                except Exception as e:
                    print(f"  Feed timeout ({futures[fut][:60]}): {e}")
        except (FuturesTimeoutError, TimeoutError):
            for f in futures:
                f.cancel()

    seen, entries = set(), []
    excluded_source_count = 0

    # Obituary listings are excluded, but reported deaths remain eligible. A phrase
    # such as "survived by" alone is common in legitimate news coverage and is not
    # enough to classify an item as an obituary.
    def _is_obituary(title, summary):
        return _looks_like_obituary_listing(title, summary)

    for url, feed_entries in feed_results:
        try:
            for entry in feed_entries[:15]:
                title = sanitize_text(entry.get("title", "").strip())
                if not title:
                    continue

                raw_link = entry.get("link", "") or getattr(entry, "link", "")
                link = extract_publisher_url(entry)
                if _is_excluded_source_entry(entry, title=title, link=link):
                    excluded_source_count += 1
                    continue
                if title.lower() in seen:
                    continue
                seen.add(title.lower())

                summary = extract_rss_text(entry)[:2500]
                publisher_name, publisher_domains = _trusted_publisher_identity(entry, title)

                # Skip obituaries entirely
                if _is_obituary(title, summary):
                    continue

                source_type = classify_source(link)

                entries.append({
                    "title":       title,
                    "summary":     summary,
                    "link":        link,
                    "aggregator_url": raw_link if "news.google.com" in str(raw_link) else "",
                    "publisher_name": publisher_name,
                    "publisher_domains": list(publisher_domains),
                    "feed_url":    url,
                    "source_type": source_type,
                    "source_quality": "unclassified",
                    "image_url":   extract_image(entry),
                    "published":   entry.get("published", "") or entry.get("updated", ""),
                })
        except Exception as e:
            print(f"  Feed error ({url[:60]}): {e}")

    if excluded_source_count:
        print(f"  Source policy excluded {excluded_source_count} Hometown News item(s)")


    # Sort by published date (freshest first), then fetch bodies for the candidate pool.
    def pub_sort(h):
        try:
            from email.utils import parsedate_to_datetime
            from datetime import timezone
            return parsedate_to_datetime(h["published"]).astimezone(timezone.utc).timestamp()
        except Exception:
            return 0

    entries.sort(key=pub_sort, reverse=True)
    result = list(entries[:limit])
    # A busy broad feed can push a locally important trusted-publisher discovery just
    # below the ordinary per-category cap. Give up to six additional local aggregator
    # discoveries a recovery chance before the later category filter selects its final
    # twelve. This does not promote them automatically; they still must resolve and
    # pass the unchanged source-depth and category gates.
    for candidate in entries[limit:limit + 30]:
        if len(result) >= limit + 6:
            break
        if (
            candidate.get("source_type") == "aggregator"
            and candidate.get("publisher_name")
            and _has_treasure_coast_locality(candidate)
        ):
            result.append(candidate)

    def enrich_one(h):
        link = h.get("link", "")
        summary_words = len((h.get("summary") or "").split())

        # Never try to turn paywalled/discovery sources into full articles.
        if h.get("source_type") == "discovery_only":
            h["source_quality"] = "discovery_only"
            return h

        # Trusted local Google News discoveries get one bounded publisher recovery
        # attempt. The normal source-depth gate remains unchanged; we publish only
        # when the resolved source yields enough verified text.
        if h.get("source_type") == "aggregator":
            publisher = str(h.get("publisher_name") or "")
            domains = tuple(h.get("publisher_domains") or ())
            local = _has_treasure_coast_locality(h)
            recovery_row = {
                "headline": h.get("title", ""),
                "publisher": publisher,
                "aggregator_url": h.get("aggregator_url") or link,
                "expected_domains": list(domains),
                "locality_confirmed": bool(local),
                "result": "not_attempted",
                "resolved_url": "",
                "source_word_count": 0,
                "reason": "",
            }
            if publisher and domains and local:
                resolved = resolve_google_news_url(h.get("aggregator_url") or link, domains)
                recovery_row["resolved_url"] = resolved
                if resolved:
                    full = fetch_article_text(resolved, max_words=2500, content_hint=_source_content_hint(h))
                    raw_words = _word_count(full)
                    focused = _focus_extracted_source_text(full, h)
                    words = _word_count(focused)
                    if focused != full:
                        h["source_focus_repaired"] = True
                        h["source_focus_original_word_count"] = raw_words
                        h["source_focus_word_count"] = words
                        full = focused
                    recovery_row["source_word_count"] = words
                    if words >= MIN_SOURCE_WORDS:
                        h["aggregator_url"] = h.get("aggregator_url") or link
                        h["link"] = resolved
                        h["source_url"] = resolved
                        h["source_type"] = classify_source(resolved)
                        h["article_text"] = full
                        h["source_quality"] = "full" if words >= 140 else "summary"
                        h["source_recovery_status"] = "recovered"
                        recovery_row["result"] = "recovered"
                        _record_trusted_source_recovery(recovery_row)
                        return h
                    recovery_row["result"] = "insufficient_source_depth"
                    recovery_row["reason"] = f"resolved publisher text had {words} words"
                else:
                    recovery_row["result"] = "resolution_failed"
                    recovery_row["reason"] = "google wrapper did not resolve to the trusted publisher"
                _record_trusted_source_recovery(recovery_row)
            h["source_quality"] = "brief" if summary_words >= 20 else "thin"
            return h

        # Try full body extraction for open/local sources.
        if h.get("source_type") == "full_source" and link:
            # 2500 words: high enough that truncation effectively never cuts a normal
            # article (even long investigations and listicles, whose ranked items come
            # last). The cap exists only to guard against a pathologically long or
            # junk-filled scraped page, not to save tokens — the savings were pennies and
            # the cost was dropping the exact facts the article is about.
            full = fetch_article_text(link, max_words=2500, content_hint=_source_content_hint(h))
            raw_words = _word_count(full)
            focused = _focus_extracted_source_text(full, h)
            if focused != full:
                h["source_focus_repaired"] = True
                h["source_focus_original_word_count"] = raw_words
                h["source_focus_word_count"] = _word_count(focused)
                full = focused
            if full and len(full.split()) >= 140:
                h["article_text"] = full
                h["source_quality"] = "full"
                return h
            # Scrape failed or was blocked (e.g. WPTV returns 403 to bots). Many
            # full_source feeds embed the ENTIRE article in the RSS content:encoded
            # field, which extract_rss_text already captured into summary. Analysis of
            # the WPTV feed shows bodies of 66-1349 words, all complete articles — the
            # short ones are legitimate brief news items (a fatal crash, a fire report),
            # not truncated snippets. Use the embedded text directly when it is a real
            # body (60+ words) rather than discarding the story as thin. This is what
            # keeps WPTV county stories alive.
            if summary_words >= 60:
                h["article_text"] = h.get("summary", "")
                h["source_quality"] = "full"
                return h

        # Fallback quality labels based on actual RSS text depth.
        if summary_words >= 140:
            h["source_quality"] = "summary"
        elif summary_words >= 40:
            h["source_quality"] = "brief"
        else:
            h["source_quality"] = "thin"
        return h

    # Keep this parallel and bounded; otherwise a few slow publisher pages can stall the run.
    try:
        with ThreadPoolExecutor(max_workers=5) as ex:
            futures = [ex.submit(enrich_one, h) for h in result]
            for fut in as_completed(futures, timeout=45):
                try:
                    fut.result(timeout=1)
                except Exception:
                    pass
    except Exception:
        # If the timeout trips, use whatever was enriched so far.
        pass

    full_count = sum(1 for h in result if h.get("source_quality") == "full")
    summary_count = sum(1 for h in result if h.get("source_quality") in ("summary", "brief"))
    discovery_count = sum(1 for h in result if h.get("source_quality") == "discovery_only")
    print(f"  Source quality: {full_count} full, {summary_count} summary/brief, {discovery_count} discovery-only, {len(result)} total")


    return result


# Category relevance filtering for broad feeds.
# This is intentionally conservative: it promotes clearly on-topic stories, but
# falls back to the unfiltered pool if a section would otherwise go thin.
def _text_for_category_match(h):
    return " ".join([
        h.get("title", ""),
        h.get("headline", ""),
        h.get("summary", ""),
        h.get("teaser", ""),
        h.get("body", "")[:1200],
        h.get("article_text", "")[:1200],
    ]).lower()


def _has_any(text, terms):
    return any(term in text for term in terms)


def _has_any_bounded_term(text, terms):
    """Match editorial exclusion terms on token/phrase boundaries.

    Hard-negative category vocabularies are semantic words/phrases, not arbitrary
    character fragments.  A term such as ``event`` must match ``event`` but never
    the letters inside ``prevents``.  Keep the older substring helper for callers
    that intentionally use fragments (for example ``announc`` freshness stems).
    """
    value = str(text or "").casefold()
    for raw_term in terms or ():
        term = str(raw_term or "").strip().casefold()
        if not term:
            continue
        pattern = re.escape(term).replace(r"\ ", r"\s+")
        if re.search(rf"(?<![a-z0-9]){pattern}(?![a-z0-9])", value):
            return True
    return False

def _story_locality_blob(item):
    return " ".join([
        item.get("source_title", ""),
        item.get("title", ""),
        item.get("headline", ""),
        item.get("summary", ""),
        item.get("source_summary", ""),
        item.get("teaser", ""),
        item.get("body", "")[:1800],
        item.get("article_text", "")[:1800],
    ]).lower()

def _strip_quoted_phrases(text):
    # Place names inside entertainment titles do not establish geography.
    text = re.sub(r'"[^"\n]{1,200}"', " ", text or "")
    text = re.sub(r"'[^'\n]{1,200}'", " ", text)
    return re.sub(r"\s+", " ", text).strip()

def _trusted_county_feed(category_key, item):
    feed_url = (item.get("feed_url", "") or "").lower()
    trusted_hints = {
        "martin": "wptv.com/news/region-martin-county.rss",
        "st_lucie": "wptv.com/news/region-st-lucie-county.rss",
        "indian_river": "wptv.com/news/region-indian-river-county.rss",
    }
    return trusted_hints.get(category_key, "") in feed_url


_COUNTY_AUTHORITY_TERMS = {
    "martin": (
        "martin county", "jensen beach", "palm city", "hobe sound", "port salerno",
        "jupiter island", "indiantown", "sewall's point", "sewalls point",
        "city of stuart", "stuart florida", "stuart fla", "stuart fl",
    ),
    "st_lucie": (
        "st. lucie county", "st lucie county", "port st. lucie", "port st lucie",
        "fort pierce", "st. lucie west", "st lucie west",
    ),
    "indian_river": (
        "indian river county", "vero beach", "fellsmere", "wabasso", "gifford",
        "sebastian inlet", "sebastian river", "city of sebastian", "sebastian florida",
        "sebastian fla", "sebastian fl",
    ),
}

_OUTSIDE_COUNTY_AUTHORITY_TERMS = {
    "palm_beach": (
        "palm beach county", "west palm beach", "royal palm beach", "palm beach gardens",
        "delray beach", "boca raton", "boynton beach", "lake worth", "wellington florida",
        "riviera beach", "loxahatchee", "belle glade", "pahokee",
    ),
    "okeechobee": ("okeechobee county",),
    "brevard": ("brevard county",),
    "broward": ("broward county", "fort lauderdale"),
    "miami_dade": ("miami-dade county", "miami dade county"),
}


def _county_authority_normalize(value):
    # Treat publisher punctuation as token boundaries so ``St. Lucie County.`` and
    # URL/path variants normalize to the same locality phrase.
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9]+", " ", str(value or "").lower())).strip()


def _county_authority_phrase_hits(text, terms):
    normalized = f" {_county_authority_normalize(text)} "
    hits = []
    for term in terms:
        phrase = _county_authority_normalize(term)
        if phrase and f" {phrase} " in normalized:
            hits.append(term)
    return hits


def _source_county_authority_blob(item):
    """Return only publisher/source-facing material that may prove county membership.

    Generated TCT headline/teaser/body copy is deliberately excluded. Raw feed rows are
    allowed to use their title/summary because those fields are publisher material.
    Persisted event-identity locality is accepted only when its origin is source-derived.
    """
    item = item if isinstance(item, dict) else {}
    event_identity = item.get("event_identity")
    if not isinstance(event_identity, dict):
        event_identity = {}

    values = [
        item.get("source_title"),
        item.get("source_headline"),
        item.get("latest_source_headline"),
        item.get("source_summary"),
        item.get("source_text"),
        item.get("article_text"),
        item.get("source_url"),
        item.get("latest_source_url"),
        item.get("_source_url"),
        item.get("original_url"),
    ]

    external_link = _normalized_external_source_url(item.get("link"))
    if external_link:
        values.append(external_link)

    # Raw fetched-source rows have not yet been rewritten. Their title/summary are
    # source material; generated/archive rows instead carry source_* provenance.
    raw_source_row = bool(
        item.get("title")
        and (
            external_link
            or item.get("article_text")
            or item.get("source_type") in {"rss", "trusted_aggregator_resolved", "source"}
        )
    )
    if raw_source_row:
        values.extend([item.get("title"), item.get("summary")])

    if str(event_identity.get("origin") or "") == "source_derived":
        values.extend([
            event_identity.get("source_headline"),
            event_identity.get("source_url"),
            " ".join(str(v or "") for v in (event_identity.get("locality") or [])),
            " ".join(str(v or "") for v in (event_identity.get("precise_locations") or [])),
            " ".join(str(v or "") for v in (event_identity.get("agencies") or [])),
        ])

    return _county_authority_normalize(" ".join(str(v or "") for v in values))


def _trusted_custom_county_blob(item):
    """Human-authored TCT copy is trusted evidence for custom-only locality."""
    item = item if isinstance(item, dict) else {}
    return _county_authority_normalize(" ".join([
        str(item.get("headline") or item.get("title") or ""),
        str(item.get("teaser") or item.get("summary") or ""),
        str(item.get("body") or ""),
    ]))


def _county_membership_authority_assessment(item, primary_category=""):
    """Assess Treasure Coast county membership from authoritative evidence only."""
    item = item if isinstance(item, dict) else {}
    custom = bool(item.get("is_custom") or item.get("authoritative_custom"))
    source_blob = _trusted_custom_county_blob(item) if custom else _source_county_authority_blob(item)

    evidence = {key: [] for key in COUNTY_KEYS}
    supported = set()
    for county_key in COUNTY_KEYS:
        hits = _county_authority_phrase_hits(source_blob, _COUNTY_AUTHORITY_TERMS[county_key])
        if hits:
            supported.add(county_key)
            evidence[county_key].extend(f"source_term:{hit}" for hit in hits[:6])

    outside_conflicts = []
    for outside_key, terms in _OUTSIDE_COUNTY_AUTHORITY_TERMS.items():
        hits = _county_authority_phrase_hits(source_blob, terms)
        if hits:
            outside_conflicts.append({
                "county": outside_key,
                "evidence": [f"source_term:{hit}" for hit in hits[:6]],
            })

    if not custom:
        # A dedicated publisher county feed is supporting metadata, but explicit
        # outside-county evidence wins unless the source independently names the
        # Treasure Coast county too.
        for county_key in COUNTY_KEYS:
            if county_key in supported:
                continue
            if _trusted_county_feed(county_key, item) and not outside_conflicts:
                supported.add(county_key)
                evidence[county_key].append("trusted_county_feed")

        # v1.13.2.0 migration safety: many June/July archive rows predate durable
        # source provenance. Their already-published county membership must not be
        # erased merely because source_* fields are absent. A migration marker can
        # preserve those historical labels only when there is *no* surviving source
        # evidence for any Treasure Coast county and no explicit outside-county
        # conflict. This marker is written only by the archive backfill below; live
        # generated copy and classifier output can never create it. If source evidence
        # later appears, it immediately takes precedence and the marker grants nothing.
        direct_supported = set(supported)
        legacy_marker = item.get("county_membership_authority")
        if (
            not direct_supported
            and not outside_conflicts
            and isinstance(legacy_marker, dict)
            and legacy_marker.get("origin") == COUNTY_LEGACY_ARCHIVE_AUTHORITY_ORIGIN
            and legacy_marker.get("contract_version") == COUNTY_MEMBERSHIP_AUTHORITY_VERSION
        ):
            for county_key in legacy_marker.get("counties", ()) or ():
                if county_key in COUNTY_KEYS:
                    supported.add(county_key)
                    evidence[county_key].append("legacy_archive_membership_uncontradicted")
    else:
        declared = {
            key for key in _normalize_category_keys(item.get("category_keys") or [])
            if key in COUNTY_KEYS
        }
        declared.update(
            key for key in (item.get("county_keys") or []) if key in COUNTY_KEYS
        )
        for key in (primary_category, item.get("category_key"), item.get("cat_key"), item.get("category")):
            if key in COUNTY_KEYS:
                declared.add(key)
        for county_key in declared:
            supported.add(county_key)
            evidence[county_key].append("trusted_custom_declaration")

    # If the final TCT display headline explicitly narrows a multi-county source to
    # exactly one Treasure Coast county, do not project that rewritten article into
    # every county merely because the underlying regional source mentioned them all.
    # Raw source rows have ``title`` but no generated ``headline``, so this boundary
    # applies only after editorial framing exists.
    display_headline = str(item.get("headline") or "").strip()
    if not custom and display_headline and len(supported) > 1:
        focused_counties = {
            county_key for county_key in COUNTY_KEYS
            if _county_authority_phrase_hits(display_headline, _COUNTY_AUTHORITY_TERMS[county_key])
        }
        if len(focused_counties) == 1:
            focused = next(iter(focused_counties))
            supported = {focused}
            evidence[focused].append("display_headline_single_county_focus")

    requested = set(
        key for key in _normalize_category_keys(item.get("category_keys") or [])
        if key in COUNTY_KEYS
    )
    requested.update(key for key in (item.get("county_keys") or []) if key in COUNTY_KEYS)
    for key in (primary_category, item.get("category_key"), item.get("cat_key"), item.get("category")):
        if key in COUNTY_KEYS:
            requested.add(key)

    rejected = sorted(requested - supported)
    return {
        "schema_version": COUNTY_MEMBERSHIP_AUTHORITY_SCHEMA_VERSION,
        "contract_version": COUNTY_MEMBERSHIP_AUTHORITY_VERSION,
        "custom_authority": custom,
        "requested_counties": [key for key in CATEGORIES if key in requested and key in COUNTY_KEYS],
        "supported_counties": [key for key in CATEGORIES if key in supported and key in COUNTY_KEYS],
        "rejected_memberships": rejected,
        "supporting_evidence": {
            key: evidence[key] for key in CATEGORIES if key in COUNTY_KEYS and evidence[key]
        },
        "conflicting_counties": outside_conflicts,
        "source_evidence_present": bool(source_blob),
    }


def _county_locality_evidence(category_key, item):
    """Compatibility wrapper for the source-authority county membership contract."""
    if category_key not in COUNTY_KEYS:
        return False
    assessment = _county_membership_authority_assessment(item)
    return category_key in assessment.get("supported_counties", ())


def _has_treasure_coast_locality(item):
    raw = _strip_quoted_phrases(_story_locality_blob(item))
    return "treasure coast" in raw or any(
        _county_locality_evidence(key, item) for key in COUNTY_KEYS
    )


def _normalize_category_keys(values):
    """Return valid category keys in the site's stable navigation order."""
    if isinstance(values, str):
        values = re.split(r"[\s,|]+", values)
    valid = {str(value or "").strip() for value in (values or [])}
    return [key for key in CATEGORIES if key in valid]


def _item_category_memberships(item, primary_category="", extra_categories=None):
    """Return valid topic memberships plus source-authorized county memberships.

    County labels from old archive rows, generated copy, classifier output, or category
    container context are never self-authorizing. They survive only when the shared
    county-authority contract independently supports them.
    """
    item = item or {}
    categories = {
        key for key in _normalize_category_keys(item.get("category_keys") or [])
        if key not in COUNTY_KEYS
    }
    for candidate in (
        primary_category, item.get("category_key"), item.get("cat_key"), item.get("category"),
    ):
        if candidate in CATEGORIES and candidate not in COUNTY_KEYS:
            categories.add(candidate)
    categories.update(
        key for key in _normalize_category_keys(extra_categories or [])
        if key not in COUNTY_KEYS
    )

    if STORY_CLASSIFICATION is not None:
        for lookup in (
            item.get("source_title", ""), item.get("source_headline", ""),
            item.get("title", ""), item.get("headline", ""),
        ):
            key = str(lookup or "").strip().lower()
            classified = STORY_CLASSIFICATION.get(key) if key else None
            if classified:
                categories.update(
                    c for c in classified if c in CATEGORIES and c not in COUNTY_KEYS
                )
                break

    # Crime & Safety is revalidated at this shared projection boundary because legacy
    # classifier/cache labels can otherwise survive in ``category_keys`` after a story
    # has been rewritten around a routine education or community focus. Existing
    # Local Government/Business contracts already enforce at their source/archive
    # boundaries; re-running them here would incorrectly reinterpret intentionally
    # preserved historical memberships from sparse archive rows.
    if "crime" in categories:
        assessment = _category_eligibility_contract_assessment("crime", item)
        if not assessment.get("eligible"):
            categories.discard("crime")

    authority = _county_membership_authority_assessment(item, primary_category)
    categories.update(authority.get("supported_counties") or [])
    return [key for key in CATEGORIES if key in categories]


def _apply_category_memberships(item, primary_category="", extra_categories=None):
    if not isinstance(item, dict):
        return []
    memberships = _item_category_memberships(item, primary_category, extra_categories)
    item["category_keys"] = memberships
    item["county_keys"] = [key for key in memberships if key in COUNTY_KEYS]
    return memberships


def _merge_category_memberships(target, source, primary_category=""):
    target = target or {}
    source = source or {}
    extras = []
    for row in (target, source):
        extras.extend(_item_category_memberships(row))

    # The target archive row may be older/sparser than the incoming source-backed
    # placement. Use a non-mutating combined authority probe so valid county evidence
    # on the incoming source is not lost during an in-place canonical update.
    authority_probe = dict(target)
    for key in (
        "source_title", "source_headline", "latest_source_headline", "source_summary",
        "source_text", "article_text", "source_url", "latest_source_url", "_source_url",
        "original_url", "feed_url", "event_identity", "link", "title",
    ):
        value = source.get(key)
        if value not in (None, "", [], {}):
            authority_probe[key] = copy.deepcopy(value)
    if source.get("is_custom") or source.get("authoritative_custom"):
        authority_probe.update({
            "is_custom": True,
            "authoritative_custom": True,
            "headline": source.get("headline", target.get("headline", "")),
            "teaser": source.get("teaser", target.get("teaser", "")),
            "body": source.get("body", target.get("body", "")),
            "category": source.get("category", ""),
            "category_key": source.get("category_key", ""),
            "category_keys": source.get("category_keys", []),
            "county_keys": source.get("county_keys", []),
        })

    memberships = _item_category_memberships(authority_probe, primary_category, extras)
    target["category_keys"] = memberships
    target["county_keys"] = [key for key in memberships if key in COUNTY_KEYS]
    return memberships


def _category_membership_contains(item, category_key):
    return category_key in _item_category_memberships(item)


def _backfill_archive_category_memberships(archive, output_root=None):
    """Revalidate and repair persisted category/county memberships deterministically."""
    rows = list(archive or [])
    changed = []
    repaired = []
    authority_rows = []
    violations = []

    for entry in rows:
        before = _normalize_category_keys(entry.get("category_keys") or [])
        before_counties = [key for key in before if key in COUNTY_KEYS]
        before_counties.extend(
            key for key in (entry.get("county_keys") or [])
            if key in COUNTY_KEYS and key not in before_counties
        )
        authority = _county_membership_authority_assessment(
            entry, entry.get("category_key", "")
        )

        # Historical archive rows created before source-provenance persistence can be
        # impossible to re-prove today even though their county placement was valid.
        # Preserve only the *existing* county labels when there is no source-derived
        # Treasure Coast county at all and no explicit outside-county contradiction.
        # This is migration-only authority: it cannot add a county that the archive
        # row did not already carry, and it is ignored as soon as real source locality
        # is available.
        primary_county = entry.get("category_key") if entry.get("category_key") in COUNTY_KEYS else ""
        legacy_existing_counties = list(before_counties)
        if primary_county and primary_county not in legacy_existing_counties:
            legacy_existing_counties.append(primary_county)
        legacy_preserve = [
            key for key in legacy_existing_counties
            if key not in authority.get("supported_counties", ())
        ]
        if (
            legacy_preserve
            and not (entry.get("is_custom") or entry.get("authoritative_custom"))
            and not authority.get("supported_counties")
            and not authority.get("conflicting_counties")
        ):
            entry["county_membership_authority"] = {
                "origin": COUNTY_LEGACY_ARCHIVE_AUTHORITY_ORIGIN,
                "contract_version": COUNTY_MEMBERSHIP_AUTHORITY_VERSION,
                "counties": [key for key in CATEGORIES if key in set(legacy_preserve)],
                "migration_only": True,
            }
            authority = _county_membership_authority_assessment(
                entry, entry.get("category_key", "")
            )

        original_primary = str(entry.get("category_key") or "")
        after = _apply_category_memberships(entry, original_primary)
        if (
            original_primary in CATEGORIES
            and original_primary not in after
            and _category_contract_config(original_primary).get("mode") == "enforce"
            and not (entry.get("is_custom") or entry.get("authoritative_custom"))
            and after
        ):
            replacement_primary = after[0]
            entry["category_key"] = replacement_primary
            entry["category_label"] = CATEGORIES[replacement_primary]["label"]
        after_counties = [key for key in after if key in COUNTY_KEYS]
        added = [key for key in after if key not in before]
        removed = [key for key in before if key not in after]

        if added or removed or list(entry.get("county_keys") or []) != after_counties:
            changed.append({
                "slug": entry.get("slug", ""),
                "headline": entry.get("headline", ""),
                "primary_category": entry.get("category_key", ""),
                "added_categories": added,
                "removed_categories": removed,
                "category_keys": after,
                "county_keys": after_counties,
            })
        removed_counties = [
            key for key in before_counties if key not in after_counties
        ]
        if removed_counties:
            repaired.append({
                "slug": entry.get("slug", ""),
                "headline": entry.get("headline", ""),
                "removed_county_memberships": removed_counties,
                "supported_counties": authority.get("supported_counties", []),
                "conflicting_counties": authority.get("conflicting_counties", []),
            })

        unsupported_after = [
            key for key in after_counties
            if key not in authority.get("supported_counties", [])
        ]
        if unsupported_after:
            violations.append({
                "slug": entry.get("slug", ""),
                "headline": entry.get("headline", ""),
                "unsupported_counties": unsupported_after,
            })

        authority_rows.append({
            "slug": entry.get("slug", ""),
            "headline": entry.get("headline", ""),
            "primary_category": entry.get("category_key", ""),
            **authority,
        })

    report = {
        "schema_version": 2,
        "generated_at": _utc_now_iso(),
        "policy": "source_authority_required_for_treasure_coast_county_membership",
        "archive_records_checked": len(rows),
        "records_backfilled": len(changed),
        "records_changed": len(changed),
        "records_repaired": len(repaired),
        "unsupported_memberships_remaining": len(violations),
        "changed": changed,
        "repaired": repaired,
        "violations": violations,
        "passed": not violations,
    }
    authority_report = {
        "schema_version": COUNTY_MEMBERSHIP_AUTHORITY_SCHEMA_VERSION,
        "contract_version": COUNTY_MEMBERSHIP_AUTHORITY_VERSION,
        "generated_at": _utc_now_iso(),
        "policy": (
            "county membership requires publisher/source-derived evidence or trusted "
            "custom TCT authority; generated copy cannot prove geography"
        ),
        "summary": {
            "archive_records_assessed": len(authority_rows),
            "archive_rows_repaired": len(repaired),
            "legacy_archive_rows_preserved": sum(
                1 for row in authority_rows
                if any(
                    "legacy_archive_membership_uncontradicted" in values
                    for values in (row.get("supporting_evidence") or {}).values()
                )
            ),
            "unsupported_memberships_remaining": len(violations),
        },
        "archive_assessments": authority_rows,
        "archive_repairs": repaired,
        "live_projection": {
            "assessed_placements": 0,
            "rejected_placements": 0,
            "violations": [],
            "passed": True,
        },
        "passed": not violations,
    }

    if output_root is not None:
        data_dir = Path(output_root) / "data"
        data_dir.mkdir(parents=True, exist_ok=True)
        (data_dir / "category-membership-report.json").write_text(
            json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        (data_dir / "county-membership-authority-report.json").write_text(
            json.dumps(authority_report, indent=2, ensure_ascii=False), encoding="utf-8"
        )

    if violations:
        raise RuntimeError(
            "County membership authority contract FAILED: "
            f"{len(violations)} unsupported archive membership(s) survived repair"
        )
    print(
        "  County membership authority PASSED "
        f"({len(rows)} archive records; {len(repaired)} repaired)"
    )
    return rows, report


def _live_county_authority_items(all_categories, top_cat=None):
    """Yield unique live placement objects with their containing category."""
    seen = set()
    categories = list(all_categories or [])
    if top_cat and top_cat not in categories:
        categories.append(top_cat)
    for category in categories:
        category_key = str((category or {}).get("category_key") or "")
        placements = [("hero", (category or {}).get("hero"))]
        placements.extend(("card", card) for card in (category or {}).get("cards", []) or [])
        for surface, item in placements:
            if not isinstance(item, dict) or not item.get("headline"):
                continue
            marker = id(item)
            if marker in seen:
                continue
            seen.add(marker)
            yield category_key, surface, item


def enforce_live_county_membership_authority(all_categories):
    """Repair county metadata and reject unsupported placements from county sections."""
    rejected = []
    assessed = 0
    for category in list(all_categories or []):
        category_key = str((category or {}).get("category_key") or "")
        if not isinstance(category, dict):
            continue

        for _, _, item in list(_live_county_authority_items([category])):
            if item.get("_section_placeholder"):
                continue
            assessed += 1
            _apply_category_memberships(
                item, item.get("category_key") or item.get("cat_key") or ""
            )

        if category_key not in COUNTY_KEYS:
            continue

        hero = category.get("hero")
        if isinstance(hero, dict) and not hero.get("_section_placeholder"):
            assessment = _county_membership_authority_assessment(hero, category_key)
            if category_key not in assessment.get("supported_counties", []):
                rejected.append({
                    "category_key": category_key,
                    "surface": "hero",
                    "headline": hero.get("headline", ""),
                    "reason": "unsupported_county_membership",
                    **assessment,
                })
                category["hero"] = None

        kept_cards = []
        for card in category.get("cards", []) or []:
            if not isinstance(card, dict) or card.get("_section_placeholder"):
                kept_cards.append(card)
                continue
            assessment = _county_membership_authority_assessment(card, category_key)
            if category_key not in assessment.get("supported_counties", []):
                rejected.append({
                    "category_key": category_key,
                    "surface": "card",
                    "headline": card.get("headline", ""),
                    "reason": "unsupported_county_membership",
                    **assessment,
                })
                continue
            kept_cards.append(card)
        category["cards"] = kept_cards
    return {"assessed_placements": assessed, "rejections": rejected}


def validate_live_county_membership_authority(all_categories, top_cat=None, output_root=None):
    """Fail closed if any final live county placement lacks source authority."""
    assessed = 0
    violations = []
    for category_key, surface, item in _live_county_authority_items(all_categories, top_cat):
        if item.get("_section_placeholder"):
            continue
        assessment = _county_membership_authority_assessment(
            item, category_key if category_key in COUNTY_KEYS else ""
        )
        assessed += 1

        # Metadata itself may not carry an unsupported county even on a topic surface.
        declared_counties = set(
            key for key in _normalize_category_keys(item.get("category_keys") or [])
            if key in COUNTY_KEYS
        )
        declared_counties.update(
            key for key in (item.get("county_keys") or []) if key in COUNTY_KEYS
        )
        unsupported_metadata = sorted(
            declared_counties - set(assessment.get("supported_counties", []))
        )
        if unsupported_metadata:
            violations.append({
                "category_key": category_key,
                "surface": surface,
                "headline": item.get("headline", ""),
                "reason": "unsupported_county_metadata",
                "unsupported_counties": unsupported_metadata,
                **assessment,
            })

        if (
            category_key in COUNTY_KEYS
            and category_key not in assessment.get("supported_counties", [])
        ):
            violations.append({
                "category_key": category_key,
                "surface": surface,
                "headline": item.get("headline", ""),
                "reason": "unsupported_county_live_placement",
                **assessment,
            })

    if output_root is not None:
        path = Path(output_root) / "data" / "county-membership-authority-report.json"
        existing = {}
        if path.exists():
            try:
                existing = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                existing = {}
        existing.setdefault("schema_version", COUNTY_MEMBERSHIP_AUTHORITY_SCHEMA_VERSION)
        existing.setdefault("contract_version", COUNTY_MEMBERSHIP_AUTHORITY_VERSION)
        existing.setdefault("generated_at", _utc_now_iso())
        existing["live_projection"] = {
            "assessed_placements": assessed,
            "rejected_placements": len(violations),
            "violations": violations,
            "passed": not violations,
        }
        existing["passed"] = bool(existing.get("passed", True)) and not violations
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(existing, indent=2, ensure_ascii=False), encoding="utf-8")

    if violations:
        raise RuntimeError(
            "County membership authority contract FAILED: "
            f"{len(violations)} unsupported live placement(s)"
        )
    print(
        "  Final county membership authority PASSED "
        f"({assessed} live placement(s) assessed)"
    )
    return {"assessed_placements": assessed, "violations": violations, "passed": True}


# Publication quality gates. A category can fall back to older real reporting, but
# a thin RSS blurb must never be expanded into a fake-looking article or promoted
# merely to keep a section populated.
MIN_HERO_BODY_WORDS = 120
MIN_CARD_BODY_WORDS = 90
MIN_SOURCE_WORDS = 80


def _word_count(text):
    return len(re.findall(r"\b[\w'-]+\b", text or ""))

def _paragraph_count(text):
    return len([p for p in re.split(r"\n\s*\n", text or "") if p.strip()])

def _sentence_count(text):
    return len([s for s in re.split(r"(?<=[.!?])\s+", (text or "").strip()) if s.strip()])

def _source_word_count(item):
    try:
        stored = int(item.get("source_word_count", 0) or 0)
    except Exception:
        stored = 0
    if stored:
        return stored
    source_text = item.get("article_text", "") or item.get("source_summary", "") or item.get("summary", "")
    return _word_count(source_text)

_MEDIA_PUBLISHER_BRANDS = {
    "wptv.com": ("wptv",),
    "wpbf.com": ("wpbf",),
    "cbs12.com": ("cbs12", "wpec"),
    "cw34.com": ("cw34",),
    "wflx.com": ("wflx",),
    "tcpalm.com": ("tcpalm", "treasure coast newspapers"),
    "hometownnewstc.com": ("hometown news", "hometown news treasure coast"),
    "sebastiandaily.com": ("sebastian daily",),
}


def _is_publisher_self_promotion(item):
    """Reject a publisher using TCT as free promotion for its own brand or event.

    News reported *by* another outlet remains eligible. This guard is intentionally
    narrow: it requires a known media publisher plus explicit publisher-branded
    promotional framing (hosting/holding/presenting an event, giveaway, meetup, etc.).
    Human-authored TCT custom articles remain authoritative.
    """
    if not isinstance(item, dict):
        return False
    if item.get("is_custom") or item.get("authoritative_custom"):
        return False

    source_url = str(
        item.get("source_url") or item.get("latest_source_url")
        or item.get("_source_url") or item.get("link") or ""
    ).strip()
    try:
        host = (urlsplit(source_url).netloc or "").lower()
    except Exception:
        host = ""
    host = host[4:] if host.startswith("www.") else host
    brands = ()
    for domain, names in _MEDIA_PUBLISHER_BRANDS.items():
        if host == domain or host.endswith("." + domain):
            brands = names
            break
    if not brands:
        return False

    headline_values = [
        str(item.get(key) or "").strip()
        for key in ("headline", "title", "source_headline", "source_title")
        if str(item.get(key) or "").strip()
    ]
    body = " ".join(str(item.get(key) or "") for key in (
        "teaser", "summary", "source_summary", "article_text", "body"
    ))[:12000]

    # Publisher names are commonly appended to syndicated/search headlines as a
    # source suffix (``Story headline - WPTV``). That attribution alone must never
    # turn an otherwise valid story about a city-hosted event into self-promotion.
    # For brand evidence, ignore a terminal publisher suffix while preserving brand
    # names that are part of the actual headline (``WPTV hosts ...``).
    brand_headlines = []
    for value in headline_values:
        cleaned = value
        for brand in brands:
            cleaned = re.sub(
                r"\s*(?:[-|—–]\s*)" + re.escape(brand) + r"\s*$",
                "", cleaned, flags=re.I,
            )
        brand_headlines.append(cleaned)
    headline = " ".join(headline_values)
    normalized_brand_headline = _normalize_nonstory_text(" ".join(brand_headlines))
    normalized_blob = _normalize_nonstory_text(headline + " " + body)
    brand_named = any(
        re.search(r"(?<![a-z0-9])" + re.escape(brand) + r"(?![a-z0-9])", normalized_brand_headline)
        for brand in brands
    )

    branded_campaign_path = bool(re.search(
        r"/(?:community/)?(?:lets-hear-it|meet-the-team|station-events?|contests?|giveaways?)(?:/|$)",
        urlsplit(source_url).path.lower() if source_url else "",
    ))
    promotional_event = bool(
        re.search(
            r"\b(?:host|hosts|hosting|hold|holds|holding|bring|brings|present|presents|"
            r"invite|invites|launch|launches|sponsor|sponsors)\b.{0,90}"
            r"\b(?:meetup|meet up|town hall|forum|community event|open house|watch party|"
            r"contest|giveaway|conversation|education focus|event)\b",
            normalized_blob,
        )
        or re.search(r"\blet s hear it\b", normalized_blob)
    )
    return bool(branded_campaign_path or (brand_named and promotional_event))


def _source_candidate_publishable(item):
    """Require enough verified source material before Claude writes anything.

    This runs before category generation, so a thin RSS blurb cannot become a hero,
    card, permalink, or even consume article-generation tokens. Archive recovery fills
    the section when the live source pool is too thin.
    """
    if not item or not item.get("title"):
        return False
    if _is_publisher_self_promotion(item):
        return False
    quality = (item.get("source_quality", "") or "").lower()
    if quality not in {"full", "summary"}:
        return False
    return _source_word_count(item) >= MIN_SOURCE_WORDS

def _normalize_nonstory_text(text):
    text = (text or "").replace("’", "'").replace("`", "'").lower()
    text = re.sub(r"[^a-z0-9'& ]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _is_nonstory_placeholder(item):
    """Identify section metadata that must never become a public article.

    The category-writing model can occasionally answer with a status sentence such
    as ``No Indian River County stories available in today's feed`` when the source
    pool has no valid lead.  That text is navigation metadata, not journalism.
    Manual/custom articles are deliberately exempt unless they carry the explicit
    structural placeholder marker, preserving the custom-authority contract.
    """
    if not item:
        return False
    if item.get("_section_placeholder") or (item.get("source_quality") or "").lower() == "section_placeholder":
        return True
    if item.get("is_custom") or item.get("authoritative_custom"):
        return False

    headline = _normalize_nonstory_text(item.get("headline") or item.get("title"))
    if not headline:
        return False

    status_patterns = (
        # Model/status prose may append a geography or coverage phrase after
        # ``available``.  Treat the complete family as navigation metadata, never a
        # publishable headline.  Custom/editor-authored work remains exempt above.
        r"^no .{1,120} stor(?:y|ies) (?:are )?available(?: in (?:today'?s|the) feed)?(?: for .{1,120})?$",
        r"^no (?:new |local |current |recent )?stor(?:y|ies) (?:are )?available(?: today| at this time)?(?: for .{1,120})?$",
        r"^(?:there are )?no (?:new |local |current |recent )?stor(?:y|ies)(?: available)?(?: for .{1,120})?$",
        r"^(?:check back|please check back)(?: later)? for (?:more |new )?(?:stories|updates|coverage)$",
    )
    if any(re.fullmatch(pattern, headline) for pattern in status_patterns):
        return True

    # The deterministic structural fallback uses a generic ``<section> coverage``
    # headline.  Only treat it as a placeholder when the item also lacks a real
    # source/article identity, avoiding false positives on legitimate coverage.
    if headline.endswith(" coverage") and not any(
        item.get(key) for key in ("source_url", "feed_url", "source_title", "article_text")
    ):
        body = _normalize_nonstory_text(item.get("body") or item.get("teaser"))
        if body.startswith("browse treasure coast today's latest") or body.startswith("browse treasure coast today s latest"):
            return True
    return False


def _sanitize_nonstory_category(data, category_label=""):
    """Remove model/status placeholders and promote a real card when possible."""
    if not isinstance(data, dict):
        return data
    cards = [card for card in list(data.get("cards") or []) if not _is_nonstory_placeholder(card)]
    removed_cards = len(list(data.get("cards") or [])) - len(cards)
    hero = data.get("hero") or {}
    removed_hero = _is_nonstory_placeholder(hero)
    if removed_hero:
        print(f"  NONSTORY BLOCK: rejected placeholder hero for {category_label}: '{hero.get('headline','')[:80]}'")
        hero = {}
    if removed_cards:
        print(f"  NONSTORY BLOCK: rejected {removed_cards} placeholder card(s) for {category_label}")
    if not hero and cards:
        hero = cards.pop(0)
        print(f"  NONSTORY BLOCK: promoted real card after placeholder removal for {category_label}")
    data["hero"] = hero
    data["cards"] = cards
    if not hero or not hero.get("headline"):
        data["_drop_category"] = True
    return data


def _publishable_article(item, hero=False):
    """Return True only when an item is substantial enough for a permalink.

    Custom/manual articles and active weather alerts remain editorial exceptions.
    Automated feed stories must have a real source, enough verified source material,
    and enough finished copy to stand alone as an article.
    """
    if not item or not item.get("headline"):
        return False
    if _is_nonstory_placeholder(item):
        return False
    if _is_publisher_self_promotion(item):
        return False
    if item.get("is_custom") or item.get("is_weather_alert"):
        return True
    if item.get("_archive_only"):
        return bool(item.get("_archive_verified_quality"))

    quality = (item.get("source_quality", "") or "").lower()
    if quality in {"thin", "brief", "discovery_only"}:
        return False

    body = (item.get("body", "") or "").strip()
    min_words = MIN_HERO_BODY_WORDS if hero else MIN_CARD_BODY_WORDS
    if _word_count(body) < min_words:
        return False
    # Prefer real paragraph structure, but allow a well-developed single paragraph
    # with at least five factual sentences.
    if _paragraph_count(body) < 2 and _sentence_count(body) < 5:
        return False

    source_words = _source_word_count(item)
    if source_words < MIN_SOURCE_WORDS:
        return False
    return True

def _archive_article_metrics(entry):
    """Get body depth for an archived page, reading legacy HTML when needed."""
    try:
        wc = int(entry.get("article_word_count", 0) or 0)
        pc = int(entry.get("article_paragraph_count", 0) or 0)
    except Exception:
        wc, pc = 0, 0
    if wc:
        return wc, pc

    slug = entry.get("slug", "")
    if not slug:
        return 0, 0
    path = OUTPUT_DIR / "articles" / f"{slug}.html"
    try:
        html_text = path.read_text(encoding="utf-8", errors="ignore")
        match = re.search(
            r'<div class="article-body">(.*?)</div>\s*(?:<aside class="newsletter-inline-slot[^>]*>.*?</aside>\s*)?<div class="article-share">',
            html_text, re.IGNORECASE | re.DOTALL,
        )
        if not match:
            return 0, 0
        body_html = match.group(1)
        pc = len(re.findall(r"<p(?:\s[^>]*)?>", body_html, re.IGNORECASE))
        import html as _html
        plain = _html.unescape(re.sub(r"<[^>]+>", " ", body_html))
        wc = _word_count(plain)
        entry["article_word_count"] = wc
        entry["article_paragraph_count"] = pc
        return wc, pc
    except Exception:
        return 0, 0

def _archive_article_body(entry):
    """Return the existing full article body as plain paragraphs for hero previews."""
    slug = entry.get("slug", "")
    if not slug:
        return ""
    path = OUTPUT_DIR / "articles" / f"{slug}.html"
    try:
        html_text = path.read_text(encoding="utf-8", errors="ignore")
        match = re.search(
            r'<div class="article-body">(.*?)</div>\s*(?:<aside class="newsletter-inline-slot[^>]*>.*?</aside>\s*)?<div class="article-share">',
            html_text, re.IGNORECASE | re.DOTALL,
        )
        if not match:
            return ""
        body_html = match.group(1)
        body_html = re.sub(r"</p>", "\n\n", body_html, flags=re.IGNORECASE)
        body_html = re.sub(r"</h[2-4]>", "\n\n", body_html, flags=re.IGNORECASE)
        import html as _html
        plain = _html.unescape(re.sub(r"<[^>]+>", " ", body_html))
        plain = re.sub(r"[ \t]+", " ", plain)
        plain = re.sub(r"\n\s*\n+", "\n\n", plain)
        return plain.strip()
    except Exception:
        return ""

def _durable_incident_anchor(item, include_archive_body=False):
    """Return one deterministic structured incident identity for any article-like item.

    This identity is independent of mutable headlines, model classifications and
    persistent story IDs. It is intentionally usable at feed intake, publication,
    archive migration and final rendering so one fragmented registry cannot create
    several public URLs for the same named real-world incident.
    """
    if not isinstance(item, dict) or incident_anchor_key is None:
        return ""
    existing = str(item.get("incident_anchor_key") or "").strip()
    if existing:
        return existing
    body = str(item.get("body") or item.get("article_text") or "")
    if include_archive_body and not body:
        body = _archive_article_body(item)
    try:
        key = incident_anchor_key(
            titles=(
                item.get("headline", ""),
                item.get("source_headline", ""),
                item.get("title", ""),
                item.get("source_title", ""),
                item.get("teaser", ""),
            ),
            facts=item.get("facts", ()) or (),
            locations=item.get("locations", ()) or (),
            agencies=item.get("agencies", ()) or (),
            event_types=item.get("event_types", ()) or (),
            entities=item.get("entities", ()) or (),
            body=body,
        )
    except Exception:
        return ""
    key = str(key or "").strip()
    if key:
        item["incident_anchor_key"] = key
    return key


def _archive_entry_publishable(entry):
    if _is_nonstory_placeholder(entry):
        return False
    if _is_publisher_self_promotion(entry):
        return False
    if entry.get("is_custom"):
        return True
    wc, pc = _archive_article_metrics(entry)
    return wc >= MIN_HERO_BODY_WORDS and (pc >= 2 or wc >= 180)


def _sports_relevance_evidence(item):
    """Require concrete athletic subject matter for Sports placements.

    The classifier is intentionally broad, so a local museum opening or police
    community event can occasionally be mislabeled as Sports. A Sports hero/card
    must contain an actual sport, team/league, athlete role, competition, result,
    roster transaction, or athletic award. Locality is enforced separately by
    ``_hero_eligible``.
    """
    text = _text_for_category_match(item)
    if not text:
        return False

    explicit_organizations = (
        r"\bst\.? lucie mets\b",
        r"\bflorida state league\b",
        r"\bfsl\b",
        r"\bminor league baseball\b",
        r"\bmlb\b",
        r"\bncaa\b",
        r"\bfhsaa\b",
        r"\b(?:varsity|junior varsity|jv)\b",
        r"\bathletic(?:s| department| program)?\b",
    )
    sport_subjects = (
        r"\bbaseball\b", r"\bfootball\b", r"\bbasketball\b",
        r"\bsoftball\b", r"\bsoccer\b", r"\bvolleyball\b",
        r"\btennis\b", r"\bgolf\b", r"\blacrosse\b",
        r"\bwrestling\b", r"\btrack and field\b", r"\bcross country\b",
        r"\bswimming\b", r"\bdiving\b", r"\bhockey\b",
        r"\bpickleball\b", r"\bgymnastics\b", r"\bcheerleading\b",
        r"\bspeed skating\b", r"\bmotorsports?\b", r"\bauto racing\b",
        r"\brunning\b", r"\broad race\b",
    )
    athlete_roles = (
        r"\bathlete\b", r"\bplayer\b", r"\bcoach\b", r"\bteam\b",
        r"\bpitcher\b", r"\bbatter\b", r"\bcatcher\b",
        r"\bquarterback\b", r"\brunning back\b", r"\bwide receiver\b",
        r"\bgoalkeeper\b", r"\bgoalie\b", r"\bswimmer\b",
        r"\brunner\b", r"\bgolfer\b", r"\bwrestler\b",
    )
    competitive_context = (
        r"\bgame\b", r"\bmatch\b", r"\bmeet\b", r"\brace\b",
        r"\btournament\b", r"\bchampionship\b", r"\bplayoffs?\b",
        r"\bseason\b", r"\bscore\b", r"\bstandings\b", r"\brecord\b",
        r"\bwin(?:s|ning)?\b", r"\bwon\b", r"\bloss\b", r"\blost\b",
        r"\bdefeat(?:s|ed)?\b", r"\bbeats?\b", r"\bsweep(?:s|t)?\b",
        r"\broster\b", r"\bdraft(?:ed)?\b", r"\bsign(?:s|ed|ing)\b",
        r"\brecruit(?:ed|ing|ment)?\b", r"\bcommits?\b", r"\bcommitted\b",
        r"\bplayer of the week\b", r"\bpitcher of the week\b",
        r"\bathlete of the week\b", r"\bcoach of the year\b",
        r"\bnamed .*\b(?:player|pitcher|athlete|coach)\b",
        r"\bhome run\b", r"\brbi\b", r"\binnings?\b",
        r"\btouchdown\b", r"\bgoal\b",
    )
    sports_facility = (
        r"\bsports complex\b", r"\bathletic complex\b",
        r"\bstadium\b", r"\bballpark\b", r"\bclover park\b",
        r"\btraining camp\b",
    )

    has_org = any(re.search(pattern, text, re.I) for pattern in explicit_organizations)
    has_subject = any(re.search(pattern, text, re.I) for pattern in sport_subjects)
    has_role = any(re.search(pattern, text, re.I) for pattern in athlete_roles)
    has_context = any(re.search(pattern, text, re.I) for pattern in competitive_context)
    has_facility = any(re.search(pattern, text, re.I) for pattern in sports_facility)

    return bool(
        has_org
        or has_facility
        or (has_subject and (has_context or has_role))
        or (has_role and has_context)
    )



_SPORTS_MONTH_NUMBERS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}
_SPORTS_WEEKDAY_NUMBERS = {
    "monday": 0, "mon": 0,
    "tuesday": 1, "tue": 1, "tues": 1,
    "wednesday": 2, "wed": 2,
    "thursday": 3, "thu": 3, "thur": 3, "thurs": 3,
    "friday": 4, "fri": 4,
    "saturday": 5, "sat": 5,
    "sunday": 6, "sun": 6,
}
_SPORTS_MONTH_PATTERN = (
    r"jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|"
    r"jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|"
    r"nov(?:ember)?|dec(?:ember)?"
)
_SPORTS_WEEKDAY_PATTERN = (
    r"monday|tuesday|wednesday|thursday|friday|saturday|sunday|"
    r"mon\.?|tue(?:s)?\.?|wed\.?|thu(?:r|rs)?\.?|fri\.?|sat\.?|sun\.?"
)
_SPORTS_PREVIEW_REASON = "sports_event_window_expired"
_KNOWN_SPORTS_EVENT_WINDOWS = (
    {
        # Permanent regression identity for the expired July 21-26 Fort Myers
        # homestand. Production has surfaced this release through multiple
        # syndication URLs and has appended publisher names to the feed title,
        # so fixture matching must tolerate only those deterministic variants.
        "title_aliases": (
            "mets back at clover park for series vs fort myers",
            (
                "st lucie mets host fort myers for seven game series at clover park "
                "starting tuesday"
            ),
            (
                "st lucie mets return to clover park for seven game homestand "
                "against fort myers"
            ),
        ),
        "source_url_fragments": (
            "/mets-back-at-clover-park-for-series-vs-fort-myers/n-6390598",
            "/sports/mets-back-at-clover-park-for-series-vs-fort-myers/",
        ),
        "start_date": "2026-07-21",
        "end_date": "2026-07-26",
    },
)


def _normalized_sports_identity(value):
    value = str(value or "").lower()
    value = re.sub(r"[^a-z0-9]+", " ", value)
    return re.sub(r"\s+", " ", value).strip()


def _known_sports_event_dates(item):
    item = item or {}
    title_values = {
        _normalized_sports_identity(item.get("source_title")),
        _normalized_sports_identity(item.get("title")),
        _normalized_sports_identity(item.get("headline")),
    }
    source_url = str(
        item.get("source_url") or item.get("_source_url") or item.get("link") or ""
    ).lower()
    for known in _KNOWN_SPORTS_EVENT_WINDOWS:
        aliases = tuple(known.get("title_aliases") or ())
        url_fragments = tuple(known.get("source_url_fragments") or ())
        title_match = any(
            observed == alias or observed.startswith(f"{alias} ")
            for observed in title_values
            if observed
            for alias in aliases
        )
        url_match = any(fragment in source_url for fragment in url_fragments)
        if title_match or url_match:
            return [
                datetime.fromisoformat(known["start_date"]).date(),
                datetime.fromisoformat(known["end_date"]).date(),
            ]
    return []


def _sports_preview_blob(item):
    """Return bounded source copy used only for deterministic event-window checks."""
    item = item or {}
    parts = [
        item.get("source_title") or item.get("title") or item.get("headline") or "",
        item.get("summary") or item.get("teaser") or "",
        item.get("article_text") or item.get("body") or "",
    ]
    return " ".join(str(part or "") for part in parts)[:16000]


def _sports_preview_evidence(item):
    """Identify forward-looking sports previews without confusing them with recaps."""
    item = item or {}
    title = str(
        item.get("source_title") or item.get("title") or item.get("headline") or ""
    ).lower()
    blob = _sports_preview_blob(item).lower()

    title_result = bool(
        re.search(r"\b\d{1,3}\s*[-–—]\s*\d{1,3}\b", title)
        or re.search(
            r"\b(?:beat|beats|defeat|defeats|defeated|won|wins|lost|falls?|rall(?:y|ies|ied)|"
            r"shut(?:s)? out|walks? off|clinches?|captures?|claims?)\b",
            title,
        )
    )
    title_preview = bool(
        re.search(
            r"\b(?:host|hosts|hosting|visit|visits|face|faces|open|opens|begin|begins|"
            r"start|starts|starting|return|returns|set to|scheduled to|will)\b",
            title,
        )
        and re.search(
            r"\b(?:game|games|match|meet|race|series|homestand|tournament|season|"
            r"mets|baseball|football|basketball|soccer|softball|volleyball|hockey)\b",
            title,
        )
    ) or bool(re.search(r"\b(?:preview|upcoming|schedule|tickets?|promotions?)\b", title))

    if title_result:
        return False
    if title_preview:
        return True

    strong_body_preview = bool(
        re.search(
            r"\b(?:return|returns|back)\b.{0,100}\b(?:series|homestand)\b",
            blob,
        )
        or re.search(
            r"\b(?:six|seven|eight|nine|\d+)[ -]day,?\s+"
            r"(?:six|seven|eight|nine|\d+)[ -]game series\b",
            blob,
        )
    )
    if strong_body_preview:
        return True

    body_preview = bool(
        re.search(
            r"\b(?:will host|will face|will play|set to host|set to face|scheduled to|"
            r"upcoming|homestand|series begins|series opens|series starts|first pitch is|"
            r"tickets are|promotion schedule|game schedule)\b",
            blob,
        )
    )
    body_result = bool(
        re.search(r"\b\d{1,3}\s*[-–—]\s*\d{1,3}\b", blob)
        and re.search(
            r"\b(?:final|beat|defeat|won|lost|scored|rallied|innings?|struck out|"
            r"earned the win|save|rbi|home run)\b",
            blob,
        )
    )
    return body_preview and not body_result


def _sports_reference_datetime(item, reference_time=None):
    """Resolve a stable timezone-aware anchor for year inference and expiry checks."""
    if reference_time is None:
        reference_time = datetime.now(timezone.utc)
    if reference_time.tzinfo is None:
        reference_time = reference_time.replace(tzinfo=timezone.utc)

    raw = str((item or {}).get("published") or (item or {}).get("published_raw") or "").strip()
    if raw:
        try:
            from email.utils import parsedate_to_datetime
            parsed = parsedate_to_datetime(raw)
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed.astimezone(timezone.utc), reference_time.astimezone(timezone.utc)
        except Exception:
            pass
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed.astimezone(timezone.utc), reference_time.astimezone(timezone.utc)
        except Exception:
            pass
    return reference_time.astimezone(timezone.utc), reference_time.astimezone(timezone.utc)


def _sports_event_year(month, explicit_year, anchor_date):
    if explicit_year:
        return int(explicit_year)
    year = anchor_date.year
    # Keep December/January previews near New Year attached to the closest season.
    if month <= 2 and anchor_date.month >= 11:
        year += 1
    elif month >= 11 and anchor_date.month <= 2:
        year -= 1
    return year


def _sports_safe_date(year, month, day):
    try:
        return datetime(int(year), int(month), int(day)).date()
    except (TypeError, ValueError):
        return None


def _extract_sports_event_dates(item, reference_time=None):
    """Extract explicit calendar dates from a preview and identify stated ranges."""
    blob = _sports_preview_blob(item)
    source_dt, now_dt = _sports_reference_datetime(item, reference_time)
    anchor = source_dt.astimezone(ZoneInfo("America/New_York")).date()
    known_dates = _known_sports_event_dates(item)
    if known_dates:
        return sorted(set(known_dates)), True, now_dt
    dates = set()
    explicit_range = False

    def add_date(month_token, day_token, year_token=None, *, fallback_month=None, fallback_year=None):
        token = str(month_token or "").lower().rstrip(".")
        month = _SPORTS_MONTH_NUMBERS.get(token) if token else fallback_month
        if not month:
            return None
        year = int(year_token) if year_token else (fallback_year or _sports_event_year(month, None, anchor))
        parsed = _sports_safe_date(year, month, day_token)
        if parsed:
            dates.add(parsed)
        return parsed

    range_re = re.compile(
        rf"\b(?P<m1>{_SPORTS_MONTH_PATTERN})\.?\s+(?P<d1>\d{{1,2}})(?:st|nd|rd|th)?"
        rf"(?:,?\s*(?P<y1>20\d{{2}}))?\s*(?:-|–|—|to|through|until)\s*"
        rf"(?:(?:{_SPORTS_WEEKDAY_PATTERN}),?\s*)?"
        rf"(?:(?P<m2>{_SPORTS_MONTH_PATTERN})\.?\s+)?"
        rf"(?P<d2>\d{{1,2}})(?:st|nd|rd|th)?(?:,?\s*(?P<y2>20\d{{2}}))?\b",
        re.I,
    )
    for match in range_re.finditer(blob):
        explicit_range = True
        first = add_date(match.group("m1"), match.group("d1"), match.group("y1"))
        first_month = first.month if first else _SPORTS_MONTH_NUMBERS.get(match.group("m1").lower().rstrip("."))
        first_year = first.year if first else _sports_event_year(first_month, match.group("y1"), anchor)
        second_month_token = match.group("m2")
        second_month = (
            _SPORTS_MONTH_NUMBERS.get(second_month_token.lower().rstrip("."))
            if second_month_token else first_month
        )
        second_year = int(match.group("y2")) if match.group("y2") else first_year
        if second_month and first_month and second_month < first_month and not match.group("y2"):
            second_year += 1
        add_date(
            second_month_token,
            match.group("d2"),
            match.group("y2"),
            fallback_month=second_month,
            fallback_year=second_year,
        )

    single_re = re.compile(
        rf"\b(?P<m>{_SPORTS_MONTH_PATTERN})\.?\s+(?P<d>\d{{1,2}})(?:st|nd|rd|th)?"
        rf"(?:,?\s*(?P<y>20\d{{2}}))?\b",
        re.I,
    )
    for match in single_re.finditer(blob):
        add_date(match.group("m"), match.group("d"), match.group("y"))

    numeric_re = re.compile(
        r"(?<!\d)(?P<m>1[0-2]|0?[1-9])/(?P<d>3[01]|[12]\d|0?[1-9])"
        r"(?:/(?P<y>20\d{2}|\d{2}))?(?!\d)"
    )
    for match in numeric_re.finditer(blob):
        year_token = match.group("y")
        if year_token and len(year_token) == 2:
            year_token = f"20{year_token}"
        add_date(
            "",
            match.group("d"),
            year_token,
            fallback_month=int(match.group("m")),
            fallback_year=(int(year_token) if year_token else None),
        )

    weekday_range_re = re.compile(
        rf"\b(?:from\s+)?(?P<w1>{_SPORTS_WEEKDAY_PATTERN})\s*"
        rf"(?:-|–|—|to|through|until)\s*(?P<w2>{_SPORTS_WEEKDAY_PATTERN})\b",
        re.I,
    )
    for match in weekday_range_re.finditer(blob):
        first_token = match.group("w1").lower().rstrip(".")
        second_token = match.group("w2").lower().rstrip(".")
        first_weekday = _SPORTS_WEEKDAY_NUMBERS.get(first_token)
        second_weekday = _SPORTS_WEEKDAY_NUMBERS.get(second_token)
        if first_weekday is None or second_weekday is None:
            continue
        explicit_range = True
        weekday_anchor = min(dates) if dates else anchor
        previous_start = weekday_anchor - timedelta(
            days=(weekday_anchor.weekday() - first_weekday) % 7
        )
        next_start = weekday_anchor + timedelta(
            days=(first_weekday - weekday_anchor.weekday()) % 7
        )
        start_date = min(
            (previous_start, next_start),
            key=lambda candidate: (
                abs((candidate - weekday_anchor).days), candidate < weekday_anchor
            ),
        )
        end_date = start_date + timedelta(days=(second_weekday - first_weekday) % 7)
        dates.add(start_date)
        dates.add(end_date)

    return sorted(dates), explicit_range, now_dt


def _sports_event_window_assessment(item, reference_time=None):
    """Return deterministic expiry evidence for one Sports source or placement."""
    item = item or {}
    base = {
        "is_preview": False,
        "expired": False,
        "reason": "",
        "event_dates": [],
        "event_end_date": "",
    }
    if item.get("is_custom") or item.get("authoritative_custom"):
        return {**base, "reason": "custom_article_exempt"}
    if not _sports_preview_evidence(item):
        return {**base, "reason": "not_a_sports_preview"}

    dates, explicit_range, now_dt = _extract_sports_event_dates(item, reference_time)
    result = {**base, "is_preview": True, "event_dates": [value.isoformat() for value in dates]}
    if not dates:
        result["reason"] = "event_date_not_resolved"
        return result

    blob = _sports_preview_blob(item).lower()
    multi_day = bool(re.search(r"\b(?:series|homestand|tournament|camp|multi-day|weeklong)\b", blob))
    if multi_day and len(dates) < 2 and not explicit_range:
        result["reason"] = "event_end_not_resolved"
        return result

    event_end = max(dates)
    today = now_dt.astimezone(ZoneInfo("America/New_York")).date()
    expired = event_end < today
    result.update({
        "expired": expired,
        "reason": _SPORTS_PREVIEW_REASON if expired else "event_window_open",
        "event_end_date": event_end.isoformat(),
        "reference_date": today.isoformat(),
    })
    return result


def _filter_expired_sports_previews(category_key, headlines, reference_time=None):
    """Remove only previews whose complete explicit event window has passed."""
    items = list(headlines or [])
    if category_key != "sports":
        return items, []

    kept = []
    rejected = []
    for item in items:
        assessment = _sports_event_window_assessment(item, reference_time)
        if not assessment.get("expired"):
            kept.append(item)
            continue
        item["sports_rejection_reason"] = _SPORTS_PREVIEW_REASON
        item["sports_event_end_date"] = assessment.get("event_end_date", "")
        rejected.append({
            "headline": str(item.get("title") or item.get("headline") or ""),
            "source_url": str(item.get("source_url") or item.get("link") or ""),
            "published": str(item.get("published") or item.get("published_raw") or ""),
            "reason": _SPORTS_PREVIEW_REASON,
            "event_end_date": assessment.get("event_end_date", ""),
            "event_dates": assessment.get("event_dates", []),
        })
    return kept, rejected


def _archive_sports_event_window_expired(entry, reference_time=None):
    if not isinstance(entry, dict):
        return False
    probe = dict(entry)
    probe.setdefault("title", entry.get("headline", ""))
    probe.setdefault("source_title", entry.get("source_title", "") or entry.get("headline", ""))
    probe.setdefault("summary", entry.get("teaser", ""))
    probe.setdefault("article_text", _archive_article_body(entry))
    probe.setdefault("published", entry.get("first_published") or entry.get("date") or "")
    return bool(_sports_event_window_assessment(probe, reference_time).get("expired"))


def _filter_expired_sports_live_placements(items, reference_time=None):
    """Remove expired Sports previews from homepage-facing live placement pools.

    Category generation and category archive recovery already reject these previews.
    This final renderer-side boundary prevents a recently archived generated copy from
    re-entering Top Stories, Latest News, or county panels through homepage backfill.
    Historical archive records and their article pages remain intact.
    """
    kept = []
    rejected = []
    for item in list(items or []):
        category_keys = set(_item_category_memberships(item))
        category_keys.update(
            value for value in (item.get("category_key"), item.get("cat_key")) if value
        )
        if "sports" not in category_keys:
            kept.append(item)
            continue

        assessment = _sports_event_window_assessment(item, reference_time)
        if not assessment.get("expired"):
            kept.append(item)
            continue

        rejected.append({
            "headline": str(item.get("headline") or item.get("title") or ""),
            "source_title": str(item.get("source_title") or ""),
            "source_url": str(item.get("source_url") or item.get("link") or ""),
            "slug": str(item.get("_archived_slug") or item.get("slug") or ""),
            "reason": _SPORTS_PREVIEW_REASON,
            "event_end_date": assessment.get("event_end_date", ""),
            "event_dates": assessment.get("event_dates", []),
        })
    return kept, rejected

def _filter_contextless_update_live_placements(items):
    """Suppress generated update articles whose lead omits the underlying event.

    This is a live-surface guard only. Historical archive records and direct article
    pages remain intact until a corrected generation updates them in place. Custom
    TCT articles are never altered by this automated gate.
    """
    kept = []
    rejected = []
    for item in list(items or []):
        if item.get("is_custom") or item.get("authoritative_custom"):
            kept.append(item)
            continue
        probe = dict(item)
        probe.setdefault("story_form", _source_story_form(probe))
        diagnostics = _update_lead_diagnostics(probe, probe)
        if not diagnostics.get("required") or diagnostics.get("passed"):
            kept.append(item)
            continue
        rejected.append({
            "headline": str(item.get("headline") or item.get("title") or ""),
            "source_title": str(item.get("source_title") or ""),
            "source_url": str(item.get("source_url") or item.get("link") or ""),
            "slug": str(item.get("_archived_slug") or item.get("slug") or ""),
            "reason": "contextless_update_lead",
            "missing": diagnostics.get("missing", []),
            "baseline_anchor": diagnostics.get("baseline_anchor", ""),
            "novelty_anchor": diagnostics.get("novelty_anchor", ""),
        })
    return kept, rejected




def _category_contract_config(category_key):
    return dict(CATEGORY_ELIGIBILITY_CONTRACTS.get(category_key, {
        "mode": "observe_only",
        "policy": "unregistered_category",
    }))


def _category_contract_hits(text, terms):
    """Return phrase-aware contract terms found in normalized story text."""
    normalized = re.sub(r"\s+", " ", str(text or "").lower()).strip()
    hits = []
    for term in terms:
        phrase = re.sub(r"\s+", " ", str(term or "").lower()).strip()
        if not phrase:
            continue
        pattern = r"(?<![a-z0-9])" + re.escape(phrase).replace(r"\ ", r"\s+") + r"(?![a-z0-9])"
        if re.search(pattern, normalized):
            hits.append(phrase)
    return hits


def _business_category_contract_assessment(item, base):
    """Enforced Business & Development primary-focus contract."""
    story_text = _text_for_category_match(item)
    source_blob = _source_county_authority_blob(item)

    local_terms = (
        "treasure coast", "martin county", "st lucie county", "st. lucie county",
        "indian river county", "stuart", "jensen beach", "palm city", "hobe sound",
        "port salerno", "indiantown", "port st lucie", "port st. lucie",
        "fort pierce", "vero beach", "sebastian", "fellsmere", "hutchinson island",
        "jupiter island",
    )
    local_hits = _category_contract_hits(source_blob, local_terms)

    positive_groups = {
        "business_opening_closure_expansion": [
            "grand opening", "opens new", "opening new", "opens in", "opening in",
            "closes", "closing", "closure", "shuts down", "expands", "expansion",
            "relocates", "relocation", "new store", "new restaurant", "new business",
            "new location", "adds location",
        ],
        "development_project": [
            "development project", "development plan", "development proposal",
            "developer", "developers", "redevelopment", "under construction",
            "construction", "breaks ground", "groundbreaking", "mixed-use",
            "commercial project", "housing development", "apartment project",
            "hotel project", "marriott project", "data center", "warehouse",
            "industrial park", "site plan", "development order", "land use",
            "rezoning", "demolition", "mall demolition",
        ],
        "jobs_employers_economic_development": [
            "jobs", "job creation", "hiring", "hires", "employer", "employers",
            "workforce", "economic development", "business recruitment",
            "business incentive", "tax incentive", "commercial investment",
        ],
        "business_transaction": [
            "acquires", "acquisition", "merger", "merges", "sold to", "sale of",
            "buys", "purchases", "investment", "invests", "bankruptcy",
        ],
        "commercial_real_estate": [
            "commercial real estate", "retail center", "shopping center", "mall",
            "office building", "industrial property", "commercial property",
            "restaurant", "retail", "hotel",
        ],
    }
    positive_signals = []
    for name, terms in positive_groups.items():
        hits = _category_contract_hits(story_text, terms)
        if hits:
            positive_signals.append(f"{name}:{hits[0]}")

    competing_groups = {
        "crime_public_safety": [
            "arrested", "arrest", "charged", "shooting", "homicide", "murder",
            "robbery", "burglary", "stabbing", "drug bust", "drug trafficking",
            "meth", "fentanyl", "cocaine", "fatal crash", "police pursuit",
            "sheriff investigation",
        ],
        "election_political_process": [
            "early voting", "primary election", "election day", "polling place",
            "candidate", "ballot", "voter registration", "supervisor of elections",
        ],
        "animal_welfare": [
            "dogs are suffering", "dogs suffering", "animal welfare", "animal control",
            "animal cruelty", "cats rescued", "dog rescue", "pet adoption",
        ],
        "generic_heat_environment_policy": [
            "extreme heat", "tree canopy", "more trees", "trees and shade",
            "shade structures", "heat advisory", "urban heat",
        ],
        "sports": [
            "game recap", "wins over", "defeats", "championship", "tournament",
            "baseball game", "football game", "soccer match",
        ],
        "schools_education": [
            "school board", "school district", "new school", "students", "teacher",
            "principal", "curriculum",
        ],
        "entertainment_event": [
            "concert", "festival", "parade", "art exhibition", "museum exhibition",
        ],
    }
    competing_signals = []
    for name, terms in competing_groups.items():
        hits = _category_contract_hits(story_text, terms)
        if hits:
            competing_signals.append(f"{name}:{hits[0]}")

    reason = "primary_business_development_focus_confirmed"
    eligible = True

    if not local_hits:
        eligible = False
        reason = "missing_treasure_coast_business_nexus"
    elif not positive_signals:
        eligible = False
        if competing_signals:
            reason = "competing_story_form_without_business_development_focus"
        else:
            reason = "missing_primary_business_development_focus"
    elif competing_signals:
        # A strong development/business event may legitimately involve government,
        # schools, or public controversy. Crime, elections, animal welfare and generic
        # heat/tree policy are disqualifying unless the source has a separate,
        # unmistakable commercial/development event beyond a generic noun.
        disqualifying = {
            signal.split(":", 1)[0] for signal in competing_signals
        } & {
            "crime_public_safety", "election_political_process", "animal_welfare",
            "generic_heat_environment_policy", "sports", "entertainment_event",
        }
        if disqualifying:
            eligible = False
            reason = "competing_story_form_without_business_development_focus"

    base.update({
        "contract_version": BUSINESS_ELIGIBILITY_CONTRACT_VERSION,
        "eligible": eligible,
        "would_reject": not eligible,
        "reason": reason,
        "positive_signals": positive_signals,
        "competing_signals": competing_signals,
        "local_nexus_signals": [f"source_locality:{hit}" for hit in local_hits[:6]],
    })
    return base


def _crime_category_contract_assessment(item, base):
    """Enforce a visible Crime & Safety focus instead of trusting classifier bleed."""
    presentation = _normalize_nonstory_text(" ".join([
        str(item.get("headline") or item.get("title") or ""),
        str(item.get("teaser") or item.get("summary") or ""),
        str(item.get("body") or "")[:500],
    ]))
    positive_groups = {
        "law_enforcement_crime": [
            "arrest", "arrested", "charged", "charges", "police", "sheriff",
            "deputy", "deputies", "trooper", "homicide", "murder", "shooting",
            "shot", "robbery", "burglary", "theft", "steal", "stealing", "stole",
            "assault", "battery", "sentenced", "prison", "drug", "fentanyl",
            "meth", "cocaine", "fraud", "scam", "stolen",
        ],
        "public_safety_incident": [
            "crash", "collision", "hit and run", "hit-and-run", "vehicle fire",
            "house fire", "structure fire", "electrical fire", "brush fire",
            "vegetation fire", "wildfire", "rescue", "rescued", "rescues",
            "drown", "drowned", "drowns", "drowning", "missing child",
            "missing person", "found dead", "dies after", "killed", "killing",
            "emergency", "evacuation", "boil water", "warning", "active shooter",
            "metal detector", "crisis alert", "road closed", "lane closed",
        ],
    }
    positives = []
    for name, terms in positive_groups.items():
        hits = _category_contract_hits(presentation, terms)
        if hits:
            positives.append(f"{name}:{hits[0]}")
    eligible = bool(positives)
    base.update({
        "contract_version": CRIME_ELIGIBILITY_CONTRACT_VERSION,
        "eligible": eligible,
        "would_reject": not eligible,
        "reason": "primary_crime_safety_focus_confirmed" if eligible else "missing_primary_crime_safety_focus",
        "positive_signals": positives,
        "competing_signals": [],
    })
    return base


def _things_to_do_category_contract_assessment(item, base):
    """Require a genuinely local, attendable activity for Things To Do.

    Classification is still required by the routing layer. This contract is a second,
    deterministic boundary so a bad/stale classifier label cannot turn an animal-
    welfare update, crime story, government action, or generic community reference
    into an events/activities story.
    """
    title = _normalize_nonstory_text(str(item.get("headline") or item.get("title") or ""))
    presentation = _normalize_nonstory_text(" ".join([
        str(item.get("headline") or item.get("title") or ""),
        str(item.get("teaser") or item.get("summary") or ""),
        str(item.get("body") or item.get("article_text") or "")[:700],
    ]))

    activity_groups = {
        "scheduled_event": [
            "festival", "concert", "parade", "fair", "farmers market", "community event",
            "family event", "holiday event", "celebration", "fundraiser", "benefit",
            "movie night", "live music", "performance", "workshop", "class", "lecture",
            "tickets", "registration", "open house", "block party", "street festival",
        ],
        "food_dining_experience": [
            "food and wine", "food festival", "wine festival", "tasting", "grand opening",
            "restaurant opens", "restaurant opening", "new restaurant", "dining event",
        ],
        "recreation_participation": [
            "triathlon", "5k", "10k", "road race", "fun run", "charity walk",
            "bike ride", "kayak", "paddle", "fishing tournament",
        ],
        "arts_culture_program": [
            "art show", "art exhibition", "museum event", "museum program",
            "theater performance", "theatre performance", "dance performance",
            "author talk", "book signing",
        ],
    }
    positive_signals = []
    title_activity_hits = []
    for name, terms in activity_groups.items():
        hits = _category_contract_hits(presentation, terms)
        if hits:
            positive_signals.append(f"{name}:{hits[0]}")
        title_activity_hits.extend(_category_contract_hits(title, terms))

    competing_groups = {
        "crime_public_safety": [
            "arrested", "arrest", "charged", "charges", "sheriff", "deputies", "police",
            "homicide", "murder", "shooting", "robbery", "burglary", "fatal crash",
            "collision", "investigation",
        ],
        "animal_welfare_update": [
            "hoarding case", "animal hoarding", "animal cruelty", "animals rescued",
            "dogs rescued", "cats rescued", "medical grooming", "shelter staff",
            "adoption applications", "rescued animals",
        ],
        "government_action": [
            "county commission", "city council", "school board", "budget", "ordinance",
            "rezoning", "tax rate", "public hearing",
        ],
    }
    competing_signals = []
    for name, terms in competing_groups.items():
        hits = _category_contract_hits(presentation, terms)
        if hits:
            competing_signals.append(f"{name}:{hits[0]}")

    local = _has_treasure_coast_locality(item)
    eligible = bool(local and positive_signals)
    reason = "local_attendable_activity_confirmed" if eligible else "missing_attendable_activity_focus"
    if not local:
        reason = "missing_treasure_coast_activity_nexus"
    elif competing_signals and not title_activity_hits:
        eligible = False
        reason = "competing_story_form_without_attendable_activity_focus"

    base.update({
        "contract_version": THINGS_TO_DO_ELIGIBILITY_CONTRACT_VERSION,
        "eligible": eligible,
        "would_reject": not eligible,
        "reason": reason,
        "positive_signals": positive_signals,
        "competing_signals": competing_signals,
        "local_nexus_signals": ["treasure_coast_locality"] if local else [],
    })
    return base


def _category_eligibility_contract_assessment(category_key, item):
    """Evaluate the explicit per-category semantic contract.

    Local Government, Business & Development, Crime & Safety, and Things To Do are
    enforced through the same shared interface. Remaining topic beats stay observe-only
    until their own regression fixtures are production-validated.
    """
    config = _category_contract_config(category_key)
    base = {
        "contract_version": CATEGORY_ELIGIBILITY_CONTRACT_VERSION,
        "category_key": category_key,
        "mode": config.get("mode", "observe_only"),
        "policy": config.get("policy", "unregistered_category"),
        "eligible": True,
        "would_reject": False,
        "reason": "contract_not_enforced",
        "positive_signals": [],
        "competing_signals": [],
    }
    if not isinstance(item, dict):
        base.update({"eligible": False, "would_reject": True, "reason": "missing_story"})
        return base
    if item.get("is_custom") or item.get("authoritative_custom"):
        base.update({"eligible": True, "reason": "custom_authority_exempt"})
        if category_key == "business":
            base["contract_version"] = BUSINESS_ELIGIBILITY_CONTRACT_VERSION
        elif category_key == "crime":
            base["contract_version"] = CRIME_ELIGIBILITY_CONTRACT_VERSION
        elif category_key == "things_to_do":
            base["contract_version"] = THINGS_TO_DO_ELIGIBILITY_CONTRACT_VERSION
        return base
    if category_key == "business":
        return _business_category_contract_assessment(item, base)
    if category_key == "crime":
        return _crime_category_contract_assessment(item, base)
    if category_key == "things_to_do":
        return _things_to_do_category_contract_assessment(item, base)
    if category_key != "local_gov":
        return base

    text = _text_for_category_match(item)
    governing_body_terms = [
        "city council", "town council", "village council", "county commission",
        "county commissioners", "board of county commissioners", "school board",
        "planning and zoning board", "planning board", "zoning board",
        "community redevelopment agency", "city commission", "fire district board",
    ]
    government_entity_terms = governing_body_terms + [
        "city manager", "county administrator", "school district", "public works",
        "city hall", "county government", "municipal government", "elections office",
        "county fire rescue", "city fire rescue", "parks and recreation",
        "parks department", "county utilities", "city utilities",
        "florida department of environmental protection",
        "department of environmental protection",
        "supervisor of elections", "fire district", "water district", "utility authority",
        "city of port st. lucie", "city of fort pierce", "city of stuart",
        "city of vero beach", "city of sebastian", "city of fellsmere",
        "village of indiantown", "martin county government",
        "st. lucie county government", "st lucie county government",
        "indian river county government",
    ]
    local_jurisdiction_terms = [
        "port st. lucie", "port st lucie", "fort pierce", "stuart", "vero beach",
        "sebastian", "fellsmere", "indiantown", "martin county", "st. lucie county",
        "st lucie county", "indian river county",
    ]
    decision_action_terms = [
        "votes", "voted", "vote to", "approves", "approved", "rejects", "rejected",
        "adopts", "adopted", "passes", "passed", "enacts", "enacted", "bans",
        "banned", "pauses", "paused", "extends", "extended", "delays", "delayed",
        "deadlocks", "deadlocked", "allocates", "allocated", "awards", "awarded",
        "challenges", "challenged", "orders", "ordered", "fines", "fined",
        "sets tax", "sets millage", "raises taxes", "cuts taxes", "seeks public input",
    ]
    jurisdiction_decision_terms = [
        "votes", "voted", "vote to", "approves", "approved", "rejects", "rejected",
        "adopts", "adopted", "enacts", "enacted", "bans", "banned", "pauses",
        "paused", "deadlocks", "deadlocked", "allocates", "allocated",
        "challenges", "challenged", "orders", "ordered", "fines", "fined",
        "sets tax", "sets millage", "raises taxes", "cuts taxes",
    ]
    administrative_action_terms = [
        "appoints", "appointed", "hires", "hired", "fires", "fired", "resigns",
        "resigned", "launches", "launched", "opens registration", "begins registration",
        "names new", "selects", "selected", "announces program", "announced program",
        "cuts positions", "cut positions", "eliminates positions", "eliminated positions",
        "closes school", "merges schools", "renews contract", "renewed contract",
        "rebuilds", "rebuilding", "repairs", "changes service", "expands service",
        "reduces service",
    ]
    intrinsic_policy_terms = [
        "ordinance", "rezoning", "zoning", "land use", "development order", "millage",
        "municipal budget", "county budget", "city budget", "budget workshop",
        "public hearing", "public meeting", "public workshop", "referendum",
        "moratorium", "tax rate", "property tax", "sales tax", "code enforcement",
        "comprehensive plan", "charter amendment", "government contract",
        "public contract", "waste management fee", "utility rate", "stormwater fee",
        "impact fee", "service fee", "capital improvement", "road project",
        "bridge project", "park renovation", "park rebuild", "procurement",
        "request for proposals", "rfi", "rfp",
    ]
    local_election_terms = [
        "city council election", "county commission election", "school board election",
        "municipal election", "local ballot", "referendum election",
        "supervisor of elections", "candidate forum",
    ]

    body_hits = _category_contract_hits(text, governing_body_terms)
    entity_hits = _category_contract_hits(text, government_entity_terms)
    jurisdiction_hits = _category_contract_hits(text, local_jurisdiction_terms)
    decision_hits = _category_contract_hits(text, decision_action_terms)
    jurisdiction_decision_hits = _category_contract_hits(text, jurisdiction_decision_terms)
    administrative_hits = _category_contract_hits(text, administrative_action_terms)
    policy_hits = _category_contract_hits(text, intrinsic_policy_terms)
    election_hits = _category_contract_hits(text, local_election_terms)

    positive_signals = []
    if policy_hits:
        positive_signals.append("intrinsic_policy:" + policy_hits[0])
    if body_hits and decision_hits:
        positive_signals.append("governing_body_action:" + body_hits[0] + "+" + decision_hits[0])
    if entity_hits and administrative_hits:
        positive_signals.append("government_administration:" + entity_hits[0] + "+" + administrative_hits[0])
    if jurisdiction_hits and jurisdiction_decision_hits:
        positive_signals.append(
            "jurisdiction_decision:" + jurisdiction_hits[0] + "+" + jurisdiction_decision_hits[0]
        )
    if election_hits:
        positive_signals.append("local_election:" + election_hits[0])

    competing_groups = {
        "crime_incident": [
            "flee police", "police pursuit", "high-speed chase", "hiding on roof",
            "arrested", "arrest", "charged", "robbery", "gunpoint", "shooting",
            "homicide", "murder", "suspect", "victim", "burglary", "stabbing",
            "fatal crash", "traffic stop", "deputies say", "police say",
        ],
        "community_feature": [
            "cyclist", "bike ride", "bicycle ride", "fundraising ride", "charity ride",
            "passes through", "honoring friend", "cross-country ride", "2,600-mile ride",
            "2600-mile ride", "memorial ride",
        ],
        "sports_or_recreation": [
            "game recap", "wins over", "defeats", "championship", "tournament",
            "football game", "baseball game", "soccer match",
        ],
        "entertainment_event": ["concert", "festival", "art exhibition", "museum exhibition"],
    }
    competing_signals = []
    for name, terms in competing_groups.items():
        hits = _category_contract_hits(text, terms)
        if hits:
            competing_signals.append(name + ":" + hits[0])

    eligible = bool(positive_signals)
    reason = "central_government_action_confirmed" if eligible else "missing_central_government_action"
    if not eligible and competing_signals:
        reason = "competing_story_form_without_government_action"
    base.update({
        "eligible": eligible,
        "would_reject": not eligible,
        "reason": reason,
        "positive_signals": positive_signals,
        "competing_signals": competing_signals,
    })
    return base


def _compact_category_contract_assessment(assessment, item=None):
    return {
        "contract_version": assessment.get("contract_version", ""),
        "category_key": assessment.get("category_key", ""),
        "mode": assessment.get("mode", ""),
        "policy": assessment.get("policy", ""),
        "eligible": bool(assessment.get("eligible")),
        "would_reject": bool(assessment.get("would_reject")),
        "reason": assessment.get("reason", ""),
        "positive_signals": list(assessment.get("positive_signals") or []),
        "competing_signals": list(assessment.get("competing_signals") or []),
        "local_nexus_signals": list(assessment.get("local_nexus_signals") or []),
        "headline": str((item or {}).get("title") or (item or {}).get("headline") or ""),
        "source_url": str((item or {}).get("link") or (item or {}).get("source_url") or ""),
    }


def _sports_zero_candidate_fast_recovery(category_key, headlines):
    """Return True when Sports has no deterministic hero candidate.

    There is no reason to spend two model attempts asking Claude to manufacture a
    Sports lead from a pool that contains no actual athletic story. The verified
    permanent archive is the safer and faster recovery path.
    """
    if category_key != "sports":
        return False
    return not any(_hero_eligible("sports", item) for item in (headlines or []))


def _things_to_do_zero_candidate_fast_recovery(category_key, headlines):
    """Do not ask Claude to choose a Things To Do lead from a non-event pool."""
    if category_key != "things_to_do":
        return False
    return not any(_hero_eligible("things_to_do", item) for item in (headlines or []))


def _county_zero_candidate_fast_recovery(category_key, headlines):
    """Skip model generation when a county has no source-backed hero candidate."""
    if category_key not in {"martin", "st_lucie", "indian_river"}:
        return False
    return not any(_hero_eligible(category_key, item) for item in (headlines or []))


# Hero selection is stricter than card inclusion. Cards may use softer fallback
# logic to keep a section populated, but a section lead must clearly belong to
# that section.
def _hero_eligible(category_key, h):
    text = _text_for_category_match(h)
    title = (h.get("title", "") or "").lower()
    quality = h.get("source_quality", "")

    if quality in {"thin", "brief", "discovery_only"}:
        return False
    if category_key == "sports" and _sports_event_window_assessment(h).get("expired"):
        return False

    _contract_assessment = _category_eligibility_contract_assessment(category_key, h)
    if _contract_assessment.get("mode") == "enforce" and not _contract_assessment.get("eligible"):
        return False

    # LLM classification is a positive signal, never a bypass around deterministic
    # locality/topic safety rules. The previous early return here meant that one bad
    # classifier label skipped every outside-area block and hard negative below.
    _classified_cats = None
    if STORY_CLASSIFICATION is not None:
        # Look up by the ORIGINAL RSS title first. Generated heroes/cards carry it in
        # source_title; raw feed items have it in title. The rewritten headline is a
        # last resort — it will usually miss, since the map is keyed on RSS titles.
        for _key in (
            (h.get("source_title", "") or "").lower(),
            title,
            (h.get("headline", "") or "").lower(),
        ):
            if not _key:
                continue
            cats = STORY_CLASSIFICATION.get(_key)
            if cats is not None:
                _classified_cats = cats
                break
        # Enforced per-category contracts are the final deterministic topic authority.
        # A stale/missing classifier label may nominate candidates upstream, but it must
        # not veto a story that the enforced contract itself proves belongs in the beat.
        # This is especially important for obvious crime/public-safety stories whose
        # classifier occasionally returns only a county label.
        if _classified_cats == {"none"} and _contract_assessment.get("mode") != "enforce":
            return False

    # Outside-coverage-area block: WPTV serves Palm Beach County and the wider
    # South Florida market, which is NOT the Treasure Coast. If a story is clearly
    # about a place outside Martin/St. Lucie/Indian River counties AND does not
    # mention any Treasure Coast location, it should never be a hero.
    _outside_places = [
        "palm beach", "west palm", "riviera beach", "delray beach", "boca raton",
        "boynton beach", "lake worth", "jupiter", "juno beach", "north palm beach",
        "wellington", "royal palm", "belle glade", "pahokee", "greenacres",
        "westlake", "loxahatchee", "palm beach gardens", "lake park", "mangonia",
        "haverhill", "atlantis", "lantana", "manalapan", "south bay", "glades",
        "miami", "fort lauderdale", "broward", "okeechobee", "orlando", "tampa",
        "jacksonville", "gainesville", "naples", "sarasota", "fort myers",
        "kissimmee", "daytona", "melbourne", "cocoa", "brevard", "st. augustine",
    ]
    _treasure_coast_places = [
        "martin county", "st. lucie", "st lucie", "indian river", "treasure coast",
        "stuart", "jensen beach", "palm city", "hobe sound", "port salerno",
        "port st. lucie", "port st lucie", "fort pierce", "vero beach", "sebastian",
        "fellsmere", "indiantown", "jupiter island", "hutchinson island",
    ]
    _has_outside = any(p in text for p in _outside_places)
    _has_local   = _has_treasure_coast_locality(h)
    # Florida is the statewide section, so Tampa/Orlando/etc. are valid there.
    # Every other section is Treasure Coast-local and must reject an outside-only story.
    if category_key != "florida" and _has_outside and not _has_local:
        return False

    # Universal obituary block — obituaries should NEVER be a hero in any section,
    # including county pages. This is specific to obituary listings (funeral home
    # references, "survived by") and won't catch news coverage of notable deaths,
    # which uses "dies", "killed", "death of" without funeral-listing language.
    if _looks_like_obituary_listing(title, text):
        return False

    topic_terms = {
        "local_gov": ["commission", "commissioner", "city council", "county council", "school board", "zoning", "rezoning", "ordinance", "budget", "tax", "millage", "mayor", "public meeting", "vote", "approved", "approval", "proposal", "hearing", "development order", "planning", "public policy", "ban", "takes effect", "school district", "superintendent", "principal", "education", "student", "teacher", "curriculum", "school closure", "school merger"],
        "crime": ["arrest", "arrested", "charged", "charges", "sheriff", "police", "deputies", "deputy", "officer", "shooting", "stabbed", "stabbing", "homicide", "murder", "crash", "fatal", "killed", "injured", "fire rescue", "missing", "suspect", "victim", "jail", "court", "public safety", "fraud", "burglary", "robbery"],
        "business": ["business", "development", "developer", "real estate", "housing", "restaurant", "store", "retail", "mall", "company", "jobs", "hiring", "economic", "economy", "construction", "project", "commercial", "warehouse", "factory", "plant", "opening", "closing", "closes", "expansion", "wawa", "publix", "downtown", "permit", "property", "market", "walmart", "campbell soup"],
        "sports": ["sports", "football", "basketball", "baseball", "softball", "soccer", "volleyball", "tennis", "golf", "lacrosse", "wrestling", "track", "cross country", "swimming", "game", "score", "win", "wins", "won", "loss", "defeats", "beats", "championship", "playoff", "tournament", "athlete", "coach", "team", "mets", "st. lucie mets", "st lucie mets"],
        "things_to_do": ["event", "events", "festival", "concert", "show", "weekend", "things to do", "restaurant", "food", "arts", "art", "music", "theater", "theatre", "park", "market", "farmers market", "fair", "fundraiser", "community", "parade", "holiday", "museum", "exhibit", "taste", "family-friendly", "activities"],
        "florida": ["florida", "statewide", "state of florida", "insurance", "property insurance", "homeowners insurance", "hurricane", "tropical storm", "weather", "storm", "flooding", "law takes effect", "takes effect", "new law", "new laws", "gas prices", "cost of living", "utility", "utilities", "fpl", "electric bill", "toll", "beaches", "red tide", "environment", "manatee", "everglades", "housing", "rent", "sinkhole", "evacuation", "desantis", "legislature", "lawmakers", "state law", "florida supreme court", "medicaid", "schools statewide", "springs", "wildlife", "boating", "fishing", "tourism", "state park"],
    }

    # Block obituary listings (non-notable individuals) but not news coverage of notable deaths.
    # Terms like "obituary", "survived by", "funeral home" only appear in obit listings —
    # news coverage of notable deaths uses "dies", "killed", "death of" which we allow.
    obit_terms = ["obituary", "obituaries", "survived by", "is survived by",
                  "funeral home", "in memoriam", "memorial service at",
                  "laid to rest", "celebration of life"]

    hard_negatives = {
        "sports":       ["sues", "lawsuit", "campbell soup", "spaghettios", "worms", "walmart",
                         "fertilizer", "ban", "commission", "politics", "arrest", "charged",
                         "shooting", "homicide", "murder", "missing", "fatal crash", "zoning",
                         "ordinance", "budget", "tax", "city council", "county council",
                         "restaurant opens", "business opens", "store opens", "new store",
                         "house fire", "died", "death", "dead", "killed", "fundraiser",
                         "gofundme", "fire broke out", "passed away", "fatal"] + obit_terms,
        "business":     ["shooting", "homicide", "murder", "missing", "fatal crash",
                         "arrest", "arrested", "charged", "stabbing", "robbery", "burglary",
                         "meth", "methamphetamine", "cocaine", "fentanyl", "heroin",
                         "narcotics", "drug bust", "drug trafficking", "trafficking",
                         "seizes", "seized", "dea", "smuggling", "cartel", "overdose",
                         "game recap", "score", "wins over", "defeats", "beats", "championship",
                         "playoff", "tournament", "festival", "concert", "parade"] + obit_terms,
        "crime":        ["restaurant", "business opens", "store opens", "new store", "hiring",
                         "festival", "concert", "event", "game recap", "score", "wins", "defeats",
                         "zoning", "ordinance", "budget vote", "commission vote", "development order"],
        "things_to_do": ["shooting", "homicide", "murder", "fatal crash", "arrest", "charged",
                         "stabbing", "robbery", "burglary", "zoning", "ordinance", "budget",
                         "tax", "lawsuit", "commission vote"] + obit_terms,
        "local_gov":    ["concert", "festival", "game recap", "score", "wins over", "defeats",
                         "arrest", "shooting", "homicide", "murder",
                         "governor debate", "gop debate", "primary debate", "gubernatorial",
                         "for governor", "for senate", "for congress", "governor's race",
                         "governor race", "senate race", "reelection campaign", "gop primary",
                         "democratic primary", "primary challenger", "skips debate",
                         "campaign trail", "poll shows", "leads in poll", "debate stage",
                         "presidential", "white house", "congress passes", "u.s. house",
                         "u.s. senate", "byron donalds", "desantis"] + obit_terms,
        "florida":      ["game recap", "score", "wins over", "defeats", "beats",
                         "world cup", "soccer", "nfl", "nba", "super bowl"] + obit_terms,
        "martin":       [],
        "st_lucie":     [],
        "indian_river": [],
    }

    if category_key in COUNTY_KEYS:
        return _county_locality_evidence(category_key, h)

    if category_key in topic_terms:
        if _has_any_bounded_term(text, hard_negatives.get(category_key, [])):
            return False
        if category_key == "sports" and not _sports_relevance_evidence(h):
            return False
        # Block national / global syndicated filler that has no local hook. WPTV and
        # other feeds carry survey/study/ranking pieces ("Study finds Gen X most
        # trusted...") that match a category on a loose word (e.g. "vote of
        # confidence" hitting local_gov's "vote"). These have international or
        # nationwide scope and no Treasure Coast connection. For non-Florida topic
        # categories, block a story that shows clear national/global scope AND names
        # no local place.
        if category_key != "florida":
            _tc_anchor = [
                "martin county", "st. lucie", "st lucie", "indian river", "treasure coast",
                "stuart", "jensen beach", "palm city", "hobe sound", "port salerno",
                "port st. lucie", "port st lucie", "fort pierce", "vero beach", "sebastian",
                "fellsmere", "indiantown", "jupiter island", "hutchinson island",
                "florida",
            ]
            _national_scope = [
                "across 15 countries", "countries", "nationwide", "across america",
                "american drivers", "americans", "global study", "worldwide", "u.k.",
                "united states", "across the country", "national survey", "study finds",
                "survey found", "survey finds", "study found", "ranking of states",
                "50 states", "study reveals", "researchers found", "new study",
            ]
            if _has_any(text, _national_scope) and not _has_any(text, _tc_anchor):
                return False
        # Keep statewide / out-of-area news OUT of local topic categories (it belongs
        # only in Florida). Rather than requiring a local place name in every story
        # (which wrongly drops local stories whose generated body doesn't repeat the
        # town), we only BLOCK stories that came from a statewide feed or clearly
        # reference an out-of-area place with no Treasure Coast connection.
        if category_key != "florida":
            feed_url = (h.get("feed_url", "") or "").lower()
            _tc_places = [
                "martin county", "st. lucie", "st lucie", "indian river", "treasure coast",
                "stuart", "jensen beach", "palm city", "hobe sound", "port salerno",
                "port st. lucie", "port st lucie", "fort pierce", "vero beach", "sebastian",
                "fellsmere", "indiantown", "jupiter island", "hutchinson island",
            ]
            if "state.rss" in feed_url or "floridapolitics" in feed_url:
                # From a statewide feed — only allow if it explicitly names a local place
                if not _has_any(text, _tc_places):
                    return False
            # Hyperlocal topic sections require a Treasure Coast anchor. This blocks
            # national MLB/World Cup/political stories even when the classifier tags
            # them as sports or business.
            if not _has_any(text, _tc_places):
                return False
        if _contract_assessment.get("mode") == "enforce":
            return bool(_contract_assessment.get("eligible"))
        if _classified_cats is not None:
            return category_key in _classified_cats
        return _has_any(title, topic_terms[category_key]) or _has_any(text, topic_terms[category_key])

    if _classified_cats is not None:
        return category_key in _classified_cats
    return True


def _category_score(category_key, h):
    text = _text_for_category_match(h)
    title = (h.get("title", "") or "").lower()
    score = 0

    local_places = [
        "treasure coast", "martin county", "st. lucie", "st lucie", "indian river",
        "stuart", "jensen beach", "palm city", "hobe sound", "port salerno",
        "port st. lucie", "port st lucie", "fort pierce", "vero beach",
        "sebastian", "fellsmere", "okeechobee", "jupiter island"
    ]

    county_terms = {
        "martin": ["martin county", "stuart", "jensen beach", "palm city", "hobe sound", "port salerno", "jupiter island"],
        "st_lucie": ["st. lucie", "st lucie", "port st. lucie", "port st lucie", "fort pierce", "st. lucie west", "st lucie west"],
        "indian_river": ["indian river", "vero beach", "sebastian", "fellsmere"],
    }

    positive_terms = {
        "local_gov": [
            "commission", "commissioner", "city council", "county council", "school board",
            "zoning", "rezoning", "ordinance", "budget", "tax", "millage", "mayor",
            "councilman", "councilwoman", "public meeting", "vote", "approved", "approval",
            "proposal", "hearing", "development order", "planning", "public policy"
        ],
        "crime": [
            "arrest", "arrested", "charged", "charges", "sheriff", "police", "deputies",
            "deputy", "officer", "shooting", "stabbed", "stabbing", "homicide", "murder",
            "crash", "fatal", "killed", "injured", "fire rescue", "missing", "suspect",
            "victim", "jail", "court", "public safety", "fraud", "burglary", "robbery"
        ],
        "business": [
            "business", "development", "developer", "real estate", "housing", "restaurant",
            "store", "retail", "mall", "company", "jobs", "hiring", "economic", "economy",
            "construction", "project", "commercial", "warehouse", "factory", "plant",
            "opening", "closing", "closes", "expansion", "wawa", "publix", "downtown",
            "permit", "approved", "zoning", "property", "market"
        ],
                "sports": [
            "sports", "football", "basketball", "baseball", "softball", "soccer", "volleyball",
            "tennis", "golf", "lacrosse", "wrestling", "track", "cross country", "swimming",
            "game", "score", "win", "wins", "won", "loss", "defeats", "beats", "championship",
            "playoff", "tournament", "athlete", "coach", "team", "mets", "st. lucie mets", "st lucie mets"
        ],
        "things_to_do": [
            "event", "events", "festival", "concert", "show", "weekend", "things to do",
            "restaurant", "food", "arts", "art", "music", "theater", "theatre", "park",
            "beach", "market", "farmers market", "fair", "fundraiser", "community", "parade",
            "holiday", "museum", "exhibit", "taste", "family-friendly", "activities"
        ],
        "florida": [
            "florida", "state", "desantis", "legislature", "tallahassee", "supreme court",
            "insurance", "hurricane", "weather", "statewide", "lawmakers", "law", "governor",
            "environment", "economy", "housing", "property insurance"
        ],
    }

    negative_terms = {
        "business": ["shooting", "arrest", "charged", "homicide", "murder", "missing", "crash", "fatal"],
        "sports": ["arrest", "charged", "shooting", "homicide", "murder", "missing", "crash", "politics", "commission", "sues", "lawsuit", "campbell soup", "spaghettios", "worms", "walmart", "fertilizer", "ban"],
        "things_to_do": ["arrest", "charged", "shooting", "homicide", "murder", "fatal crash", "tax", "budget"],
        "local_gov": ["concert", "festival", "restaurant review", "game recap"],
    }

    if category_key in county_terms:
        feed_url = (h.get("feed_url", "") or "").lower()
        county_feed_hints = {
            "martin": "region-martin-county",
            "st_lucie": "region-st-lucie-county",
            "indian_river": "region-indian-river-county",
        }
        title_l = (h.get("title", "") or "").lower()

        # Count mentions of the target county vs other counties
        def _county_mentions(terms):
            return sum(text.count(t) for t in terms)

        target_mentions = _county_mentions(county_terms[category_key])
        other_counties  = {k: v for k, v in county_terms.items() if k != category_key}
        other_mentions  = {k: _county_mentions(v) for k, v in other_counties.items()}
        max_other       = max(other_mentions.values()) if other_mentions else 0
        max_other_key   = max(other_mentions, key=other_mentions.get) if other_mentions else None

        in_target_feed = county_feed_hints.get(category_key, "") in feed_url
        in_other_feed  = any(county_feed_hints.get(k, "___") in feed_url for k in other_counties)

        # HARD BLOCK: if the story is primarily about another county
        # (another county appears in the title, or is mentioned more than the
        # target county, or came from another county's dedicated WPTV feed),
        # it does not belong in this county section.
        target_in_title = _has_any(title_l, county_terms[category_key])
        other_in_title  = any(_has_any(title_l, other_counties[k]) for k in other_counties)

        if other_in_title and not target_in_title:
            return -10  # Clearly about another county
        if in_other_feed and not in_target_feed:
            return -10  # WPTV filed it under another county
        if max_other > target_mentions and target_mentions == 0:
            return -10  # Only mentions other counties, never the target

        # Positive signals for the target county
        if in_target_feed:
            score += 9
        if target_in_title:
            score += 6
        elif target_mentions > 0:
            score += 4
        # Penalize competing county mentions even if target is present
        if max_other > target_mentions:
            score -= 4

        if h.get("source_quality") == "full":
            score += 2
        elif h.get("source_quality") in {"summary", "brief"}:
            score += 1
        return score

    terms = positive_terms.get(category_key, [])
    if terms:
        for term in terms:
            if term in title:
                score += 3
            elif term in text:
                score += 1

    if category_key != "florida" and _has_any(text, local_places):
        score += 2

    if h.get("source_quality") == "full":
        score += 2

    for term in negative_terms.get(category_key, []):
        if term in text:
            score -= 3

    return score


def filter_category_headlines(category_key, headlines, target=HEADLINES_PER_CATEGORY, min_keep=6):
    """Return the best on-topic headlines for a section without blanking weak sections.

    Broad WPTV feeds are useful because they provide full bodies, but they can put crime,
    schools, business, and county stories in the same pool. Topic beats now require an
    explicit classification; local topic beats also require deterministic Treasure Coast
    locality. County pages retain their separate geographic/source-authority fallback.
    """
    if not headlines:
        return headlines

    scored = []
    _unclassified_rejections = 0
    _locality_rejections = 0
    for h in headlines:
        # Local topic beats are Treasure Coast sections, not South Florida sections.
        # Locality is deterministic and cannot be bypassed by a classifier label.
        if category_key in LOCAL_TOPIC_CATEGORY_KEYS and not _has_treasure_coast_locality(h):
            _locality_rejections += 1
            continue

        _contract = _category_eligibility_contract_assessment(category_key, h)
        h["_category_eligibility_contract"] = _compact_category_contract_assessment(_contract, h)
        if _contract.get("mode") == "enforce" and not _contract.get("eligible"):
            continue
        # Classification-first: every topic-category source must have an explicit
        # classification. An absent mapping is no longer permission to use broad
        # keywords; it is a fail-safe rejection to archive recovery. County pages
        # retain their independent source-authority fallback.
        if STORY_CLASSIFICATION is not None:
            _cats = STORY_CLASSIFICATION.get((h.get("title", "") or "").lower())
            if _cats is None and category_key in TOPIC_CATEGORY_KEYS:
                _unclassified_rejections += 1
                continue
            if _cats is not None:
                if "none" in _cats and len(_cats) == 1:
                    continue  # non-local content, drop from every category
                if category_key in _cats:
                    score = 10  # classified for this category
                else:
                    continue  # classified, but for other categories — skip here
                h["category_match_score"] = score
                h["hero_eligible"] = "yes" if _hero_eligible(category_key, h) else "no"
                scored.append((score, h))
                continue
        score = _category_score(category_key, h)
        h["category_match_score"] = score
        h["hero_eligible"] = "yes" if _hero_eligible(category_key, h) else "no"
        scored.append((score, h))

    if _locality_rejections or _unclassified_rejections:
        print(
            f"  Category routing gate: rejected {_locality_rejections} outside-Treasure-Coast "
            f"and {_unclassified_rejections} unclassified {CATEGORIES[category_key]['label']} source(s)"
        )

    # For broad/local categories, require only a weak positive score. The goal is
    # to remove obvious mismatches, not starve the section.
    threshold = 1
    if category_key in {"business", "sports", "things_to_do", "local_gov", "crime"}:
        threshold = 2
    if category_key in {"martin", "st_lucie", "indian_river"}:
        threshold = 2  # Cross-county hard-blocks already prevent bleed; keep this low so counties aren't starved

    filtered = [h for score, h in scored if score >= threshold]
    hero_ready = [h for _, h in scored if h.get("hero_eligible") == "yes"]

    if len(filtered) < min_keep:
        if hero_ready:
            filler = [h for score, h in sorted(scored, key=lambda x: x[0], reverse=True) if h not in hero_ready]
            combined = hero_ready + filler
            print(f"  Category filter: only {len(filtered)} strong matches; preserving {len(hero_ready)} hero-eligible items and filling cards")
            return combined[:target]
        print(f"  Category filter: only {len(filtered)} strong matches and no hero-eligible items; using best scored pool")
        return [h for score, h in sorted(scored, key=lambda x: x[0], reverse=True)][:target]

    filtered.sort(key=lambda h: (h.get("hero_eligible") == "yes", h.get("category_match_score", 0), h.get("source_quality") == "full"), reverse=True)
    print(f"  Category filter: {len(filtered)} on-topic matches from {len(headlines)}; {len(hero_ready)} hero-eligible")
    return filtered[:target]

