class ContextualUpdateLeadError(RuntimeError):
    """Raised when an update hero omits the original event or the new development."""


def _source_story_form(source):
    """Classify update copy from authoritative story routing or explicit title cues."""
    if not isinstance(source, dict):
        return "standard"
    explicit = str(source.get("story_form") or "").strip().lower()
    if explicit in {"update", "standard"}:
        return explicit
    route = str(
        source.get("_editorial_route") or source.get("editorial_route") or ""
    ).strip().lower()
    if route in {"update_existing", "replace_canonical", "publish_major_update"}:
        return "update"
    title = str(source.get("source_title") or source.get("title") or source.get("headline") or "")
    if any(pattern.search(title) for pattern in _UPDATE_SOURCE_PATTERNS):
        return "update"
    return "standard"


def _first_body_paragraph(text):
    value = str(text or "").strip()
    if not value:
        return ""
    paragraphs = [part.strip() for part in re.split(r"\n\s*\n", value) if part.strip()]
    return paragraphs[0] if paragraphs else value


def _first_matching_anchor(text, anchor_groups):
    value = str(text or "")
    for name, pattern in anchor_groups:
        if pattern.search(value):
            return name, pattern
    return "", None


_UPDATE_CONTEXT_STOP_WORDS = {
    "about", "after", "again", "against", "before", "being", "between",
    "child", "children", "county", "details", "during", "from", "have",
    "into", "latest", "local", "more", "news", "officials", "over",
    "says", "said", "story", "their", "there", "these", "they", "this",
    "through", "under", "where", "with", "would",
}


def _update_context_tokens(text):
    return {
        token
        for token in re.findall(r"[a-z0-9]+", str(text or "").lower())
        if len(token) >= 4 and token not in _UPDATE_CONTEXT_STOP_WORDS
    }


def _update_lead_diagnostics(item, source=None):
    """Return a deterministic pass/fail assessment for a story update lead.

    Update status comes from the publication/story decision, not merely from words
    such as ``update`` or ``new details`` in a headline. When a canonical TCT page
    already exists, its headline and article context define the original event. The
    incoming source defines the new development. A replacement lead must explain both
    to a first-time reader before the canonical page may be changed.
    """
    source = source if isinstance(source, dict) else item
    story_form = str(item.get("story_form") or _source_story_form(source))
    if story_form != "update":
        return {"required": False, "passed": True, "story_form": story_form}

    lead = _first_body_paragraph(item.get("body", ""))
    lead_word_count = len(re.findall(r"\b\w+\b", lead))
    source_title = str(
        source.get("source_title")
        or source.get("title")
        or source.get("headline")
        or ""
    )
    current_source_text = " ".join([
        source_title,
        str(
            source.get("article_text")
            or source.get("source_summary")
            or source.get("summary")
            or source.get("body")
            or ""
        )[:2400],
        " ".join(str(value) for value in (source.get("_editorial_new_facts") or [])),
    ])

    canonical_headline = str(
        source.get("_canonical_context_headline")
        or item.get("_canonical_context_headline")
        or ""
    ).strip()
    canonical_body = str(
        source.get("_canonical_context_body")
        or item.get("_canonical_context_body")
        or ""
    ).strip()
    canonical_context_available = bool(canonical_headline or canonical_body)
    baseline_text = " ".join(filter(None, [
        canonical_headline,
        canonical_body,
        current_source_text if not canonical_context_available else "",
    ]))

    baseline_name, baseline_pattern = _first_matching_anchor(
        baseline_text, _UPDATE_BASELINE_ANCHORS
    )
    baseline_anchor_present = bool(
        not baseline_pattern or baseline_pattern.search(lead)
    )

    canonical_tokens = _update_context_tokens(canonical_headline)
    lead_tokens = _update_context_tokens(lead)
    baseline_context_hits = sorted(canonical_tokens & lead_tokens)
    baseline_context_required = min(2, len(canonical_tokens)) if canonical_tokens else 0
    baseline_details_present = bool(
        not baseline_context_required
        or len(baseline_context_hits) >= baseline_context_required
    )
    baseline_present = baseline_anchor_present and baseline_details_present

    novelty_name, novelty_pattern = _first_matching_anchor(
        source_title, _UPDATE_NOVELTY_ANCHORS
    )
    novelty_tokens = sorted(
        _update_context_tokens(source_title) - _update_context_tokens(canonical_headline)
    )
    novelty_token_hits = sorted(set(novelty_tokens) & lead_tokens)
    if novelty_pattern is not None:
        novelty_present = bool(novelty_pattern.search(lead))
    elif canonical_context_available and novelty_tokens:
        novelty_name = "source_distinctive_detail"
        novelty_present = bool(novelty_token_hits)
    else:
        novelty_present = True

    length_present = lead_word_count >= 18
    passed = bool(lead) and baseline_present and novelty_present and length_present

    missing = []
    if not lead:
        missing.append("lead_missing")
    if not baseline_anchor_present:
        missing.append("original_event_context_missing")
    if baseline_anchor_present and not baseline_details_present:
        missing.append("original_event_details_missing")
    if not novelty_present:
        missing.append("new_development_missing")
    if lead and not length_present:
        missing.append("lead_too_short_for_context")

    return {
        "required": True,
        "passed": passed,
        "story_form": story_form,
        "lead_word_count": lead_word_count,
        "baseline_anchor": baseline_name,
        "baseline_present": baseline_present,
        "baseline_anchor_present": baseline_anchor_present,
        "baseline_details_present": baseline_details_present,
        "baseline_context_hits": baseline_context_hits,
        "baseline_context_required": baseline_context_required,
        "canonical_context_available": canonical_context_available,
        "canonical_context_headline": canonical_headline,
        "novelty_anchor": novelty_name,
        "novelty_present": novelty_present,
        "novelty_token_hits": novelty_token_hits,
        "missing": missing,
        "source_title": source_title,
        "headline": str(item.get("headline") or ""),
    }


def _archive_entry_has_contextless_update_lead(entry):
    if not isinstance(entry, dict) or entry.get("is_custom") or entry.get("authoritative_custom"):
        return False
    story_form = _source_story_form({
        "title": entry.get("source_title") or entry.get("headline"),
    })
    if story_form != "update":
        return False
    probe = dict(entry)
    probe["story_form"] = story_form
    probe["body"] = (
        entry.get("body")
        or entry.get("article_text")
        or _archive_article_body(entry)
        or entry.get("teaser")
        or ""
    )
    return not _update_lead_diagnostics(probe, probe).get("passed", True)


def _archive_entry_has_article_framing_failure(entry):
    if not isinstance(entry, dict) or entry.get("is_custom") or entry.get("authoritative_custom"):
        return False
    probe = dict(entry)
    probe["body"] = (
        entry.get("body")
        or entry.get("article_text")
        or _archive_article_body(entry)
        or entry.get("teaser")
        or ""
    )
    return not _article_framing_diagnostics(probe, probe).get("passed", True)


class ArticleFramingIntegrityError(RuntimeError):
    """Raised when a generated article relies on its headline or changes its core claim."""


_FRAMING_STOP_WORDS = {
    "a", "an", "and", "are", "as", "at", "be", "been", "being", "by", "for",
    "from", "has", "have", "in", "into", "is", "it", "its", "of", "on", "or",
    "that", "the", "their", "this", "to", "was", "were", "will", "with",
}

# These are deliberately local and specific. County/city identity is a primary claim
# for a hyperlocal publication, not a cosmetic keyword. Longest patterns appear first
# so "Port St. Lucie" never collapses into the broader "St. Lucie" token family.
_LOCAL_JURISDICTION_PATTERNS = (
    ("port_st_lucie", re.compile(r"\bport\s+st\.?\s+lucie\b", re.I)),
    ("st_lucie_county", re.compile(r"\bst\.?\s+lucie\s+county\b", re.I)),
    ("indian_river_county", re.compile(r"\bindian\s+river\s+county\b", re.I)),
    ("martin_county", re.compile(r"\bmartin\s+county\b", re.I)),
    ("fort_pierce", re.compile(r"\bfort\s+pierce\b", re.I)),
    ("vero_beach", re.compile(r"\bvero\s+beach\b", re.I)),
    ("jensen_beach", re.compile(r"\bjensen\s+beach\b", re.I)),
    ("hobe_sound", re.compile(r"\bhobe\s+sound\b", re.I)),
    ("palm_city", re.compile(r"\bpalm\s+city\b", re.I)),
    ("port_salerno", re.compile(r"\bport\s+salerno\b", re.I)),
    ("jupiter_island", re.compile(r"\bjupiter\s+island\b", re.I)),
    ("indian_town", re.compile(r"\bindiantown\b", re.I)),
    ("fellsmere", re.compile(r"\bfellsmere\b", re.I)),
    ("sebastian", re.compile(r"\bsebastian\b", re.I)),
    ("stuart", re.compile(r"\bstuart\b", re.I)),
)

_OPAQUE_POLICY_REFERENCE_PATTERNS = (
    re.compile(
        r"\b(?:amendment|measure|proposition|resolution|ordinance|referendum)\s+"
        r"(?:no\.?\s*)?(?:\d+[a-z0-9-]*|[a-z])\b",
        re.I,
    ),
    re.compile(r"\b(?:house|senate)\s+bill\s+\d+[a-z-]*\b", re.I),
    re.compile(r"\b(?:hb|sb)\s*\d+[a-z-]*\b", re.I),
)

_DEFINITION_SIGNAL_PATTERN = re.compile(
    r"\b(?:which|that|would|will|seeks?|proposes?|raises?|increases?|expands?|"
    r"reduces?|eliminates?|changes?|requires?|authorizes?|creates?|funds?|cuts?|"
    r"allows?|bans?|prohibits?|exempts?|extends?|replaces?)\b",
    re.I,
)

# A named resolution/bill/amendment is intelligible when the lead states its actual
# effect, even if newsroom shorthand in the headline (for example ``trash fee``) is
# expressed with the formal term in the body (``solid waste assessment``).  Keep this
# separate from generic procedural verbs such as ``approved``/``passed``: merely saying
# that Resolution 26-R70 passed does not tell a first-time reader what it does.
_POLICY_EFFECT_ACTION_PATTERN = re.compile(
    r"\b(?:rais(?:e|es|ed|ing)|increas(?:e|es|ed|ing)|lower(?:s|ed|ing)?|"
    r"reduc(?:e|es|ed|ing)|cut(?:s|ting)?|set(?:s|ting)?|chang(?:e|es|ed|ing)|"
    r"requir(?:e|es|ed|ing)|authoriz(?:e|es|ed|ing)|creat(?:e|es|ed|ing)|"
    r"fund(?:s|ed|ing)?|allow(?:s|ed|ing)?|ban(?:s|ned|ning)?|prohibit(?:s|ed|ing)?|"
    r"exempt(?:s|ed|ing)?|extend(?:s|ed|ing)?|replac(?:e|es|ed|ing)|expand(?:s|ed|ing)?|"
    r"eliminat(?:e|es|ed|ing)|impos(?:e|es|ed|ing)|levy|levies|levied|levying|"
    r"restor(?:e|es|ed|ing)|remov(?:e|es|ed|ing))\b",
    re.I,
)


def _meaningful_framing_tokens(text):
    return {
        token
        for token in re.findall(r"[a-z0-9]+", str(text or "").casefold())
        if len(token) > 1 and token not in _FRAMING_STOP_WORDS
    }


def _extract_money_claims(text):
    """Return normalized monetary magnitudes stated in prose or a URL slug.

    Normalize both compact newsroom forms (``$22K``, ``48 million``) and ordinary
    dollar literals (``$22,000``). Headline/lead integrity compares magnitudes, not
    typography, so equivalent forms must resolve to the same integer value.
    """
    normalized = re.sub(r"[-_]", " ", str(text or "").lower())
    claims = set()
    magnitude_pattern = re.compile(
        r"(?<![a-z0-9])\$?\s*(\d+(?:\.\d+)?)\s*"
        r"(billion|million|thousand|[bmk])\b(?:\s+dollars?)?",
        re.I,
    )
    multipliers = {
        "billion": 1_000_000_000,
        "b": 1_000_000_000,
        "million": 1_000_000,
        "m": 1_000_000,
        "thousand": 1_000,
        "k": 1_000,
    }
    for match in magnitude_pattern.finditer(normalized):
        try:
            value = float(match.group(1)) * multipliers[match.group(2).lower()]
        except (TypeError, ValueError, KeyError):
            continue
        claims.add(int(round(value)))

    dollar_literal_pattern = re.compile(
        r"(?<![a-z0-9])\$\s*(\d[\d,]*(?:\.\d+)?)",
        re.I,
    )
    for match in dollar_literal_pattern.finditer(normalized):
        # Compact magnitude forms such as $22K are handled above. Skip them here
        # after consuming the complete numeric token so regex backtracking cannot
        # misread $22K as the plain-dollar value $2.
        suffix = normalized[match.end():]
        if re.match(r"\s*(?:billion|million|thousand|[bmk])\b", suffix, re.I):
            continue
        try:
            value = float(match.group(1).replace(",", ""))
        except (TypeError, ValueError):
            continue
        claims.add(int(round(value)))
    return claims


def _extract_jurisdiction_claims(text):
    value = re.sub(r"[-_]", " ", str(text or ""))
    return {
        canonical
        for canonical, pattern in _LOCAL_JURISDICTION_PATTERNS
        if pattern.search(value)
    }


# City/county containment is a geographic equivalence for headline/lead integrity,
# but sibling cities are not interchangeable. A headline that says Port St. Lucie
# is adequately grounded by a lead that says St. Lucie County; a headline that says
# Port St. Lucie is NOT grounded by a lead that says Fort Pierce.
_JURISDICTION_PARENT_COUNTY = {
    "port_st_lucie": "st_lucie_county",
    "fort_pierce": "st_lucie_county",
    "stuart": "martin_county",
    "jensen_beach": "martin_county",
    "hobe_sound": "martin_county",
    "palm_city": "martin_county",
    "port_salerno": "martin_county",
    "indian_town": "martin_county",
    "vero_beach": "indian_river_county",
    "sebastian": "indian_river_county",
    "fellsmere": "indian_river_county",
}


def _jurisdiction_claim_covered(claim, lead_claims):
    if claim in lead_claims:
        return True
    parent = _JURISDICTION_PARENT_COUNTY.get(claim)
    if parent and parent in lead_claims:
        return True
    # A county headline may be grounded by a specific city inside that county.
    if claim in {"st_lucie_county", "martin_county", "indian_river_county"}:
        return any(
            _JURISDICTION_PARENT_COUNTY.get(lead_claim) == claim
            for lead_claim in lead_claims
        )
    return False


def _missing_headline_jurisdiction_claims(headline_claims, lead_claims):
    return sorted(
        claim for claim in headline_claims
        if not _jurisdiction_claim_covered(claim, lead_claims)
    )


def _extract_opaque_policy_references(text):
    value = re.sub(r"\s+", " ", str(text or "")).strip()
    references = []
    seen = set()
    for pattern in _OPAQUE_POLICY_REFERENCE_PATTERNS:
        for match in pattern.finditer(value):
            normalized = re.sub(r"\s+", " ", match.group(0).casefold()).strip()
            if normalized in seen:
                continue
            seen.add(normalized)
            references.append({"text": match.group(0), "normalized": normalized})
    return references


def _lead_defines_policy_reference(lead, reference):
    """Return True when the opening paragraph actually explains a named measure.

    This is intentionally semantic at the clause level rather than a vocabulary
    equivalence test.  Formal government language and newsroom shorthand often use
    different nouns (``solid waste assessment`` vs. ``trash fee``), but the lead is
    self-contained when the sentence naming the resolution/bill/amendment states the
    concrete effect of that measure.
    """
    lead_text = re.sub(r"\s+", " ", str(lead or "")).strip()
    reference_text = str((reference or {}).get("text") or "").strip()
    if not lead_text or not reference_text:
        return False
    matches = list(re.finditer(re.escape(reference_text), lead_text, re.I))
    if not matches:
        return False

    reference_tokens = _meaningful_framing_tokens(reference_text)
    procedural_only = {
        "amendment", "measure", "proposition", "resolution", "ordinance",
        "referendum", "house", "senate", "bill", "council", "commission",
        "board", "city", "county", "meeting", "monday", "tuesday", "wednesday",
        "thursday", "friday", "saturday", "sunday", "approved", "passed",
        "adopted", "vote", "voted", "votes",
    }

    # Work sentence-by-sentence so an unrelated later policy effect cannot define a
    # bare reference in the opening sentence by accident.
    sentence_spans = list(re.finditer(r"[^.!?]+(?:[.!?]|$)", lead_text))
    for match in matches:
        sentence = next(
            (
                span.group(0).strip()
                for span in sentence_spans
                if span.start() <= match.start() < span.end()
            ),
            lead_text,
        )

        # Classic appositive definition: "Amendment 3, a proposed constitutional
        # amendment that would raise ...".
        if re.search(
            re.escape(reference_text)
            + r"\s*,\s*(?:a|an|the)\b.{3,180}\b(?:that|which|would|will)\b",
            sentence,
            re.I,
        ):
            return True

        # Direct effect definition: "Resolution 26-R70, raising the annual solid
        # waste assessment by $14.83 ..." or "HB 123 requires insurers to ...".
        effect = _POLICY_EFFECT_ACTION_PATTERN.search(sentence)
        if effect:
            remainder = sentence[effect.end():]
            substantive_tokens = (
                _meaningful_framing_tokens(remainder)
                - reference_tokens
                - procedural_only
            )
            # Require enough object/impact detail to distinguish a real definition
            # from procedural copy such as "Resolution 26-R70 passed Monday." Money,
            # percentages and dates are useful supporting detail but never required.
            if len(substantive_tokens) >= 2:
                return True

    return False


def _lead_independence_diagnostics(item, source=None):
    """Assess whether the opening paragraph stands alone without the headline."""
    item = item if isinstance(item, dict) else {}
    source = source if isinstance(source, dict) else item
    if item.get("is_custom") or item.get("authoritative_custom"):
        return {"required": False, "passed": True, "custom_exempt": True, "missing": []}

    headline = str(item.get("headline") or item.get("title") or "").strip()
    lead = _first_body_paragraph(item.get("body") or item.get("article_text") or item.get("teaser") or "")
    missing = []
    if not lead:
        missing.append("lead_missing")

    headline_tokens = _meaningful_framing_tokens(headline)
    lead_tokens = _meaningful_framing_tokens(lead)
    overlap_ratio = (
        len(headline_tokens & lead_tokens) / len(headline_tokens)
        if headline_tokens else 0.0
    )
    new_context_tokens = lead_tokens - headline_tokens
    lead_word_count = len(re.findall(r"\b\w+\b", lead))
    if (
        lead
        and len(headline_tokens) >= 5
        and overlap_ratio >= 0.85
        and len(new_context_tokens) <= 3
        and lead_word_count <= max(22, len(headline_tokens) + 6)
    ):
        missing.append("headline_restatement_without_context")

    reference_blob = " ".join([
        headline,
        str(source.get("source_title") or source.get("title") or ""),
        lead,
    ])
    references = _extract_opaque_policy_references(reference_blob)
    undefined = [
        ref["text"]
        for ref in references
        if not _lead_defines_policy_reference(lead, ref)
    ]
    if undefined:
        missing.append("named_measure_undefined_in_lead")

    update_diag = _update_lead_diagnostics(item, source)
    if update_diag.get("required") and not update_diag.get("passed"):
        missing.extend(update_diag.get("missing") or [])

    missing = list(dict.fromkeys(missing))
    return {
        "required": True,
        "passed": not missing,
        "headline": headline,
        "lead": lead,
        "lead_word_count": lead_word_count,
        "headline_overlap_ratio": round(overlap_ratio, 3),
        "new_context_token_count": len(new_context_tokens),
        "opaque_references": [ref["text"] for ref in references],
        "undefined_references": undefined,
        "story_form": update_diag.get("story_form", _source_story_form(source)),
        "update_diagnostics": update_diag,
        "missing": missing,
    }


def _headline_lead_claim_diagnostics(item):
    """Verify that headline amounts and jurisdictions are actually stated in the lead."""
    item = item if isinstance(item, dict) else {}
    if item.get("is_custom") or item.get("authoritative_custom"):
        return {"required": False, "passed": True, "custom_exempt": True, "missing": []}

    headline = str(item.get("headline") or item.get("title") or "").strip()
    lead = _first_body_paragraph(item.get("body") or item.get("article_text") or item.get("teaser") or "")
    headline_money = _extract_money_claims(headline)
    lead_money = _extract_money_claims(lead)
    headline_jurisdictions = _extract_jurisdiction_claims(headline)
    lead_jurisdictions = _extract_jurisdiction_claims(lead)
    headline_references = {
        ref["normalized"] for ref in _extract_opaque_policy_references(headline)
    }
    lead_references = {
        ref["normalized"] for ref in _extract_opaque_policy_references(lead)
    }

    missing = []
    missing_money = sorted(headline_money - lead_money)
    if missing_money:
        missing.append("headline_money_claim_missing_from_lead")
    missing_jurisdictions = _missing_headline_jurisdiction_claims(
        headline_jurisdictions, lead_jurisdictions
    )
    if missing_jurisdictions:
        missing.append("headline_jurisdiction_missing_from_lead")
    missing_references = sorted(headline_references - lead_references)
    if missing_references:
        missing.append("headline_named_measure_missing_from_lead")

    return {
        "required": True,
        "passed": not missing,
        "headline": headline,
        "lead": lead,
        "headline_money_claims": sorted(headline_money),
        "lead_money_claims": sorted(lead_money),
        "missing_money_claims": missing_money,
        "headline_jurisdictions": sorted(headline_jurisdictions),
        "lead_jurisdictions": sorted(lead_jurisdictions),
        "missing_jurisdictions": missing_jurisdictions,
        "headline_policy_references": sorted(headline_references),
        "lead_policy_references": sorted(lead_references),
        "missing_policy_references": missing_references,
        "missing": missing,
    }


def _source_focus_diagnostics(item, source=None):
    """Fail closed when generated copy abandons the publisher story's main focus."""
    item = item if isinstance(item, dict) else {}
    source = source if isinstance(source, dict) else item
    if item.get("is_custom") or item.get("authoritative_custom"):
        return {"required": False, "passed": True, "custom_exempt": True, "missing": []}

    generated_headline = str(item.get("headline") or item.get("title") or "").strip()
    generated_lead = _first_body_paragraph(
        item.get("body") or item.get("teaser") or ""
    )
    source_title = str(
        source.get("source_title")
        or source.get("source_headline")
        or source.get("title")
        or ""
    ).strip()
    source_text = str(
        source.get("article_text")
        or source.get("source_text")
        or source.get("summary")
        or ""
    ).strip()

    def opening_focus_text(value, *, max_sentences=2, max_words=80):
        normalized = re.sub(r"\s+", " ", str(value or "")).strip()
        if not normalized:
            return ""
        sentences = [
            part.strip()
            for part in re.split(r"(?<=[.!?])\s+(?=[A-Z0-9])", normalized)
            if part.strip()
        ]
        focused = " ".join(sentences[:max_sentences]) if sentences else normalized
        words = focused.split()
        return " ".join(words[:max_words])

    source_lead = opening_focus_text(source_text)
    generated_focus_lead = opening_focus_text(generated_lead)
    source_title_tokens = _meaningful_framing_tokens(source_title)
    source_lead_tokens = _meaningful_framing_tokens(source_lead)
    generated_lead_tokens = _meaningful_framing_tokens(generated_focus_lead)

    # Short alerts, opaque wire labels, and missing source text do not provide enough
    # independent evidence for this guard. Other framing and identity contracts still
    # apply to those items.
    required = bool(
        generated_headline
        and generated_lead
        and len(source_title_tokens) >= 5
        and len(source_lead_tokens) >= 8
        and len(re.findall(r"\b\w+\b", source_text)) >= 35
    )
    if not required:
        return {
            "required": False,
            "passed": True,
            "source_title": source_title,
            "source_lead": source_lead,
            "missing": [],
        }

    if semantic_headline_similarity is not None:
        title_similarity = semantic_headline_similarity(
            generated_headline, source_title
        )
    else:
        generated_title_tokens = _meaningful_framing_tokens(generated_headline)
        shared = generated_title_tokens & source_title_tokens
        denominator = min(len(generated_title_tokens), len(source_title_tokens))
        score = len(shared) / denominator if denominator else 0.0
        title_similarity = {
            "score": round(score, 4),
            "shared_token_count": float(len(shared)),
        }

    lead_overlap = (
        len(generated_lead_tokens & source_lead_tokens)
        / min(len(generated_lead_tokens), len(source_lead_tokens))
        if generated_lead_tokens and source_lead_tokens
        else 0.0
    )
    drifted = bool(
        float(title_similarity.get("score") or 0.0) < 0.38
        and int(title_similarity.get("shared_token_count") or 0) <= 3
        and lead_overlap < 0.30
    )
    missing = ["generated_copy_drifted_from_source_focus"] if drifted else []
    return {
        "required": True,
        "passed": not drifted,
        "generated_headline": generated_headline,
        "generated_lead": generated_focus_lead,
        "source_title": source_title,
        "source_lead": source_lead,
        "title_similarity": title_similarity,
        "lead_token_overlap": round(lead_overlap, 3),
        "missing": missing,
    }



# v1.13.2.0: source-backed county jurisdiction authority now delegates to the
# shared county-membership contract so generation-time hero checks, archive repair,
# cache reuse, and final live projection cannot disagree.
# v1.13.1.6: source-backed county jurisdiction authority
def _source_only_jurisdiction_blob(source):
    return _source_county_authority_blob(source)


def _source_jurisdiction_diagnostics(item, source=None):
    item = item if isinstance(item, dict) else {}
    source = source if isinstance(source, dict) else item
    category_key = str(item.get("category_key") or source.get("category_key") or "")
    if category_key not in COUNTY_KEYS:
        return {"required": False, "passed": True, "missing": []}

    probe = dict(source)
    # Preserve the intended generated county as context only; it is never evidence.
    assessment = _county_membership_authority_assessment(probe, category_key)
    local_hits = list(
        assessment.get("supporting_evidence", {}).get(category_key, [])
    )
    outside_hits = []
    for conflict in assessment.get("conflicting_counties", []) or []:
        outside_hits.extend(conflict.get("evidence") or [])

    missing = []
    if category_key not in assessment.get("supported_counties", []):
        missing.append("generated_jurisdiction_not_supported_by_source")
        if outside_hits:
            missing.append("source_jurisdiction_conflicts_with_generated_county")

    return {
        "required": True,
        "passed": not missing,
        "category_key": category_key,
        "local_source_hits": local_hits,
        "outside_source_hits": outside_hits,
        "authority_assessment": assessment,
        "missing": missing,
    }


def _article_framing_diagnostics(item, source=None):
    """Combined universal lead-independence and headline/lead claim contract."""
    item = item if isinstance(item, dict) else {}
    # Missing/null heroes are contained by the category-generation failure path.
    # Do not misclassify absence as a prose-quality failure or bypass its existing
    # structured retry/recovery diagnostics.
    if not str(item.get("headline") or item.get("title") or "").strip() and not str(item.get("body") or "").strip():
        return {"required": False, "passed": True, "empty_item": True, "missing": []}
    if item.get("is_custom") or item.get("authoritative_custom"):
        return {"required": False, "passed": True, "custom_exempt": True, "missing": []}
    lead_diag = _lead_independence_diagnostics(item, source)
    claim_diag = _headline_lead_claim_diagnostics(item)
    source_focus_diag = _source_focus_diagnostics(item, source)
    source_jurisdiction_diag = _source_jurisdiction_diagnostics(item, source)
    missing = list(dict.fromkeys(
        list(lead_diag.get("missing") or [])
        + list(claim_diag.get("missing") or [])
        + list(source_focus_diag.get("missing") or [])
        + list(source_jurisdiction_diag.get("missing") or [])
    ))
    return {
        "required": True,
        "passed": not missing,
        "headline": str(item.get("headline") or item.get("title") or ""),
        "missing": missing,
        "lead_independence": lead_diag,
        "claim_consistency": claim_diag,
        "source_focus": source_focus_diag,
        "source_jurisdiction": source_jurisdiction_diag,
    }


def _filter_article_framing_live_placements(items):
    """Suppress generated articles that fail the universal framing contract."""
    kept = []
    rejected = []
    for item in list(items or []):
        if item.get("is_custom") or item.get("authoritative_custom"):
            kept.append(item)
            continue
        probe = dict(item)
        if probe.get("_archived_slug") and _word_count(probe.get("body", "")) < 45:
            archive_body = _archive_article_body({"slug": probe.get("_archived_slug")})
            if archive_body:
                probe["body"] = archive_body
        diagnostics = _article_framing_diagnostics(probe, probe)
        if diagnostics.get("passed"):
            kept.append(item)
            continue
        rejected.append({
            "headline": str(item.get("headline") or item.get("title") or ""),
            "source_title": str(item.get("source_title") or ""),
            "source_url": str(item.get("source_url") or item.get("link") or ""),
            "slug": str(item.get("_archived_slug") or item.get("slug") or ""),
            "reason": "article_framing_integrity",
            "missing": diagnostics.get("missing", []),
            "lead_independence": diagnostics.get("lead_independence", {}),
            "claim_consistency": diagnostics.get("claim_consistency", {}),
            "source_focus": diagnostics.get("source_focus", {}),
        })
    return kept, rejected

def strip_markdown(text, headline=""):
    """Remove markdown formatting and headline restatements from article text."""
    if not text:
        return text
    text = re.sub(r"#{1,6}\s*", "", text)
    text = re.sub(r"\*{1,2}([^*]+)\*{1,2}", r"\1", text)
    text = re.sub(r"_([^_]+)_", r"\1", text)
    text = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", text)
    text = re.sub(r"^[-*]\s+", "", text, flags=re.MULTILINE)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    # Remove common Guardian/newsletter openers
    greetings = ["good morning.", "good afternoon.", "good evening.", "good morning,", "good afternoon,", "good evening,"]
    lower = text.lower()
    for g in greetings:
        if lower.startswith(g):
            text = text[len(g):].lstrip()
            break

    # Remove first paragraph if it looks like a headline restatement
    if headline:
        paragraphs = text.split("\n\n")
        if paragraphs:
            first = paragraphs[0].strip()
            if len(first.split()) < 20:
                hl_words = set(re.sub(r"[^a-z0-9 ]", " ", headline.lower()).split())
                p_words  = set(re.sub(r"[^a-z0-9 ]", " ", first.lower()).split())
                if len(hl_words & p_words) >= min(4, len(hl_words) // 2):
                    text = "\n\n".join(paragraphs[1:]).strip()
    return text



def _category_story_source_url(item):
    """Return the external publisher URL used to distinguish a retouch from new reporting."""
    if not isinstance(item, dict):
        return ""
    for key in ("source_url", "latest_source_url", "_source_url", "original_url", "link"):
        raw = str(item.get(key) or "").strip()
        if not raw:
            continue
        normalized = _normalized_external_source_url(raw)
        if normalized:
            return normalized
    return ""


def _category_story_matching_source_receipt(item, archive):
    """Find an older archive receipt for the exact external publisher article URL."""
    source_url = _category_story_source_url(item)
    if not source_url:
        return None
    for row in archive or []:
        if not isinstance(row, dict):
            continue
        for key in ("source_url", "latest_source_url", "original_url"):
            candidate = _normalized_external_source_url(row.get(key))
            if candidate and candidate == source_url:
                return row
    return None


def _category_story_receipt_datetime(row):
    if not isinstance(row, dict):
        return None
    from email.utils import parsedate_to_datetime
    for key in ("first_published", "published_raw", "published", "date", "lastmod"):
        raw = row.get(key)
        if not raw:
            continue
        try:
            dt = parsedate_to_datetime(str(raw))
        except Exception:
            dt = None
        if dt is None:
            try:
                dt = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
            except Exception:
                try:
                    dt = datetime.strptime(str(raw)[:10], "%Y-%m-%d")
                except Exception:
                    continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    return None


def _category_story_has_validated_update_authority(item):
    if not isinstance(item, dict):
        return False
    route = str(item.get("_editorial_route") or item.get("editorial_route") or "").strip().lower()
    return bool(
        item.get("meaningful_update_validated")
        or item.get("_semantic_material_update")
        or item.get("_pre_generation_material_update_promotion")
        or route in {"update_existing", "replace_canonical", "publish_major_update"}
    )


def _category_story_is_stale(item, archive, published_raw="", now=None):
    """Shared live/shadow stale-story test based on publication evidence.

    A freshly published article is not stale merely because it reports an event that
    happened yesterday.  Previous-day words describe event time, not publication
    freshness.  A fresh feed timestamp is treated as a stale *retouch* only when the
    same external publisher URL already has an older archive receipt and no validated
    material-update authority exists.  This separates genuine next-day reporting from
    RSS timestamp churn without relying on brittle weekday vocabulary.
    """
    from email.utils import parsedate_to_datetime

    if not isinstance(item, dict):
        return False
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    content = (
        str(item.get("headline") or "") + " "
        + str(item.get("teaser") or "") + " "
        + str(item.get("body") or "")[:900]
    ).lower()

    fresh_override = (
        "today", "this morning", "this afternoon", "this evening", "hours ago",
        "minutes ago", "just announced", "just released", "breaking", "moments ago",
        "earlier today", "announced today", "arrested today", "ruled today",
        "confirmed today",
    )
    if any(phrase in content for phrase in fresh_override):
        return False
    if _category_story_has_validated_update_authority(item):
        return False

    published = None
    try:
        if published_raw:
            published = parsedate_to_datetime(str(published_raw))
            if published.tzinfo is None:
                published = published.replace(tzinfo=timezone.utc)
            published = published.astimezone(timezone.utc)
    except Exception:
        published = None

    if published is not None:
        age_hours = max(0.0, (now - published).total_seconds() / 3600)
        if age_hours >= 24:
            return True

        # A fresh source URL with no prior receipt is genuinely fresh reporting even
        # when its subject occurred Monday/Sunday/yesterday.  Only an exact publisher
        # URL already received as an older article can prove timestamp retouching.
        receipt = _category_story_matching_source_receipt(item, archive)
        receipt_dt = _category_story_receipt_datetime(receipt)
        if receipt_dt is not None:
            receipt_age_hours = max(0.0, (now - receipt_dt).total_seconds() / 3600)
            # Require a materially older receipt.  A same-day archive copy is simply
            # the current canonical representation and must not demote the story.
            if receipt_age_hours >= 24:
                return True
        return False

    # If no trustworthy source timestamp exists, retain a conservative textual
    # fallback.  This path is deliberately secondary: event-day language must never
    # override a valid fresh publication receipt.
    from datetime import timedelta
    stale_days = {
        (now - timedelta(days=days)).strftime("%A").lower()
        for days in range(1, 5)
    }
    for day in stale_days:
        if (
            f" {day} " in content
            or f" {day}," in content
            or f" {day}." in content
            or content.startswith(f"{day} ")
        ):
            return True
    if any(
        phrase in content
        for phrase in (
            "yesterday", "two days ago", "three days ago", "earlier this week",
            "last week", "days ago", "happened on", "occurred on", "took place on",
        )
    ):
        return True
    return False

def generate_category_content(category_key, category_label, headlines, request_timeout_seconds=None):
    # Build headlines with raw published strings for Claude to copy back
    def sanitize(text):
        if not text:
            return ""
        import re as _re
        # Remove characters that break JSON
        text = text.replace("\\", " ").replace('"', "'").replace("\n", " ").replace("\r", " ").replace("\t", " ")
        # Remove non-printable characters
        text = "".join(c for c in text if c.isprintable())
        # Remove any remaining control sequences
        text = _re.sub(r"[\x00-\x1f\x7f-\x9f]", " ", text)
        # Collapse whitespace
        text = _re.sub(r"\s+", " ", text).strip()
        return text

    def hl_line(i, h):
        pub     = sanitize(h.get("published", ""))
        pub_str = f" [pub:{pub}]" if pub else ""
        title   = sanitize(h.get("title", ""))
        quality = h.get("source_quality", "unknown")
        stype   = h.get("source_type", "unknown")
        hero_eligible = h.get("hero_eligible", "unknown")
        match_score = h.get("category_match_score", "")
        story_form = _source_story_form(h)
        content = h.get("article_text", "") or h.get("summary", "")
        # 14000 chars (~2300 words): the input the model writes from. Set high enough
        # that a normal article is never truncated, so key facts (ranked lists, names,
        # numbers) always reach the model. Only a pathologically long page would be cut.
        if story_form == "update" and h.get("_canonical_context_headline"):
            original_headline = sanitize(h.get("_canonical_context_headline", ""))
            original_body = sanitize(h.get("_canonical_context_body", ""))[:2400]
            return (
                f"{i+1}. {title} [source_type:{stype}] [source_quality:{quality}] "
                f"[hero_eligible:{hero_eligible}] [category_match_score:{match_score}] "
                f"[story_form:{story_form}]{pub_str}\n"
                f"   ORIGINAL PUBLISHED STORY: {original_headline}\n"
                f"   ORIGINAL STORY CONTEXT: {original_body}\n"
                f"   CURRENT UPDATE SOURCE: {sanitize(content)[:14000]}"
            )
        return f"{i+1}. {title} [source_type:{stype}] [source_quality:{quality}] [hero_eligible:{hero_eligible}] [category_match_score:{match_score}] [story_form:{story_form}]{pub_str}\n   {sanitize(content)[:14000]}"
    # Pre-filter headlines older than 48 hours before Claude sees them
    from datetime import timezone as _tz
    _now_utc = datetime.now(_tz.utc)
    def _is_stale(h):
        try:
            from email.utils import parsedate_to_datetime
            dt = parsedate_to_datetime(h.get("published","")).astimezone(_tz.utc)
            age_hrs = (_now_utc - dt).total_seconds() / 3600
            return age_hrs > category_max_age_hours(category_key)
        except Exception:
            return False
    if category_label == "Politics":
        print(f"  Politics pre-filter: {len(headlines)} headlines incoming")
        for h in headlines[:8]:
            stale = _is_stale(h)
            print(f"    [stale={stale}] [{h.get('published','NO DATE')}] {h.get('title','')[:55]}")
    fresh = [h for h in headlines if not _is_stale(h)]
    # Generation itself is stricter than section retention.  A thin section should
    # recover canonical archive stories, not mint a new article from stale sources.
    _hard_fresh = [
        _candidate for _candidate in fresh
        if not _new_publication_source_is_stale(
            _candidate, category_key, now=_now_utc
        )
    ]
    headlines = _hard_fresh

    headlines_text = "\n".join(hl_line(i, h) for i, h in enumerate(headlines))
    # Final safety pass — remove any remaining characters that break JSON
    headlines_text = headlines_text.replace("\\", " ")
    # Final nuclear sanitization — encode to ASCII and back to strip any remaining bad chars
    headlines_text = headlines_text.encode("ascii", "ignore").decode("ascii")

    # Category-specific hero selection rules
    cat_rules = {
        "world": "CRITICAL for World: pick a story about international geopolitics, foreign government actions, wars, diplomacy, or global crises. A celebrity death or cultural figure dying belongs in Entertainment, not World. Skip any story that is primarily about a single person's death unless they were a head of state or major political figure.",
        "business": "CRITICAL for Business: pick a story about markets, economic policy, major corporate decisions, trade, financial regulation, or industry-wide developments. An accident at a factory or airport (Boeing gear collapse, workplace injury) is NOT a business story — it belongs in U.S. or World. Business heroes should be about economic consequences, not physical accidents.",
        "us": "CRITICAL for U.S.: pick a story about something happening on US soil that affects American life broadly — policy, law, public safety, society. Avoid duplicating the Politics hero.",
        "politics": "CRITICAL for Politics: pick a story where the US government, Congress, White House, or Supreme Court is the PRIMARY actor. Foreign political news without direct US government involvement belongs in World.",
        "tech": "CRITICAL for Tech & Science: pick a story about technology products, companies, research, or scientific discoveries. Avoid general business stories that happen to involve a tech company.",
        "entertainment": "CRITICAL for Entertainment: this is the correct home for celebrity deaths, cultural figures, film, music, television, and arts. A major author or artist dying belongs HERE, not in World.",
        "sports": "CRITICAL for Sports: pick an actual sports result, trade, signing, or athletic achievement. Avoid crime or non-sports stories even if they involve athletes.",
    }
    rule = cat_rules.get(category_key, "")
    rule_line = f"\n\nCATEGORY RULE: {rule}" if rule else ""

    from datetime import timezone as _tz2
    _now2 = datetime.now(_tz2.utc)
    _today_label     = _now2.strftime("%A, %B %-d, %Y")
    _yesterday_label = (_now2 - timedelta(days=1)).strftime("%A, %B %-d")
    _date_context    = f"TODAY IS: {_today_label}. Yesterday was {_yesterday_label}. Use this to judge how recent each story is.\n\n"

    # Category-specific rules
    cat_rules = {
        "local_gov":    "Pick a story about local government decisions, zoning, budgets, elections, or public policy.",
        "crime":        "Pick an actual crime, arrest, or public safety story. Not politics or tax policy.",
        "business":     "Pick a story about local economic development, real estate, business openings/closings, or commercial projects.",
        "sports":       "Pick an actual sports result, game, team, athlete, coach, signing, tournament, championship, or St. Lucie Mets story. Do NOT pick lawsuits, consumer stories, crime, politics, general local news, or county government items as the Sports hero.",
        "things_to_do": "Pick a local event, activity, or attraction within 60 miles. Skip Orlando/Miami/Tampa unless very close.",
        "florida":      "Pick a statewide Florida story with broad impact. Not hyperlocal Treasure Coast.",
        "martin":       "Pick a story specifically about Martin County — Stuart, Jensen Beach, Palm City, Hobe Sound, Port Salerno.",
        "st_lucie":     "Pick a story specifically about St. Lucie County — Port St. Lucie, Fort Pierce.",
        "indian_river": "Pick a story specifically about Indian River County — Vero Beach, Sebastian, Fellsmere.",
    }
    rule = cat_rules.get(category_key, "")
    rule_line = f"\n\nCATEGORY RULE: {rule}" if rule else ""

    is_florida    = (category_key == "florida")
    system_prompt = FLORIDA_SYSTEM_PROMPT if is_florida else LOCAL_SYSTEM_PROMPT

    if category_key in COUNTY_KEYS:
        source_rules = """SOURCE RULES:
- Items marked [hero_eligible:no] must NOT be selected as the hero/section lead, even if they are full-source stories. They may only be used as lower cards if needed.
- Stories marked [source_quality:full] contain full article body text and should be used for the hero and the main full cards.
- Stories marked [source_quality:summary] may be used for normal cards only when the provided source contains enough concrete facts.
- Stories marked [source_quality:brief], [source_quality:thin], or [source_type:discovery_only] must NOT be used at all. Do not turn a blurb into an article.
- The hero must come from [source_quality:full] or [source_quality:summary].
- If there are not enough usable stories for six cards, return fewer cards. The site will backfill from its archive; never invent filler to populate the section.
- Do not write generic context such as "this reflects growth," "officials continue to investigate," or "residents are encouraged" unless those facts are explicitly in the source.

"""
    else:
        source_rules = """SOURCE RULES:
- Items marked [hero_eligible:no] must NOT be selected as the hero/section lead, even if they are full-source stories. They may only be used as lower cards if needed.
- Stories marked [source_quality:full] contain full article body text and may be used for the hero or full cards.
- Stories marked [source_quality:summary] may be used for shorter full cards only if the provided text has enough concrete facts.
- Stories marked [source_quality:brief], [source_quality:thin], or [source_type:discovery_only] must NOT be used for the hero and must not be padded into full articles.
- If there are not enough usable stories for six cards, return fewer cards rather than writing filler.
- Do not write generic context such as "this reflects growth," "officials continue to investigate," or "residents are encouraged" unless those facts are explicitly in the source.

"""

    lead_standard = LEAD_AND_HEADLINE_INTEGRITY_STANDARD

    if is_florida:
        prompt = f"""{_date_context}Florida news headlines:{rule_line}

{source_rules}{lead_standard}{headlines_text}

Tasks:
1. Pick the single most important/urgent Florida statewide story. Prioritize broad impact — legislation, court rulings, economic news, environmental decisions, significant crimes or disasters anywhere in the state.
2. Write an accurate Florida-focused headline. Name the specific Florida city, region, or institution when relevant.
3. Write a 380-430 word factual article in FOUR full paragraphs. Cover what happened, who is affected across Florida, and what happens next statewide.
4. For the next {CARDS_PER_CATEGORY} most important Florida stories write a teaser (one to two sentences) and a body of two to three full paragraphs. Ground all specific facts in the source. Always preserve proper nouns. Never write absence language. Include an urgency_score (1-10). Cards MUST be different stories from the hero.

Return ONLY valid JSON:
{{
  "hero": {{"headline": "...", "body": "full article", "urgency_score": <1-10>, "published": "copy [pub:...] exactly", "source_index": <number>}},
  "cards": [{{"headline": "...", "teaser": "...", "body": "two to three paragraphs...", "urgency_score": <1-10>, "published": "copy timestamp", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}]
}}
"""
    else:
        prompt = f"""{_date_context}Local Treasure Coast news headlines for {category_label}:{rule_line}

{source_rules}{lead_standard}{headlines_text}

Tasks:
1. Pick the single most important/urgent story for Treasure Coast Florida residents. LOCAL stories (county commission decisions, local crime, school district news, local business, road/infrastructure, local sports) rank ABOVE national or state stories unless the national story has very direct local impact.
2. Write an accurate, locally-framed headline. Name the specific county, city, or town in the headline when relevant.
3. Write a complete, readable factual article of four full paragraphs covering what happened, who is affected locally, the context, and what happens next. Never write absence language.
4. For the next {CARDS_PER_CATEGORY} most important stories write a teaser (one to two sentences) and a body of two to three full paragraphs. Always preserve proper nouns — school names, road names, business names, people's names. If the source names specific schools, streets, or institutions, those names MUST appear in the card. Never write absence language. Include an urgency_score (1-10). Cards MUST be different stories from the hero.

Return ONLY valid JSON:
{{
  "hero": {{"headline": "...", "body": "full article", "urgency_score": <1-10>, "published": "copy [pub:...] exactly", "source_index": <number>}},
  "cards": [{{"headline": "...", "teaser": "...", "body": "two to three paragraphs...", "urgency_score": <1-10>, "published": "copy timestamp", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}, {{"headline": "...", "teaser": "...", "body": "...", "urgency_score": <1-10>, "published": "...", "source_index": <number>}}]
}}
"""


    request_kwargs = {
        "model": MODEL_ARTICLES,
        "max_tokens": 5600,
        "system": [{
            "type": "text",
            "text": system_prompt,
            "cache_control": {"type": "ephemeral"}
        }],
        "messages": [{"role": "user", "content": prompt}],
        "extra_headers": {"anthropic-beta": "prompt-caching-2024-07-31"},
    }
    request_client = client
    if request_timeout_seconds is not None:
        request_timeout = max(1.0, float(request_timeout_seconds))
        # The Anthropic SDK retries transient failures by default. Disable those
        # hidden retries here because this pipeline owns a visible, bounded retry
        # policy and must keep the entire category inside its declared budget.
        if hasattr(client, "with_options"):
            request_client = client.with_options(timeout=request_timeout, max_retries=0)
        else:
            # Offline test clients generally expose only messages.create().
            request_kwargs["timeout"] = request_timeout
    response = request_client.messages.create(**request_kwargs)

    raw = response.content[0].text.strip()
    if raw.startswith("```"):
        raw = raw.split("```")[1]
        if raw.startswith("json"):
            raw = raw[4:]
    raw = raw.strip()

    try:
        from json_repair import repair_json
        data = json.loads(repair_json(raw))
    except Exception:
        try:
            data = json.loads(raw, strict=False)
        except json.JSONDecodeError:
            import re as _re
            cleaned = raw.encode("ascii", "ignore").decode("ascii")
            try:
                data = json.loads(cleaned, strict=False)
            except json.JSONDecodeError:
                start = cleaned.find("{")
                end   = cleaned.rfind("}") + 1
                if start == -1 or end <= start:
                    # The model returned no JSON object at all (empty string, a refusal,
                    # or prose). Raise a clear error the caller handles gracefully instead
                    # of crashing the whole run with a bare ValueError from .index().
                    raise ValueError(
                        f"Model returned no JSON object (got {len(cleaned)} chars of non-JSON)"
                    )
                data  = json.loads(cleaned[start:end], strict=False)
    # The model must return a JSON object. If it returns a bare array (e.g. a list
    # of story objects, or the object wrapped in a list), normalize it to the dict
    # we expect so we don't crash on data["category_key"] below.
    if isinstance(data, list):
        if len(data) == 1 and isinstance(data[0], dict):
            data = data[0]
        elif data and isinstance(data[0], dict) and "hero" in data[0]:
            data = data[0]
        elif all(isinstance(x, dict) for x in data) and data:
            # A list of story objects — treat first as hero, rest as cards
            data = {"hero": data[0], "cards": data[1:]}
        else:
            data = {"hero": {}, "cards": []}
    if not isinstance(data, dict):
        data = {"hero": {}, "cards": []}

    # Capture the exact successful production request packet and raw normalized
    # Sonnet 4.5 output before any downstream TCT post-processing. The challenger
    # runs later, after the normal build, from an in-memory copy only.
    if MODEL_BAKEOFF_ENABLED:
        _queue_model_bakeoff_category(
            category_key=category_key,
            category_label=category_label,
            headlines=headlines,
            request_kwargs=request_kwargs,
            baseline_output=data,
            baseline_response=response,
        )
    if ASSIGNMENT_EDITOR_SHADOW_ENABLED:
        _queue_assignment_editor_category(
            category_key=category_key,
            category_label=category_label,
            headlines=headlines,
            baseline_output=data,
            baseline_response=response,
        )

    data["category_key"]   = category_key
    data["category_label"] = category_label

    # Use source_index to attach original RSS link and image directly — no fuzzy matching needed
    def attach_source(item, headlines):
        # Model responses occasionally contain ``"hero": null`` or null card
        # entries. Treat those as an empty result that the caller can recover from;
        # never dereference None and turn a controlled category miss into a traceback.
        if not isinstance(item, dict):
            return {}
        idx = item.get("source_index")
        if idx is not None:
            try:
                source = headlines[int(idx) - 1]
                item["link"]      = source.get("link", "")
                item["image_url"] = source.get("image_url", "")
                item["source_quality"] = source.get("source_quality", "")
                item["source_type"] = source.get("source_type", "")
                item["article_text"] = source.get("article_text", "")
                item["source_summary"] = source.get("summary", "")
                item["source_word_count"] = _word_count(
                    source.get("article_text", "") or source.get("summary", "")
                )
                # Carry the ORIGINAL RSS title through. The generated headline is a
                # rewrite and will not be found in STORY_CLASSIFICATION (which is keyed
                # on RSS titles), so without this the eligibility guard falls back to
                # keyword logic and rejects stories the classifier already approved —
                # which is what was emptying whole categories of their heroes.
                item["source_title"] = source.get("title", "")
                item["story_form"] = _source_story_form(source)
                for context_key in (
                    "_canonical_context_slug",
                    "_canonical_context_headline",
                    "_canonical_context_body",
                    "_canonical_context_first_published",
                    "_canonical_context_basis",
                    "_story_aware_update_context",
                ):
                    if source.get(context_key) not in (None, ""):
                        item[context_key] = source.get(context_key)
                item["feed_url"] = source.get("feed_url", "")
            except (IndexError, ValueError, TypeError):
                item["link"]      = ""
                item["image_url"] = ""
        else:
            item["link"]      = ""
            item["image_url"] = ""

        # Format published
        raw_pub = item.get("published", "").replace("pub:", "").strip().strip("[]")
        item["published_raw"] = raw_pub
        item["published"] = format_age(raw_pub)
        return item

    data["hero"] = attach_source(data.get("hero"), headlines)
    data["hero"]["body"] = strip_absence_language(strip_markdown(data["hero"].get("body", ""), data["hero"].get("headline", "")))
    normalized_cards = []
    for card in data.get("cards", []) or []:
        card = attach_source(card, headlines)
        if not card:
            continue
        card["body"] = strip_absence_language(strip_markdown(card.get("body", ""), card.get("headline", "")))
        normalized_cards.append(card)
    data["cards"] = normalized_cards

    # Deterministic update-lead gate. A contextless update hero triggers the normal
    # bounded category retry; contextless update cards are removed rather than
    # published as standalone articles.
    _contextual_update_lead_rejections = []
    _hero_diag = _update_lead_diagnostics(data.get("hero", {}), data.get("hero", {}))
    if _hero_diag.get("required") and not _hero_diag.get("passed"):
        _contextual_update_lead_rejections.append({"surface": "hero", **_hero_diag})
        raise ContextualUpdateLeadError(
            "Contextless update lead for hero: "
            + ",".join(_hero_diag.get("missing") or ["unknown"])
            + f" — {_hero_diag.get('source_title','')[:120]}"
        )

    _contextual_cards = []
    for _card in data.get("cards", []) or []:
        _card_diag = _update_lead_diagnostics(_card, _card)
        if _card_diag.get("required") and not _card_diag.get("passed"):
            _contextual_update_lead_rejections.append({"surface": "card", **_card_diag})
            print(
                "  Contextual update-lead guard removed card: "
                f"'{_card.get('headline','')[:65]}' "
                f"({','.join(_card_diag.get('missing') or ['unknown'])})"
            )
            continue
        _contextual_cards.append(_card)
    data["cards"] = _contextual_cards
    data["_contextual_update_lead_rejections"] = _contextual_update_lead_rejections

    # Universal article-framing contract. Unlike the older update-only guard, this
    # applies to every generated non-custom article. Heroes retry inside the bounded
    # category budget; invalid cards are removed rather than published.
    _article_framing_rejections = []
    _hero_framing = _article_framing_diagnostics(data.get("hero", {}), data.get("hero", {}))
    if _hero_framing.get("required") and not _hero_framing.get("passed"):
        _article_framing_rejections.append({"surface": "hero", **_hero_framing})
        raise ArticleFramingIntegrityError(
            "Article framing integrity failed for hero: "
            + ",".join(_hero_framing.get("missing") or ["unknown"])
            + f" — {_hero_framing.get('headline','')[:120]}"
        )

    _framed_cards = []
    for _card in data.get("cards", []) or []:
        _card_framing = _article_framing_diagnostics(_card, _card)
        if _card_framing.get("required") and not _card_framing.get("passed"):
            _article_framing_rejections.append({"surface": "card", **_card_framing})
            print(
                "  Article-framing guard removed card: "
                f"'{_card.get('headline','')[:65]}' "
                f"({','.join(_card_framing.get('missing') or ['unknown'])})"
            )
            continue
        _framed_cards.append(_card)
    data["cards"] = _framed_cards
    data["_article_framing_rejections"] = _article_framing_rejections

    # Enforce category lead eligibility in Python, not just by prompt. Claude can
    # still be tempted by a full-source off-topic item from a broad WPTV feed.
    def _item_hero_eligible(item):
        idx = item.get("source_index")
        try:
            return headlines[int(idx) - 1].get("hero_eligible") == "yes"
        except Exception:
            return False

    # Obituary check on GENERATED content. Reported deaths remain eligible when the
    # copy merely notes surviving relatives; funeral-listing structure is required.
    def _is_obituary_content(item):
        return _looks_like_obituary_listing(
            item.get("headline", ""), item.get("body", "")
        )

    # If the hero is an obituary, swap in the first non-obituary card
    if _is_obituary_content(data.get("hero", {})) and data.get("cards"):
        for ci, card in enumerate(data["cards"]):
            if not _is_obituary_content(card):
                print(f"  Obituary hero swap for {category_label}: '{data['hero'].get('headline','')[:50]}' -> '{card.get('headline','')[:50]}'")
                data["hero"] = card
                data["cards"].pop(ci)
                break

    # Also drop any obituary cards entirely
    if data.get("cards"):
        data["cards"] = [c for c in data["cards"] if not _is_obituary_content(c)]

    if not _item_hero_eligible(data.get("hero", {})) and data.get("cards"):
        for ci, card in enumerate(data["cards"]):
            if _item_hero_eligible(card):
                old_hero = data["hero"]
                print(f"  Hero eligibility swap for {category_label}: '{old_hero.get('headline','')[:55]}' -> '{card.get('headline','')[:55]}'")
                if not old_hero.get("teaser"):
                    _body = old_hero.get("body", "").strip()
                    _first = _body.split(". ")[0].strip()
                    old_hero["teaser"] = (_first[:160] + ".") if _first else ""
                data["hero"] = card
                data["cards"][ci] = old_hero
                break

    # Content-based category guard: the final hero must actually match the category
    # by content (topic terms present, no hard negatives), regardless of what Claude
    # flagged. Catches cases like a house-fire tragedy landing in Sports.
    # Only applies to TOPIC categories — counties are geographic and already filtered
    # upstream by relevance scoring, so re-checking them here wrongly empties sections.
    _topic_guard_cats = {"sports", "business", "crime", "things_to_do", "local_gov", "florida"}
    if category_key in _topic_guard_cats:
        if not _hero_eligible(category_key, data.get("hero", {})):
            swapped = False
            for ci, card in enumerate(data.get("cards", [])):
                if _hero_eligible(category_key, card):
                    print(f"  Category content swap for {category_label}: '{data['hero'].get('headline','')[:50]}' -> '{card.get('headline','')[:50]}'")
                    old_hero = data["hero"]
                    data["hero"] = card
                    data["cards"][ci] = old_hero
                    swapped = True
                    break
            if not swapped:
                # Nothing swapped here, but do NOT drop yet: the final guard below has
                # the full recovery cascade (card swap, county archive fallback, and
                # highest-urgency promotion). Dropping this early was killing sections
                # that the later safety nets would have saved.
                print(f"  Category guard: no eligible swap found for {category_label}; deferring to final guard")

    # Age-based score decay for stale non-breaking stories
    def decay_score(item):
        score = item.get("urgency_score", 5)
        idx = item.get("source_index")
        if idx is None: return item
        try:
            pub_raw = headlines[int(idx) - 1].get("published", "")
            if not pub_raw: return item
            from email.utils import parsedate_to_datetime
            from datetime import timezone
            dt  = parsedate_to_datetime(pub_raw).astimezone(timezone.utc)
            now = datetime.now(timezone.utc)
            hrs = (now - dt).total_seconds() / 3600
            headline = item.get("headline", "").lower()
            fresh_words = ["confirms","confirmed","announces","announced","charges","charged",
                          "arrested","arrest","resigns","resigned","fired","breaks","exclusive",
                          "new details","emerges","emerged","discovered","uncovers","uncovered",
                          "identified","named","ruled","plot","conspiracy","indicted","sentenced",
                          "found guilty","linked","motive","cause of death"]
            is_fresh = any(w in headline for w in fresh_words)
            if not is_fresh:
                if hrs > 48: score = min(score, 4)
                elif hrs > 36: score = min(score, 5)
                elif hrs > 24: score = min(score, 7)
                elif hrs > 12: score = min(score, 8)
        except Exception:
            pass
        item["urgency_score"] = score
        return item

    decay_score(data["hero"])
    for card in data.get("cards", []): decay_score(card)

    # Age cap function — parses RSS timestamps properly
    def apply_age_cap(item):
        from email.utils import parsedate_to_datetime
        from datetime import timezone, timedelta
        import re as _re
        score = item.get("urgency_score", 5)
        # Try to get age from source headline timestamp via source_index
        idx = item.get("source_index")
        pub_raw = ""
        if idx is not None:
            try:
                pub_raw = headlines[int(idx) - 1].get("published", "")
            except Exception:
                pass
        if not pub_raw:
            pub_raw = item.get("published", "")
        if not pub_raw:
            return
        try:
            dt  = parsedate_to_datetime(pub_raw).astimezone(timezone.utc)
            now = datetime.now(timezone.utc)
            hrs = (now - dt).total_seconds() / 3600
        except Exception:
            return

        headline_lower = item.get("headline", "").lower()
        body_lower     = item.get("body", "").lower()[:400]
        one_time_events = ["resigns", "resigned", "steps down", "fired", "dies", "dead at",
                           "killed in", "found dead", "passed away", "obituary"]

        if hrs > 48:
            item["urgency_score"] = min(score, 4)
        elif hrs > 24:
            if any(w in headline_lower for w in one_time_events):
                item["urgency_score"] = min(score, 4)
            else:
                item["urgency_score"] = min(score, 6)
        elif hrs > 12:
            if any(w in headline_lower for w in one_time_events):
                item["urgency_score"] = min(score, 6)
            else:
                # Check for stale body signals
                _now   = datetime.now(timezone.utc)
                _dates = [(_now - timedelta(days=d)).strftime("%B %d").lower().replace(" 0", " ") for d in range(2, 14)]
                _months_gone = [(_now - timedelta(days=d*30)).strftime("%B").lower() for d in range(1, 6)]
                stale_body_signals = ["last week", "last month", "a week ago", "days ago",
                                      "on monday", "on tuesday", "on wednesday", "on thursday",
                                      "on friday", "on saturday", "on sunday"] + _dates + _months_gone
                if any(s in body_lower for s in stale_body_signals):
                    item["urgency_score"] = min(score, 6)

    apply_age_cap(data["hero"])
    if data["hero"].get("published", "") and not any(w in data["hero"]["published"].lower() for w in ["minute", "hour", "a few", ":"]):
        print(f"  Hard age cap applied: hero is from {data['hero']['published']}")
    for card in data.get("cards", []):
        apply_age_cap(card)

    # Stale-hero swap: preserve the shared live/shadow stale-story contract.
    # The test still catches publisher re-touches of old events, but no longer treats
    # a genuinely current-day update as stale merely because it describes yesterday's
    # underlying incident.
    _now_c = datetime.now(timezone.utc)
    _stale_archive = load_archive(OUTPUT_DIR / "archive.json")

    def _story_is_stale(item):
        pub_raw = ""
        idx = item.get("source_index") if isinstance(item, dict) else None
        if idx is not None:
            try:
                pub_raw = headlines[int(idx) - 1].get("published", "")
            except Exception:
                pub_raw = ""
        return _category_story_is_stale(
            item, _stale_archive, pub_raw, now=_now_c
        )

    if _story_is_stale(data["hero"]) and data.get("cards"):
        for ci, card in enumerate(data["cards"]):
            if _story_is_stale(card):
                continue
            # The replacement must also be eligible for this category —
            # _hero_eligible routes to topic-matching for topic categories and
            # geographic-matching for counties, so this is safe for all.
            if not _hero_eligible(category_key, card):
                continue
            old_hero = data["hero"]
            print(f"  Stale hero swapped: '{old_hero.get('headline','')[:50]}' -> '{card.get('headline','')[:50]}'")
            if not old_hero.get("teaser"):
                _body = old_hero.get("body", "").strip()
                _first = _body.split(". ")[0].strip()
                old_hero["teaser"] = (_first[:160] + ".") if _first else ""
            data["hero"] = card
            data["cards"][ci] = old_hero
            break

    # FINAL eligibility guard — runs last, after all other swaps. Applies to ALL
    # categories: topic categories require topic match, counties require geographic
    # match (both handled inside _hero_eligible).
    if True:
        # Keep a copy BEFORE the eligibility filter. If every card gets filtered out
        # and the hero is rejected too, the section would be dropped despite having
        # had real content — so the last-resort promotion below falls back to this.
        _cards_before_filter = list(data.get("cards", []))
        # Drop cards that don't belong in this category
        if data.get("cards"):
            data["cards"] = [c for c in data["cards"] if _hero_eligible(category_key, c)]

        # HARD LOCALITY GATE for county pages. The classifier sometimes places an
        # out-of-area story (a Palm Beach wildfire, a Minneapolis rally) into a county
        # and flags it hero-eligible. If that wrong story sits in the hero slot, the
        # archive fallback below never fires (the code thinks the county already has a
        # valid hero), and the county page leads with non-local news. So: a county hero
        # MUST name one of that county's places. If it does not, clear it here so the
        # eligibility swap / archive fallback replaces it with genuinely local content.
        _county_places = {
            "martin": ["martin county", "stuart", "jensen beach", "palm city",
                       "hobe sound", "port salerno", "jupiter island",
                       "hutchinson island", "indiantown", "palm city"],
            "st_lucie": ["st. lucie", "st lucie", "port st. lucie", "port st lucie",
                         "fort pierce", "st. lucie west", "hutchinson island"],
            "indian_river": ["indian river", "vero beach", "sebastian", "fellsmere",
                             "wabasso", "gifford"],
        }.get(category_key, [])
        if _county_places:
            def _names_local_place(item):
                blob = (item.get("headline", "") + " " + item.get("teaser", "") + " "
                        + item.get("body", "")).lower()
                return any(p in blob for p in _county_places)
            if data.get("hero") and not _names_local_place(data["hero"]):
                print(f"  Non-local hero cleared for {category_label}: "
                      f"'{data['hero'].get('headline','')[:50]}' names no local place")
                # Try a local card first; else leave hero to the archive fallback below.
                _local_card = None
                for _ci, _c in enumerate(data.get("cards", [])):
                    if _names_local_place(_c):
                        _local_card = _ci
                        break
                if _local_card is not None:
                    data["hero"] = data["cards"].pop(_local_card)
                else:
                    data["hero"] = {}
            # Drop non-local cards from county pages too
            if data.get("cards"):
                data["cards"] = [c for c in data["cards"] if _names_local_place(c)]

        if not _hero_eligible(category_key, data.get("hero", {})):
            _fixed = False
            for ci, card in enumerate(data.get("cards", [])):
                if _hero_eligible(category_key, card):
                    old_hero = data["hero"]
                    data["hero"] = card
                    data["cards"][ci] = old_hero
                    print(f"  Final category guard swap for {category_label}: '{old_hero.get('headline','')[:50]}' -> '{card.get('headline','')[:50]}'")
                    _fixed = True
                    break
            if not _fixed:
                # Before dropping a page, try to build its hero from the recent archive.
                # Live feeds are intermittent (WPTV rotates stories, Google News items
                # come in thin), so a category can end up with nothing hero-eligible
                # even though a relevant story was archived in the last few days. This
                # applies to BOTH county pages AND topic categories (crime, business,
                # etc.) — previously only counties were backfilled, so topic categories
                # with good recent archived articles were wrongly dropped.
                _is_county = category_key in COUNTY_KEYS
                _cf = {
                    "martin": ["martin county", "stuart", "jensen beach", "palm city",
                               "hobe sound", "port salerno", "jupiter island",
                               "hutchinson island", "indiantown"],
                    "st_lucie": ["st. lucie", "st lucie", "port st. lucie",
                                 "port st lucie", "fort pierce"],
                    "indian_river": ["indian river", "vero beach", "sebastian", "fellsmere"],
                }.get(category_key, [])
                try:
                    _arch = load_archive(OUTPUT_DIR / "archive.json")
                    _arch.sort(key=lambda e: e.get("lastmod") or e.get("date",""), reverse=True)
                    from datetime import timezone as _tzf
                    _nowf = datetime.now(_tzf.utc)
                    for e in _arch:
                        # County pages match on place names; topic categories match on
                        # the archived story's own category_key.
                        if _is_county:
                            _htext = (e.get("headline","") + " " + e.get("teaser","")).lower()
                            if not any(p in _htext for p in _cf):
                                continue
                        else:
                            if e.get("category_key") != category_key:
                                continue
                        _d = e.get("lastmod") or e.get("date","")
                        try:
                            _dt = datetime.strptime(_d[:10], "%Y-%m-%d").replace(tzinfo=_tzf.utc)
                            # Topic categories may reach a little further back (7 days)
                            # than counties (4) — a recent crime or business story is
                            # still worth showing rather than an empty section.
                            _max_age = 4 if _is_county else 7
                            if (_nowf - _dt).days > _max_age:
                                continue
                        except Exception:
                            continue
                        _archive_candidate = {
                            "headline": e.get("headline",""),
                            "title": e.get("headline",""),
                            "teaser": e.get("teaser",""),
                            "summary": e.get("teaser",""),
                            "body": e.get("teaser",""),
                            "image_url": e.get("image_url",""),
                            "published": e.get("lastmod") or e.get("date",""),
                            "published_raw": e.get("lastmod") or e.get("date",""),
                            "source_quality": "full",
                            "feed_url": e.get("feed_url", ""),
                            "enriched": True,
                            "urgency_score": 4,
                            "link": f"{SITE_URL}/articles/{e['slug']}.html",
                            "_archived_slug": e["slug"],
                        }
                        # Never trust the old archive tag by itself; older runs may have
                        # stored category bleed. Revalidate the archived story now.
                        if not _hero_eligible(category_key, _archive_candidate):
                            continue
                        data["hero"] = _archive_candidate
                        print(f"  Archive-hero fallback for {category_label}: '{e.get('headline','')[:50]}'")
                        _fixed = True
                        break
                except Exception as _ex:
                    print(f"  Archive fallback failed: {_ex}")
                if not _fixed:
                    # LAST RESORT: if this category has ANY cards, one of them becomes
                    # the hero. A section with cards but no hero is never correct — it
                    # is what happens when the guards above reject a hero that the
                    # classifier already approved. Promote the highest-urgency card
                    # rather than dropping a section that plainly has content.
                    _cards = [
                        c for c in (data.get("cards", []) or _cards_before_filter)
                        if _hero_eligible(category_key, c)
                    ]
                    if _cards:
                        _best_i = max(
                            range(len(_cards)),
                            key=lambda i: int(_cards[i].get("urgency_score", 0) or 0),
                        )
                        _best = _cards[_best_i]
                        data["hero"] = _best
                        data["cards"] = _cards[:_best_i] + _cards[_best_i + 1:]
                        print(f"  Promoting highest-urgency card to hero for {category_label}: "
                              f"'{_best.get('headline','')[:50]}'")
                        _fixed = True

                if _fixed:
                    data["_drop_category"] = False  # a hero was recovered; never keep a stale drop flag
                else:
                    print(f"  Dropping {category_label}: no eligible hero available")
                    data["_drop_category"] = True

    return data


def _category_generation_error_code(exc):
    name = type(exc).__name__.lower()
    message = str(exc or "").lower()
    if isinstance(exc, ContextualUpdateLeadError) or "contextless update lead" in message:
        return "contextless_update_lead"
    if isinstance(exc, ArticleFramingIntegrityError) or "article framing integrity" in message:
        return "article_framing_integrity"
    if "timeout" in name or "timed out" in message or "timeout" in message:
        return "model_timeout"
    if isinstance(exc, (ValueError, json.JSONDecodeError)) or "json" in name or "json" in message:
        return "invalid_json"
    return "generation_exception"


def _safe_exception_summary(exc, limit=240):
    text = re.sub(r"\s+", " ", str(exc or "")).strip()
    if not text:
        text = type(exc).__name__
    return text[:limit]


def _run_category_generation_with_budget(category_key, category_label, headlines):
    """Generate one category with a bounded two-attempt model budget.

    This helper contains model failures inside the category boundary. It returns
    ``(None, diagnostics)`` after a persistent failure so the normal permanent
    archive recovery path can fill the section without a Python traceback.
    """
    started = time.perf_counter()
    attempts = []
    last_code = ""
    last_summary = ""

    for attempt_number in range(1, CATEGORY_GENERATION_MAX_ATTEMPTS + 1):
        elapsed = time.perf_counter() - started
        remaining = CATEGORY_GENERATION_BUDGET_SECONDS - elapsed
        if remaining <= 0 or (
            attempt_number > 1 and remaining < CATEGORY_GENERATION_MIN_RETRY_SECONDS
        ):
            last_code = "generation_budget_exhausted"
            last_summary = (
                f"No retry window remained inside the {CATEGORY_GENERATION_BUDGET_SECONDS:.0f}s "
                "category generation budget"
            )
            break

        request_timeout = min(CATEGORY_MODEL_CALL_TIMEOUT_SECONDS, remaining)
        attempt_started = time.perf_counter()
        try:
            data = generate_category_content(
                category_key,
                category_label,
                headlines,
                request_timeout_seconds=request_timeout,
            )
            attempt_elapsed = time.perf_counter() - attempt_started
            usable_hero = (
                isinstance(data, dict)
                and isinstance(data.get("hero"), dict)
                and bool(str(data["hero"].get("headline") or "").strip())
                and not data.get("_drop_category")
            )
            if usable_hero:
                attempts.append({
                    "attempt": attempt_number,
                    "timeout_seconds": round(request_timeout, 1),
                    "elapsed_seconds": round(attempt_elapsed, 3),
                    "result": "success",
                })
                _lead_rejections = list(
                    data.get("_contextual_update_lead_rejections", []) or []
                )
                _framing_rejections = list(
                    data.get("_article_framing_rejections", []) or []
                )
                return data, {
                    "status": "success",
                    "attempt_count": len(attempts),
                    "attempts": attempts,
                    "model_elapsed_seconds": round(time.perf_counter() - started, 3),
                    "failure_code": "",
                    "failure_summary": "",
                    "budget_seconds": CATEGORY_GENERATION_BUDGET_SECONDS,
                    "contextual_update_lead_rejection_count": len(_lead_rejections),
                    "contextual_update_lead_rejections": _lead_rejections,
                    "article_framing_rejection_count": len(_framing_rejections),
                    "article_framing_rejections": _framing_rejections,
                }

            last_code = "missing_or_null_hero"
            last_summary = "Model response did not contain a usable hero after normalization"
            attempts.append({
                "attempt": attempt_number,
                "timeout_seconds": round(request_timeout, 1),
                "elapsed_seconds": round(attempt_elapsed, 3),
                "result": last_code,
                "error_summary": last_summary,
            })
        except Exception as exc:
            attempt_elapsed = time.perf_counter() - attempt_started
            last_code = _category_generation_error_code(exc)
            last_summary = _safe_exception_summary(exc)
            attempts.append({
                "attempt": attempt_number,
                "timeout_seconds": round(request_timeout, 1),
                "elapsed_seconds": round(attempt_elapsed, 3),
                "result": last_code,
                "error_type": type(exc).__name__,
                "error_summary": last_summary,
            })

        if attempt_number < CATEGORY_GENERATION_MAX_ATTEMPTS:
            remaining_after = CATEGORY_GENERATION_BUDGET_SECONDS - (time.perf_counter() - started)
            if remaining_after >= CATEGORY_GENERATION_MIN_RETRY_SECONDS:
                print(
                    f"  Category generation attempt {attempt_number} failed for {category_label}: "
                    f"{last_code} ({last_summary}); retrying once with "
                    f"{remaining_after:.0f}s remaining"
                )

    return None, {
        "status": "failed",
        "attempt_count": len(attempts),
        "attempts": attempts,
        "model_elapsed_seconds": round(time.perf_counter() - started, 3),
        "failure_code": last_code or "generation_failed",
        "failure_summary": last_summary or "Category generation failed without a usable response",
        "budget_seconds": CATEGORY_GENERATION_BUDGET_SECONDS,
    }


def _finalize_category_generation_record(record, status, started, **updates):
    record.update(updates)
    record["status"] = status
    record["elapsed_seconds"] = round(time.perf_counter() - started, 3)
    record.pop("_started", None)
    return record


def _build_category_generation_report(records):
    status_counts = defaultdict(int)
    failure_counts = defaultdict(int)
    total_attempts = 0
    total_model_seconds = 0.0
    archive_recovery_count = 0
    sports_expired_event_preview_count = 0
    contextual_update_lead_rejection_count = 0
    article_framing_rejection_count = 0
    category_eligibility_rejection_count = 0
    published_story_duplicate_suppression_count = 0
    story_aware_update_context_count = 0
    material_update_promotion_evaluation_count = 0
    material_update_promotion_count = 0
    material_update_promotion_cache_hit_count = 0
    material_update_promotion_model_call_count = 0
    for record in records:
        status_counts[str(record.get("status") or "unknown")] += 1
        failure_code = str(record.get("failure_code") or "")
        if failure_code:
            failure_counts[failure_code] += 1
        total_attempts += int(record.get("attempt_count") or 0)
        total_model_seconds += float(record.get("model_elapsed_seconds") or 0.0)
        archive_recovery_count += int(bool(record.get("archive_recovery_requested")))
        sports_expired_event_preview_count += int(
            record.get("sports_expired_event_preview_count") or 0
        )
        contextual_update_lead_rejection_count += int(
            record.get("contextual_update_lead_rejection_count") or 0
        )
        contextual_update_lead_rejection_count += sum(
            1
            for attempt in (record.get("attempts") or [])
            if str(attempt.get("result") or "") == "contextless_update_lead"
        )
        article_framing_rejection_count += int(
            record.get("article_framing_rejection_count") or 0
        )
        article_framing_rejection_count += sum(
            1
            for attempt in (record.get("attempts") or [])
            if str(attempt.get("result") or "") == "article_framing_integrity"
        )
        category_eligibility_rejection_count += int(
            record.get("category_eligibility_rejection_count") or 0
        )
        published_story_duplicate_suppression_count += int(
            record.get("published_story_duplicate_suppression_count") or 0
        )
        story_aware_update_context_count += int(
            record.get("story_aware_update_context_count") or 0
        )
        material_update_promotion_evaluation_count += int(
            record.get("material_update_promotion_evaluation_count") or 0
        )
        material_update_promotion_count += int(
            record.get("material_update_promotion_count") or 0
        )
        material_update_promotion_cache_hit_count += int(
            record.get("material_update_promotion_cache_hit_count") or 0
        )
        material_update_promotion_model_call_count += int(
            record.get("material_update_promotion_model_call_count") or 0
        )

    return {
        "schema_version": CATEGORY_GENERATION_REPORT_SCHEMA_VERSION,
        "generated_at": _utc_now_iso(),
        "policy": {
            "mode": "fail_closed_archive_recovery",
            "model_call_timeout_seconds": CATEGORY_MODEL_CALL_TIMEOUT_SECONDS,
            "category_generation_budget_seconds": CATEGORY_GENERATION_BUDGET_SECONDS,
            "max_attempts": CATEGORY_GENERATION_MAX_ATTEMPTS,
            "minimum_retry_window_seconds": CATEGORY_GENERATION_MIN_RETRY_SECONDS,
            "removed_dead_feeds": [
                "https://www.wptv.com/feeds/rss/news",
                "https://www.wptv.com/feeds/rss/local",
            ],
        },
        "summary": {
            "category_count": len(records),
            "statuses": dict(sorted(status_counts.items())),
            "failures": dict(sorted(failure_counts.items())),
            "model_attempt_count": total_attempts,
            "model_elapsed_seconds": round(total_model_seconds, 3),
            "archive_recovery_requested_count": archive_recovery_count,
            "sports_expired_event_preview_count": sports_expired_event_preview_count,
            "contextual_update_lead_rejection_count": contextual_update_lead_rejection_count,
            "article_framing_rejection_count": article_framing_rejection_count,
            "category_eligibility_rejection_count": category_eligibility_rejection_count,
            "published_story_duplicate_suppression_count": published_story_duplicate_suppression_count,
            "story_aware_update_context_count": story_aware_update_context_count,
            "material_update_promotion_evaluation_count": material_update_promotion_evaluation_count,
            "material_update_promotion_count": material_update_promotion_count,
            "material_update_promotion_cache_hit_count": material_update_promotion_cache_hit_count,
            "material_update_promotion_model_call_count": material_update_promotion_model_call_count,
        },
        "categories": records,
    }


def _write_category_generation_report(records, output_path=None):
    report = _build_category_generation_report(records)
    path = Path(output_path or CATEGORY_GENERATION_REPORT_PATH)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    temporary.replace(path)
    return report


def _build_category_eligibility_report(records):
    categories = []
    total_assessed = 0
    total_rejected = 0
    for record in records:
        assessed = int(record.get("category_eligibility_assessed_count") or 0)
        rejected = list(record.get("category_eligibility_rejections") or [])
        total_assessed += assessed
        total_rejected += len(rejected)
        config = _category_contract_config(record.get("category_key", ""))
        categories.append({
            "category_key": record.get("category_key", ""),
            "category_label": record.get("category_label", ""),
            "mode": config.get("mode", "observe_only"),
            "policy": config.get("policy", "unregistered_category"),
            "assessed_count": assessed,
            "rejected_count": len(rejected),
            "rejections": rejected,
        })
    return {
        "schema_version": CATEGORY_ELIGIBILITY_REPORT_SCHEMA_VERSION,
        "generated_at": _utc_now_iso(),
        "contract_version": CATEGORY_ELIGIBILITY_CONTRACT_VERSION,
        "category_contract_versions": {
            "local_gov": CATEGORY_ELIGIBILITY_CONTRACT_VERSION,
            "business": BUSINESS_ELIGIBILITY_CONTRACT_VERSION,
            "crime": CRIME_ELIGIBILITY_CONTRACT_VERSION,
            "things_to_do": THINGS_TO_DO_ELIGIBILITY_CONTRACT_VERSION,
        },
        "rollout_policy": (
            "shared_contract_interface; Local Government, Business & Development, Crime & Safety, "
            "and Things To Do enforced; remaining topic contracts observe-only until regression fixtures "
            "are production-validated"
        ),
        "summary": {
            "assessed_count": total_assessed,
            "rejected_count": total_rejected,
            "enforced_categories": sorted(
                key for key, value in CATEGORY_ELIGIBILITY_CONTRACTS.items()
                if value.get("mode") == "enforce"
            ),
            "observe_only_categories": sorted(
                key for key, value in CATEGORY_ELIGIBILITY_CONTRACTS.items()
                if value.get("mode") == "observe_only"
            ),
            "existing_geographic_categories": sorted(
                key for key, value in CATEGORY_ELIGIBILITY_CONTRACTS.items()
                if value.get("mode") == "existing_geographic_enforce"
            ),
        },
        "categories": categories,
    }


def _write_category_eligibility_report(records, output_path=None):
    report = _build_category_eligibility_report(records)
    path = Path(output_path or CATEGORY_ELIGIBILITY_REPORT_PATH)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    temporary.replace(path)
    return report


# -- HTML GENERATION --

def now_et():
    from datetime import timezone, timedelta
    utc = datetime.now(timezone.utc)
    et  = utc - timedelta(hours=4)
    return et.strftime("%-I:%M %p ET")

def _now_eastern_rfc822():
    """Current time as an RFC-822 string in US Eastern time (EDT/EST aware).
    Used as the first-published timestamp for RSS pubDate so consumers like Nextdoor
    show when a story appeared on OUR site, not when the original source posted it."""
    from datetime import timezone as _tz, timedelta as _td
    # Eastern is UTC-4 (EDT) Mar-Nov, UTC-5 (EST) otherwise. Determine DST roughly by
    # US rules: 2nd Sunday March through 1st Sunday November.
    u = datetime.now(_tz.utc)
    y = u.year
    def _nth_sun(month, nth):
        d = datetime(y, month, 1, tzinfo=_tz.utc)
        first_sun = 1 + (6 - d.weekday()) % 7
        return first_sun + (nth - 1) * 7
    dst_start = datetime(y, 3, _nth_sun(3, 2), 7, tzinfo=_tz.utc)   # 2am EST = 7am UTC
    dst_end   = datetime(y, 11, _nth_sun(11, 1), 6, tzinfo=_tz.utc) # 2am EDT = 6am UTC
    offset = -4 if dst_start <= u < dst_end else -5
    eastern = u + _td(hours=offset)
    tzname = "-0400" if offset == -4 else "-0500"
    return eastern.strftime(f"%a, %d %b %Y %H:%M:%S {tzname}")


def _today_eastern_iso(now=None):
    """Return the Treasure Coast local calendar date for publication permalinks."""
    now = now or datetime.now(timezone.utc)
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    return now.astimezone(ZoneInfo("America/New_York")).date().isoformat()


def canonical_image_url(url):
    if not url: return ""
    return re.sub(r"[?#].*$", "", url.strip())


def make_paragraphs(text, preserve_all=False):
    if not text:
        return ""
    # Split on double newlines first, fall back to single newlines
    paragraphs = text.split("\n\n")
    if len(paragraphs) == 1:
        paragraphs = text.split("\n")

    # WALL-OF-TEXT FALLBACK. Some sources (notably Google News summaries) arrive with
    # their paragraph breaks stripped, so the whole article is one or two enormous
    # blocks that render as an unreadable wall. When a "paragraph" is very long and has
    # no internal breaks, regroup it into readable paragraphs of ~3 sentences each.
    # Markdown structure (##, ###, **, links) is preserved: only long plain blocks are
    # regrouped, and blocks that already contain markers are left alone.
    def _regroup_long(block):
        block = block.strip()
        if not block:
            return []
        # Leave structured/short blocks untouched
        if block.startswith(("## ", "### ")) or len(block) < 320:
            return [block]
        # Split into sentences (keep the terminator), then group ~3 per paragraph.
        # Protect common abbreviations so names such as "St. Lucie", "Dr. Smith",
        # and "U.S. 1" are not mistaken for sentence endings.
        import re as _re
        _abbr_token = "__TCT_ABBR_DOT__"
        _protected = block
        _abbreviations = (
            "St.", "Dr.", "Mr.", "Mrs.", "Ms.", "Jr.", "Sr.",
            "U.S.", "U.K.", "Fla.", "Ave.", "Blvd.", "Rd.",
            "Hwy.", "No.", "Inc.", "Co.", "Dept.", "Mt.",
        )
        for _abbr in _abbreviations:
            _protected = _re.sub(
                rf'(?<![A-Za-z]){_re.escape(_abbr)}',
                _abbr.replace(".", _abbr_token),
                _protected,
                flags=_re.IGNORECASE,
            )
        sentences = _re.split(r'(?<=[.!?])\s+(?=[A-Z"])', _protected)
        sentences = [s.replace(_abbr_token, ".").strip() for s in sentences if s.strip()]
        if len(sentences) < 4:
            return [block]  # not actually a wall; leave it
        groups, cur, cur_len = [], [], 0
        for s in sentences:
            cur.append(s)
            cur_len += len(s)
            # New paragraph every ~3 sentences or ~360 chars, whichever comes first
            if len(cur) >= 3 or cur_len >= 360:
                groups.append(" ".join(cur))
                cur, cur_len = [], 0
        if cur:
            # Avoid a lone trailing sentence: fold it into the previous paragraph
            if len(cur) == 1 and groups:
                groups[-1] = groups[-1] + " " + cur[0]
            else:
                groups.append(" ".join(cur))
        return groups

    _expanded = []
    for p in paragraphs:
        _expanded.extend(_regroup_long(p))
    paragraphs = _expanded

    def _inline(s):
        # Links first (before bold), so URLs inside markdown link syntax are handled
        # cleanly. Supports [text](url) markdown links and bare http(s) URLs. Applies
        # to every article rendered through make_paragraphs, custom or generated.
        # 1. Markdown links: [label](https://url) or [label](mailto:addr)
        s = re.sub(
            r'\[([^\]]+)\]\(((?:https?://|mailto:)[^)\s]+)\)',
            r'<a href="\2" rel="noopener">\1</a>',
            s,
        )
        # Add target=_blank to http(s) links only (mailto opens the mail client)
        s = re.sub(
            r'<a href="(https?://[^"]+)" rel="noopener">',
            r'<a href="\1" target="_blank" rel="noopener">',
            s,
        )
        # 2. Bare URLs not already inside an anchor tag
        def _bare(m):
            url = m.group(0)
            return f'<a href="{url}" target="_blank" rel="noopener">{url}</a>'
        s = re.sub(r'(?<!["\'>])(https?://[^\s<]+)', _bare, s)
        # 3. Bold
        s = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", s)
        return s

    out = []
    for p in paragraphs:
        p = p.strip()
        if not p:
            continue
        # Section header: line starting with "## "
        if p.startswith("## "):
            out.append(f'<h2 class="article-section">{_inline(p[3:].strip())}</h2>')
        # Sub-header: line starting with "### "
        elif p.startswith("### "):
            out.append(f'<h3 class="article-subhead">{_inline(p[4:].strip())}</h3>')
        # Markdown bullet block. Custom articles preserve every submitted item and
        # render it as a real list rather than flattening or dropping short lines.
        elif preserve_all and all(
            (not line.strip()) or line.lstrip().startswith("- ")
            for line in p.splitlines()
        ) and any(line.lstrip().startswith("- ") for line in p.splitlines()):
            items = [line.lstrip()[2:].strip() for line in p.splitlines() if line.lstrip().startswith("- ")]
            out.append("<ul>" + "".join(f"<li>{_inline(item)}</li>" for item in items) + "</ul>")
        # Regular paragraph — generated copy may still drop stray fragments, but a
        # manually submitted custom article is an immutable payload and preserves
        # every non-empty paragraph regardless of length.
        elif preserve_all or len(p) > 30:
            out.append(f"<p>{_inline(p)}</p>")
        elif p and not p.endswith((".", "!", "?", ":")) and p[0:1].isupper():
            # Short standalone label line (e.g. a date sub-header) — keep as subhead
            out.append(f'<h3 class="article-subhead">{_inline(p)}</h3>')
    return "".join(out)


def build_content_bank(feed_documents=None):
    """Build rich-content matches from the shared prefetched RSS documents."""
    bank = []
    seen = set()
    feed_documents = feed_documents or {}
    for url in CONTENT_BANK_FEEDS:
        try:
            feed = feed_documents[url] if url in feed_documents else _fetch_feed_document(url)
            for entry in getattr(feed, "entries", [])[:25]:
                title = sanitize_text(entry.get("title", ""))
                link = extract_publisher_url(entry)
                if _is_excluded_source_entry(entry, title=title, link=link):
                    continue
                if not title or title.lower() in seen:
                    continue
                seen.add(title.lower())
                summary = entry.get("summary", entry.get("description", ""))[:4000]
                if summary and len(summary) > 100:
                    feed_meta = getattr(feed, "feed", {}) or {}
                    bank.append({
                        "title": title,
                        "summary": summary,
                        "source": feed_meta.get("title", url),
                    })
        except Exception as e:
            print(f"  Content bank feed error ({url[:50]}): {e}")
    print(f"  Content bank built: {len(bank)} entries")
    return bank


def find_content(headline, content_bank, max_entries=5):
    """Fuzzy-match a headline against the content bank and return combined rich summaries."""
    stops = {"that","this","with","from","have","been","said","will","more",
             "also","when","were","they","their","about","says","just","after"}
    def tokens(text):
        return set(re.sub(r"[^a-z0-9 ]", " ", text.lower()).split()) - stops
    hero_tokens = tokens(headline)
    matches = []
    for entry in content_bank:
        overlap = len(hero_tokens & tokens(entry["title"]))
        if overlap >= 2:
            matches.append((overlap, entry))
    matches.sort(key=lambda x: x[0], reverse=True)
    if not matches:
        return ""
    parts = []
    for _, entry in matches[:max_entries]:
        src     = entry["source"]
        title   = entry["title"]
        summary = entry["summary"]
        parts.append(f"[{src}] {title}\n{summary}")
    return "\n\n".join(parts)




def fetch_article_text(url, max_words=2500, content_hint=""):
    """Fetch readable article body text.

    Uses trafilatura when available, then JSON-LD articleBody, then a paragraph fallback.
    Returns plain text or an empty string on failure.
    """
    if not url:
        return ""

    cache_key = _source_text_cache_key(url, max_words, content_hint)
    cached = GENERATION_CACHE.get("source_text", cache_key)
    if cached is not _CACHE_MISS:
        return str(cached.get("text", ""))

    # Multiple category workers can encounter the same source at once. Only one
    # worker performs the network extraction; the others recheck the cache after
    # acquiring the per-source lock.
    fetch_lock = _source_fetch_lock(cache_key)
    fetch_lock.acquire()
    cached = GENERATION_CACHE.get("source_text", cache_key)
    if cached is not _CACHE_MISS:
        fetch_lock.release()
        return str(cached.get("text", ""))

    def _finish(text):
        text = str(text or "")
        try:
            # Successful extractions remain valid while the feed fingerprint is stable.
            # Short-lived negative caching prevents repeatedly hammering blocked sources.
            GENERATION_CACHE.put(
                "source_text",
                cache_key,
                {"text": text, "word_count": len(text.split()), "url": _normalize_cache_url(url)},
                ttl_seconds=86400 if text else 7200,
            )
            return text
        finally:
            fetch_lock.release()

    try:
        resp = requests.get(
            url,
            timeout=8,
            allow_redirects=True,
            headers={
                "User-Agent": (
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) "
                    "Chrome/120.0 Safari/537.36"
                )
            },
        )
        if resp.status_code != 200:
            return _finish("")

        html = resp.text

        def clean_article_text(raw):
            raw = re.sub(r"<script.*?</script>", " ", raw or "", flags=re.DOTALL | re.IGNORECASE)
            raw = re.sub(r"<style.*?</style>", " ", raw, flags=re.DOTALL | re.IGNORECASE)
            raw = re.sub(r"<[^>]+>", " ", raw)
            raw = re.sub(r"&[a-zA-Z0-9#]+;", " ", raw)
            raw = re.sub(r"\s+", " ", raw).strip()
            junk = [
                "subscribe", "sign up", "cookie", "advertisement", "all rights reserved",
                "terms of service", "privacy policy", "follow us", "newsletter",
                "download our app", "watch live", "copyright"
            ]
            sentences = re.split(r"(?<=[.!?])\s+", raw)
            kept = [s.strip() for s in sentences if len(s.strip()) > 25 and not any(j in s.lower() for j in junk)]
            words = " ".join(kept).split()
            return " ".join(words[:max_words]).strip()

        # 1. Best: trafilatura if installed in the workflow.
        try:
            import trafilatura
            extracted = trafilatura.extract(
                html,
                url=url,
                include_comments=False,
                include_tables=False,
                favor_precision=False,
            )
            cleaned = clean_article_text(extracted or "")
            if len(cleaned.split()) >= 140:
                return _finish(cleaned)
        except Exception:
            pass

        # 2. JSON-LD articleBody often exists on modern news pages.
        scripts = re.findall(
            r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>',
            html,
            flags=re.DOTALL | re.IGNORECASE,
        )
        for raw in scripts:
            try:
                data = json.loads(raw.strip())
            except Exception:
                continue
            stack = data if isinstance(data, list) else [data]
            for item in stack:
                if not isinstance(item, dict):
                    continue
                candidates = item.get("@graph") if isinstance(item.get("@graph"), list) else [item]
                for c in candidates:
                    if isinstance(c, dict) and c.get("articleBody"):
                        cleaned = clean_article_text(c.get("articleBody", ""))
                        if len(cleaned.split()) >= 140:
                            return _finish(cleaned)

        # 3. Fallback: paragraphs within <article>, then all paragraphs.
        article_match = re.search(r"<article[^>]*>(.*?)</article>", html, re.DOTALL | re.IGNORECASE)
        scope = article_match.group(1) if article_match else html
        paras = re.findall(r"<p[^>]*>(.*?)</p>", scope, re.DOTALL | re.IGNORECASE)
        cleaned = clean_article_text(" ".join(paras))
        return _finish(cleaned if len(cleaned.split()) >= 80 else "")

    except Exception:
        return _finish("")


def enhance_card(card, content_bank, headlines):
    """Rewrite a card from its exact source article, not fuzzy content-bank matches."""
    headline = card.get("headline", "")
    if not headline:
        return card

    # The category-generation call already receives the exact source body. Do not
    # spend a second Claude request rewriting a card that already passes the final
    # publication gate. This is the primary cold-cache runtime reduction.
    if _publishable_article(card, hero=False):
        card["enriched"] = True
        GENERATION_CACHE.stats["card_second_pass_skipped"] += 1
        return card

    source = None
    idx = card.get("source_index")
    if idx is not None:
        try:
            source = headlines[int(idx) - 1]
        except Exception:
            source = None

    if not source:
        return card

    link = source.get("link", "")
    is_thin = source.get("source_type") == "discovery_only" or any(d in link.lower() for d in THIN_SOURCE_DOMAINS)
    source_text = source.get("article_text", "") or ""

    # If article_text was not stored, try fetching it now — for open full sources
    # AND aggregators (Google News links resolve to real publisher pages). This is
    # what lets crime/things-to-do cards from Google News enrich instead of being dropped.
    if not source_text and link and not is_thin and source.get("source_type") in ("full_source", "aggregator"):
        source_text = fetch_article_text(link, max_words=2500, content_hint=_source_content_hint(source))
        if source_text and len(source_text.split()) >= 140:
            source["article_text"] = source_text
            source["source_quality"] = "full"

    # Fallback only to the exact RSS summary for this same story, never the fuzzy bank.
    if not source_text:
        source_text = source.get("summary", "")

    word_count = len(source_text.split())
    if word_count < 80 or is_thin:
        # Not enough verifiable material for a full rewrite. Keep Claude's original,
        # but do not expand a paywalled/thin blurb into fake detail.
        return card

    try:
        body = card.get("body", "")
        target = "two fully developed paragraphs, about 170-240 words total" if word_count >= 140 else "one concise paragraph"
        update_lead_instruction = ""
        if _source_story_form(source) == "update":
            update_lead_instruction = (
                " Because this is an update, the first paragraph must state both the "
                "original event and the new development so it stands alone for readers "
                "who did not see earlier coverage."
            )
        prompt = (
            f"Rewrite this local news card using the exact source material below.\n\n"
            f"Card headline: {headline}\n\n"
            f"Current card body:\n{body}\n\n"
            f"Exact source material:\n{source_text[:6000]}\n\n"
            f"Write {target}. Use only confirmed facts from the source. "
            "Include concrete names, places, agencies, dates, numbers, votes, charges, locations, schools, roads, or businesses when present. "
            "Do not write generic background, typical patterns, community-impact filler, or advice unless explicitly stated in the source. "
            f"If the source lacks enough facts, write less and stop.{update_lead_instruction} "
            "No em dashes. Return only the rewritten body."
        )
        resp = client.messages.create(
            model=MODEL_ARTICLES,
            max_tokens=800,
            messages=[{"role": "user", "content": prompt}]
        )
        enhanced = resp.content[0].text.strip()
        explanation_signals = ["i cannot rewrite", "source material", "does not match", "cannot proceed"]
        if enhanced and not any(s in enhanced.lower()[:150] for s in explanation_signals):
            # Only accept a short rewrite if the source itself was short. Full sources should
            # produce at least two useful paragraphs.
            if word_count < 140 or len(enhanced.split()) >= 90:
                card["body"] = strip_absence_language(strip_markdown(enhanced, headline))
                card["enriched"] = True
    except Exception:
        pass

    return card


def enhance_hero_article(hero, full_text):
    """Rewrite the hero article using the full source text for accuracy and detail."""
    # A generated hero counts as enriched only when it passes the same publication
    # quality gate used before permalink creation. A 40-60 word blurb is not an article.
    if _publishable_article(hero, hero=True):
        hero["enriched"] = True
        GENERATION_CACHE.stats["hero_second_pass_skipped"] += 1
        return hero
    if not full_text or len(full_text.split()) < 100:
        return hero  # Not enough extra text to improve on; keep generated body
    body = hero.get("body", "")
    update_lead_instruction = ""
    if str(hero.get("story_form") or "") == "update":
        update_lead_instruction = (
            " The first paragraph must state both the original event and the new "
            "development so the article stands alone without earlier coverage."
        )
    prompt = (
        f"You wrote this article about: {hero.get('headline', '')}\n\n"
        f"Your original article:\n\n{body}\n\n"
        f"Here is source material:\n\n{full_text}\n\n"
        "If the source material is clearly about a different story, location, or incident than the headline, "
        "return your original article exactly as written above with no changes. "
        "Otherwise, rewrite your article using confirmed facts from the source. "
        "Write in your own words — paraphrase everything except direct quotes from named individuals. "
        "Do not invent details not in the source. Do not comment on absent information. "
        "Do not copy newsletter openers like 'Good morning'. "
        f"Keep it 380-480 words in four paragraphs. Include the concrete facts from the source.{update_lead_instruction} "
        "Plain direct English. No em dashes."
    )
    try:
        resp = client.messages.create(
            model=MODEL_ARTICLES,
            max_tokens=1600,
            messages=[{"role": "user", "content": prompt}]
        )
        enhanced = resp.content[0].text.strip()
        # Detect if Claude returned an explanation instead of an article
        explanation_signals = ["i cannot rewrite", "source material", "does not match", "i must return", "cannot proceed"]
        if enhanced and not any(s in enhanced.lower()[:200] for s in explanation_signals):
            candidate_body = strip_markdown(enhanced, hero.get("headline", ""))
            candidate = dict(hero)
            candidate["body"] = candidate_body
            if _publishable_article(candidate, hero=True):
                hero["body"] = candidate_body
                hero["enriched"] = True
                print(f"  Hero article enhanced with full source text")
            else:
                print(f"  Enhancement rejected: result was still too thin for a hero article")
        else:
            print(f"  Enhancement skipped: Claude returned explanation, keeping original")
    except Exception as e:
        print(f"  Enhancement failed ({e}), keeping original")
    return hero


def format_age(published_str):
    """Format publish time using stdlib only — no pytz needed."""
    if not published_str:
        return ""
    try:
        from email.utils import parsedate_to_datetime
        from datetime import timezone, timedelta
        et      = timezone(timedelta(hours=-4))  # EDT approximation
        dt_utc  = parsedate_to_datetime(published_str).astimezone(timezone.utc)
        now_utc = datetime.now(timezone.utc)
        mins    = int((now_utc - dt_utc).total_seconds() / 60)
        dt_et   = dt_utc.astimezone(et)
        now_et  = now_utc.astimezone(et)
        hour    = dt_et.hour % 12 or 12
        ampm    = "AM" if dt_et.hour < 12 else "PM"
        time_str = f"{hour}:{dt_et.strftime('%M')} {ampm} ET"
        if mins < 60:
            return "A few minutes ago"
        if dt_et.date() == now_et.date():
            return time_str
        if mins < 2880:
            return f"Yesterday, {time_str}"
        months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]
        return f"{months[dt_et.month-1]} {dt_et.day}, {time_str}"
    except Exception:
        return ""


def _format_category_hero_timestamp(item, archive_entries=None):
    """Return a trustworthy human-readable timestamp for category heroes.

    Generated category items often inherit a publisher timestamp. Some feeds expose
    only a calendar date and normalize that value to midnight, which made newly
    published category heroes display ``12:00 AM``. Once an article has been written,
    its TCT archive row is the authoritative publication receipt and contains the
    actual ``first_published`` time. Prefer that value. When only a date or a synthetic
    midnight timestamp exists, show the date instead of pretending midnight was a
    meaningful publication time.
    """
    archive_entries = archive_entries or []
    matched = None
    if isinstance(item, dict):
        archived_slug = str(item.get("_archived_slug") or item.get("slug") or "").strip()
        if archived_slug:
            matched = next(
                (
                    entry
                    for entry in archive_entries
                    if str(entry.get("slug") or "").strip() == archived_slug
                ),
                None,
            )
        if matched is None:
            headline_key = " ".join(
                str(item.get("headline") or "").lower().split()
            )
            exact = [
                entry
                for entry in archive_entries
                if " ".join(str(entry.get("headline") or "").lower().split())
                == headline_key
            ]
            if len(exact) == 1:
                matched = exact[0]
        if matched is None:
            matched = find_matching_entry(
                item.get("headline", ""),
                archive_entries,
                item.get("link", ""),
                is_weather_alert=bool(item.get("is_weather_alert")),
            )

    candidates = []
    if matched:
        candidates.extend(
            [
                matched.get("first_published"),
                matched.get("published_raw"),
            ]
        )
    if isinstance(item, dict):
        candidates.extend(
            [
                item.get("first_published"),
                item.get("published_raw"),
                item.get("published"),
            ]
        )

    for value in candidates:
        raw = str(value or "").strip()
        if not raw:
            continue

        # Preserve already-humanized relative labels.
        lowered = raw.lower()
        if any(token in lowered for token in ("ago", "yesterday", "a few minutes")):
            return raw

        parsed = None
        try:
            from email.utils import parsedate_to_datetime
            parsed = parsedate_to_datetime(raw)
        except Exception:
            try:
                parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
            except Exception:
                parsed = None

        if parsed is None:
            # Date-only archive values should stay dates, not become midnight.
            if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
                try:
                    dt = datetime.strptime(raw, "%Y-%m-%d")
                    return f"{dt.strftime('%b')} {dt.day}, {dt.year}"
                except Exception:
                    return raw
            return raw

        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)

        # A feed-supplied exact midnight is usually a date placeholder, not a real
        # clock time. The archive's TCT first_published value normally prevents this
        # branch for new stories; this is the safe fallback for legacy rows.
        if parsed.hour == 0 and parsed.minute == 0 and parsed.second == 0:
            return f"{parsed.strftime('%b')} {parsed.day}, {parsed.year}"

        formatted = format_age(raw)
        if formatted:
            return formatted

    return ""



CANONICAL_HERO_FRESHNESS_VERSION = "1.1"
CANONICAL_HERO_FRESHNESS_MAX_AGE_HOURS = 18
CANONICAL_HERO_REFRESHED_SLUGS_THIS_RUN = set()


def _parse_publication_timestamp(value):
    """Parse RFC-822, ISO-8601, or date-only publication values as UTC."""
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        from email.utils import parsedate_to_datetime
        parsed = parsedate_to_datetime(raw)
    except Exception:
        parsed = None
    if parsed is None:
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except Exception:
            try:
                parsed = datetime.strptime(raw[:10], "%Y-%m-%d")
            except Exception:
                return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _canonical_hero_freshness_assessment(item, now=None):
    """Return freshness using the final canonical publication, never source recency.

    Once a live placement has been rebound to an archive record, only a validated
    meaningful-update timestamp or the canonical first-publication timestamp may
    make it fresh. ``lastmod``, image repairs, redirect reconciliation, and an
    incoming source's publication date are deliberately ignored.
    """
    item = item if isinstance(item, dict) else {}
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    canonical_bound = bool(
        item.get("_canonical_freshness_bound")
        or item.get("canonical_slug")
        or item.get("_archived_slug")
    )
    meaningful_validated = bool(item.get("meaningful_update_validated"))
    candidates = []
    if meaningful_validated:
        candidates.extend([
            ("canonical_last_material_update_at", item.get("canonical_last_material_update_at")),
            ("last_meaningful_update_at", item.get("last_meaningful_update_at")),
        ])
    candidates.extend([
        ("canonical_first_published_at", item.get("canonical_first_published_at")),
        ("first_published", item.get("first_published")),
        ("date", item.get("date")),
    ])
    if not canonical_bound:
        candidates.extend([
            ("published_raw", item.get("published_raw")),
            ("published", item.get("published")),
        ])

    timestamp = None
    field = ""
    raw = ""
    for candidate_field, candidate_value in candidates:
        parsed = _parse_publication_timestamp(candidate_value)
        if parsed is None:
            continue
        timestamp = parsed
        field = candidate_field
        raw = str(candidate_value or "")
        break

    if timestamp is None:
        return {
            "stale": bool(canonical_bound),
            "reason": "canonical_timestamp_missing" if canonical_bound else "source_timestamp_missing",
            "date_field": "",
            "date_value": "",
            "age_hours": None,
            "canonical_bound": canonical_bound,
            "meaningful_update_validated": meaningful_validated,
        }

    age_hours = max(0.0, (now - timestamp).total_seconds() / 3600)
    stale = age_hours >= CANONICAL_HERO_FRESHNESS_MAX_AGE_HOURS
    if field in {"canonical_last_material_update_at", "last_meaningful_update_at"}:
        reason = "validated_meaningful_update_fresh" if not stale else "validated_meaningful_update_stale"
    elif canonical_bound:
        reason = "canonical_publication_fresh" if not stale else "canonical_publication_stale"
    else:
        reason = "source_publication_fresh" if not stale else "source_publication_stale"
    return {
        "stale": stale,
        "reason": reason,
        "date_field": field,
        "date_value": raw,
        "age_hours": round(age_hours, 2),
        "canonical_bound": canonical_bound,
        "meaningful_update_validated": meaningful_validated,
    }


def _record_validated_meaningful_update(existing, item, diagnostics, *, changed, now=None):
    """Stamp hero freshness only for a changed, contextual, genuine update."""
    route = str(
        (item or {}).get("_editorial_route") or (item or {}).get("editorial_route") or ""
    ).strip().lower()
    valid = bool(
        isinstance(existing, dict)
        and isinstance(item, dict)
        and changed
        and route in {"update_existing", "replace_canonical"}
        and (diagnostics or {}).get("required")
        and (diagnostics or {}).get("passed")
        and (diagnostics or {}).get("baseline_present")
        and (diagnostics or {}).get("novelty_present")
    )
    if not valid:
        return False
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    stamp = now.isoformat(timespec="seconds").replace("+00:00", "Z")
    canonical_first = str(
        existing.get("canonical_first_published_at")
        or existing.get("first_published")
        or existing.get("date")
        or ""
    )
    origin_headline = str(
        existing.get("permalink_origin_headline")
        or existing.get("headline")
        or ""
    )
    if canonical_first:
        existing["canonical_first_published_at"] = canonical_first
        item["canonical_first_published_at"] = canonical_first
    if origin_headline and not existing.get("permalink_origin_headline"):
        existing["permalink_origin_headline"] = origin_headline
    existing["last_meaningful_update_at"] = stamp
    existing["canonical_last_material_update_at"] = stamp
    existing["meaningful_update_validated"] = True
    existing["meaningful_update_basis"] = "contextual_update_contract"
    item["last_meaningful_update_at"] = stamp
    item["canonical_last_material_update_at"] = stamp
    item["meaningful_update_validated"] = True
    item["meaningful_update_basis"] = "contextual_update_contract"
    item["_canonical_freshness_bound"] = True
    refreshed_slug = str(existing.get("slug") or item.get("canonical_slug") or item.get("_archived_slug") or "").strip()
    if refreshed_slug:
        CANONICAL_HERO_REFRESHED_SLUGS_THIS_RUN.add(refreshed_slug)
    return True


def _write_canonical_hero_freshness_report(report):
    path = CANONICAL_HERO_FRESHNESS_REPORT_PATH
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
    return report


def enforce_final_canonical_hero_freshness(all_categories, top_cat, output_root=None):
    """Re-evaluate the homepage hero after final canonical publication binding.

    A fresh feed item can be rebound to an old canonical only after archive writing.
    This final barrier prevents the feed timestamp from surviving that rebind. When a
    fresh canonical alternative exists, the stale hero is deterministically replaced.
    """
    output_root = Path(output_root or OUTPUT_DIR)
    now = datetime.now(timezone.utc)
    before = (top_cat or {}).get("hero") or {}
    before_assessment = _canonical_hero_freshness_assessment(before, now=now)

    fresh_candidates = []
    for category in all_categories or []:
        for placement, item in [("hero", category.get("hero"))] + [
            ("card", card) for card in (category.get("cards") or [])
        ]:
            if not isinstance(item, dict) or not item.get("headline"):
                continue
            if _is_nonstory_placeholder(item) or item.get("ranking_eligible") is False:
                continue
            category_key = str(category.get("category_key") or "")
            if category_key == "florida":
                continue
            if placement == "card" and (
                not _publishable_article(item, hero=True)
                or not _hero_eligible(category_key, item)
            ):
                continue
            if category_key not in COUNTY_KEYS:
                local_blob = " ".join([
                    str(item.get("headline") or ""),
                    str(item.get("teaser") or ""),
                    str(item.get("body") or "")[:900],
                ]).lower()
                local_markers = (
                    "florida", "treasure coast", "martin county", "st. lucie",
                    "st lucie", "indian river", "stuart", "jensen beach",
                    "palm city", "hobe sound", "port salerno", "port st. lucie",
                    "port st lucie", "fort pierce", "vero beach", "sebastian",
                    "fellsmere", "indiantown", "jupiter island",
                    "hutchinson island", "mets", "clover park", "roger dean",
                )
                if not any(marker in local_blob for marker in local_markers):
                    continue
            assessment = _canonical_hero_freshness_assessment(item, now=now)
            if not assessment.get("stale"):
                fresh_candidates.append({
                    "category_key": category.get("category_key", ""),
                    "placement": placement,
                    "headline": item.get("headline", ""),
                    "canonical_slug": item.get("canonical_slug") or item.get("_archived_slug") or "",
                    **assessment,
                })

    refreshed_slugs = {str(slug or "").strip() for slug in CANONICAL_HERO_REFRESHED_SLUGS_THIS_RUN if str(slug or "").strip()}
    refreshed_candidates = [
        row for row in fresh_candidates
        if str(row.get("canonical_slug") or "").strip() in refreshed_slugs
    ]

    action = "retained_fresh_canonical_hero"
    selected = top_cat
    if refreshed_candidates:
        # A canonical can become legitimately fresh only inside write_archives(),
        # which runs after the initial homepage hero selection. Reopen the normal
        # guarded hero competition exactly once when that happens so the refreshed
        # canonical is not excluded merely because its permalink is older. Use the
        # normal selector (including its editorial model choice) rather than forcing
        # a deterministic promotion of the updated story.
        selected = select_front_page_hero(all_categories)
        if selected is None:
            raise RuntimeError(
                "Canonical hero freshness contract FAILED: a same-run validated material "
                "update became fresh but hero reselection produced no hero"
            )
        action = "reselected_after_same_run_material_update"
    elif before_assessment.get("stale") and fresh_candidates:
        selected = select_front_page_hero(all_categories, deterministic_only=True)
        if selected is None:
            raise RuntimeError(
                "Canonical hero freshness contract FAILED: a fresh canonical candidate exists "
                "but reselection produced no hero"
            )
        action = "reselected_after_final_canonical_binding"

    after = (selected or {}).get("hero") or {}
    after_assessment = _canonical_hero_freshness_assessment(after, now=now)
    if after_assessment.get("stale") and fresh_candidates:
        report = {
            "version": CANONICAL_HERO_FRESHNESS_VERSION,
            "generated_at": now.isoformat(timespec="seconds"),
            "passed": False,
            "action": action,
            "before": {"headline": before.get("headline", ""), **before_assessment},
            "after": {"headline": after.get("headline", ""), **after_assessment},
            "fresh_candidate_count": len(fresh_candidates),
            "fresh_candidates": fresh_candidates,
            "same_run_material_update_candidate_count": len(refreshed_candidates),
            "same_run_material_update_candidates": refreshed_candidates,
        }
        _write_canonical_hero_freshness_report(report)
        raise RuntimeError(
            "Canonical hero freshness contract FAILED: final hero is stale while "
            f"{len(fresh_candidates)} fresh canonical candidate(s) exist"
        )

    report = {
        "version": CANONICAL_HERO_FRESHNESS_VERSION,
        "generated_at": now.isoformat(timespec="seconds"),
        "passed": True,
        "action": action if fresh_candidates else "stale_fallback_no_fresh_canonical_candidates",
        "before": {
            "headline": before.get("headline", ""),
            "canonical_slug": before.get("canonical_slug") or before.get("_archived_slug") or "",
            **before_assessment,
        },
        "after": {
            "headline": after.get("headline", ""),
            "canonical_slug": after.get("canonical_slug") or after.get("_archived_slug") or "",
            **after_assessment,
        },
        "fresh_candidate_count": len(fresh_candidates),
        "fresh_candidates": fresh_candidates,
        "same_run_material_update_candidate_count": len(refreshed_candidates),
        "same_run_material_update_candidates": refreshed_candidates,
    }
    _write_canonical_hero_freshness_report(report)
    print(
        "  Canonical hero freshness contract PASSED: "
        f"{report['action']} — '{after.get('headline','')[:60]}'"
    )
    return selected


HERO_PREFILTER_AUDIT = []
FRONT_PAGE_HERO_AUDIT = {}

def _write_front_page_hero_audit(output_root=None):
    root = Path(output_root or OUTPUT_DIR)
    path = root / "data" / "front-page-hero-selection.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(FRONT_PAGE_HERO_AUDIT, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    return path

def select_front_page_hero(all_categories, deterministic_only=False):
    """Select the strongest current front-page story across every live placement.

    Section heroes are editorial layout choices, not the complete candidate pool. A
    fresh custom article or strong card must be able to outrank an older recovered
    section hero. Archive-only stories remain available as a structural last resort,
    but routine sports recaps cannot lead while any viable non-sports story exists.
    """
    if not all_categories:
        return None

    from email.utils import parsedate_to_datetime
    from datetime import timezone as _tz, timedelta

    _now = datetime.now(_tz.utc)

    def _candidate_view(cat, item, placement, card_index=None):
        return {
            "category_key": cat.get("category_key", ""),
            "category_label": cat.get("category_label", ""),
            "hero": item,
            "cards": cat.get("cards", []),
            "_source_category": cat,
            "_source_placement": placement,
            "_source_card_index": card_index,
        }

    def _is_major_sports_story(item):
        text = " ".join([
            str(item.get("headline") or ""),
            str(item.get("teaser") or ""),
            str(item.get("body") or "")[:500],
        ]).lower()
        major_terms = [
            "championship", "state title", "national title", "playoff berth",
            "wins state", "wins national", "olympic", "world series",
            "drafted", "signs with", "record-setting", "record setting",
        ]
        urgency = int(item.get("urgency_score", 0) or 0)
        return urgency >= 8 or any(term in text for term in major_terms)

    def _is_eligible(candidate):
        cat_key = candidate.get("category_key", "")
        item = candidate.get("hero") or {}
        if not item.get("headline") or _is_nonstory_placeholder(item):
            return False
        if item.get("ranking_eligible") is False:
            return False
        if cat_key == "florida":
            return False
        if candidate.get("_source_placement") == "card":
            if not _publishable_article(item, hero=True):
                return False
            if not _hero_eligible(cat_key, item):
                return False
        if cat_key in COUNTY_KEYS:
            return True
        blob = " ".join([
            str(item.get("headline") or ""),
            str(item.get("teaser") or ""),
            str(item.get("body") or "")[:900],
        ]).lower()
        local_markers = [
            "florida", "treasure coast", "martin county", "st. lucie", "st lucie",
            "indian river", "stuart", "jensen beach", "palm city", "hobe sound",
            "port salerno", "port st. lucie", "port st lucie", "fort pierce",
            "vero beach", "sebastian", "fellsmere", "indiantown", "jupiter island",
            "hutchinson island", "mets", "clover park", "roger dean",
        ]
        return _has_any(blob, local_markers)

    def _parse_hero_datetime(item):
        assessment = _canonical_hero_freshness_assessment(item, now=_now)
        raw = assessment.get("date_value") or ""
        dt = _parse_publication_timestamp(raw)
        return dt, assessment.get("date_field", ""), raw

    stale_day_names = {
        (_now - timedelta(days=1)).strftime("%A").lower(),
        (_now - timedelta(days=2)).strftime("%A").lower(),
        (_now - timedelta(days=3)).strftime("%A").lower(),
    }
    stale_event_phrases = [
        "yesterday", "two days ago", "three days ago", "earlier this week",
        "last week", "days ago", "happened on", "occurred on",
    ]
    fresh_dev_phrases = [
        "today", "this morning", "this afternoon", "this evening",
        "hours ago", "minutes ago", "just announced", "just released",
        "breaking", "moments ago", "earlier today",
    ]

    def _stale_assessment(candidate):
        item = candidate.get("hero") or {}
        content = " ".join([
            str(item.get("teaser") or ""),
            str(item.get("body") or "")[:900],
        ]).lower()
        canonical_assessment = _canonical_hero_freshness_assessment(item, now=_now)
        dt, date_field, raw_date = _parse_hero_datetime(item)
        age_hours = canonical_assessment.get("age_hours")
        if item.get("_canonical_freshness_bound") or item.get("canonical_slug") or item.get("_archived_slug"):
            return dict(canonical_assessment)
        if dt is not None:
            same_day = dt.date() == _now.date()
            if same_day or (age_hours is not None and age_hours < 18):
                return {
                    "stale": False,
                    "reason": "same_day_publication" if same_day else "published_within_18_hours",
                    "date_field": date_field,
                    "date_value": raw_date,
                    "age_hours": round(age_hours, 2) if age_hours is not None else None,
                    "canonical_bound": False,
                    "meaningful_update_validated": bool(item.get("meaningful_update_validated")),
                }
        if any(phrase in content for phrase in fresh_dev_phrases):
            return {
                "stale": False,
                "reason": "fresh_development_language",
                "date_field": date_field,
                "date_value": raw_date,
                "age_hours": round(age_hours, 2) if age_hours is not None else None,
            }
        for day in stale_day_names:
            if f" {day} " in content or content.startswith(f"{day} ") or f" {day}." in content or f" {day}," in content:
                return {
                    "stale": True,
                    "reason": f"past_day_reference:{day}",
                    "date_field": date_field,
                    "date_value": raw_date,
                    "age_hours": round(age_hours, 2) if age_hours is not None else None,
                }
        if any(phrase in content for phrase in stale_event_phrases):
            phrase = next(phrase for phrase in stale_event_phrases if phrase in content)
            return {
                "stale": True,
                "reason": f"stale_event_phrase:{phrase}",
                "date_field": date_field,
                "date_value": raw_date,
                "age_hours": round(age_hours, 2) if age_hours is not None else None,
            }
        if age_hours is not None and age_hours >= 18:
            return {
                "stale": True,
                "reason": "published_18_plus_hours_ago",
                "date_field": date_field,
                "date_value": raw_date,
                "age_hours": round(age_hours, 2),
            }
        return {
            "stale": False,
            "reason": "no_reliable_stale_signal",
            "date_field": date_field,
            "date_value": raw_date,
            "age_hours": round(age_hours, 2) if age_hours is not None else None,
        }

    def _priority(candidate):
        item = candidate.get("hero") or {}
        urgency = int(item.get("urgency_score", 0) or 0)
        cap = CATEGORIES.get(candidate.get("category_key", ""), {}).get("front_page_cap", 10)
        score = min(urgency, cap) * 10
        category_bonus = {
            "local_gov": 24,
            "crime": 22,
            "business": 16,
            "martin": 14,
            "st_lucie": 14,
            "indian_river": 14,
            "things_to_do": 2,
            "sports": -24,
        }
        score += category_bonus.get(candidate.get("category_key", ""), 0)
        if item.get("force_hero"):
            score += 1000
        if item.get("is_custom") or item.get("authoritative_custom"):
            score += 8
        if candidate.get("_source_placement") == "hero":
            score += 1
        if item.get("_archive_only") and not item.get("_custom_active_queue"):
            score -= 35
        assessment = _stale_assessment(candidate)
        age = assessment.get("age_hours")
        if age is not None:
            if age < 6:
                score += 18
            elif age < 18:
                score += 10
            elif age < 36:
                score -= 4
            elif age < 72:
                score -= 18
            else:
                score -= 35
        return score

    def _candidate_audit(candidate):
        item = candidate.get("hero") or {}
        assessment = _stale_assessment(candidate)
        return {
            "headline": item.get("headline", ""),
            "category_key": candidate.get("category_key", ""),
            "category_label": candidate.get("category_label", ""),
            "placement": candidate.get("_source_placement", ""),
            "urgency_score": int(item.get("urgency_score", 0) or 0),
            "priority_score": _priority(candidate),
            "archive_only": bool(item.get("_archive_only") and not item.get("_custom_active_queue")),
            "active_custom_queue": bool(item.get("_custom_active_queue")),
            "is_custom": bool(item.get("is_custom") or item.get("authoritative_custom")),
            "major_sports": bool(candidate.get("category_key") == "sports" and _is_major_sports_story(item)),
            **assessment,
        }

    def _materialize(candidate, reason):
        global FRONT_PAGE_HERO_AUDIT
        source = candidate.get("_source_category") or candidate
        placement = candidate.get("_source_placement")
        selected_item = candidate.get("hero") or {}
        if placement == "card":
            cards = list(source.get("cards") or [])
            idx = candidate.get("_source_card_index")
            if not isinstance(idx, int) or idx < 0 or idx >= len(cards) or cards[idx] is not selected_item:
                idx = next((i for i, card in enumerate(cards) if card is selected_item), None)
            if idx is None:
                selected_key = (
                    str(selected_item.get("editorial_story_id") or selected_item.get("_editorial_story_id") or ""),
                    str(selected_item.get("headline") or "").strip().lower(),
                    str(selected_item.get("link") or ""),
                )
                idx = next((
                    i for i, card in enumerate(cards)
                    if (
                        str(card.get("editorial_story_id") or card.get("_editorial_story_id") or ""),
                        str(card.get("headline") or "").strip().lower(),
                        str(card.get("link") or ""),
                    ) == selected_key
                ), None)
            if idx is not None:
                promoted = cards.pop(idx)
                old_hero = source.get("hero")
                source["hero"] = promoted
                if old_hero and old_hero.get("headline") and old_hero is not promoted:
                    old_key = str(old_hero.get("headline") or "").strip().lower()
                    if all(str(card.get("headline") or "").strip().lower() != old_key for card in cards):
                        cards.insert(0, old_hero)
                source["cards"] = cards
                print(
                    f"  Front page candidate promoted from {source.get('category_label','')} card: "
                    f"{promoted.get('headline','')[:60]}"
                )
        selected = source.get("hero") or selected_item
        FRONT_PAGE_HERO_AUDIT = {
            "version": "1.11.3.4",
            "generated_at": datetime.now(_tz.utc).isoformat(timespec="seconds"),
            "selection_reason": reason,
            "selected": {
                "headline": selected.get("headline", ""),
                "category_key": source.get("category_key", candidate.get("category_key", "")),
                "category_label": source.get("category_label", candidate.get("category_label", "")),
                "urgency_score": int(selected.get("urgency_score", 0) or 0),
                "archive_only": bool(selected.get("_archive_only") and not selected.get("_custom_active_queue")),
                "active_custom_queue": bool(selected.get("_custom_active_queue")),
                "is_custom": bool(selected.get("is_custom") or selected.get("authoritative_custom")),
            },
            "candidates": sorted(
                [_candidate_audit(row) for row in candidate_pool],
                key=lambda row: row.get("priority_score", 0),
                reverse=True,
            ),
        }
        print(
            f"  Front page hero: [{source.get('category_label', candidate.get('category_label',''))}] "
            f"{selected.get('headline','')[:60]} ({reason})"
        )
        return source

    candidate_pool = []
    seen = set()
    for cat in all_categories:
        placements = [("hero", cat.get("hero"), None)]
        placements.extend(("card", card, index) for index, card in enumerate(cat.get("cards") or []))
        for placement, item, index in placements:
            if not isinstance(item, dict) or not item.get("headline"):
                continue
            candidate = _candidate_view(cat, item, placement, index)
            if not _is_eligible(candidate):
                continue
            identity = (
                str(item.get("editorial_story_id") or item.get("_editorial_story_id") or ""),
                re.sub(r"[^a-z0-9]+", " ", str(item.get("headline") or "").lower()).strip(),
                str(item.get("link") or item.get("source_link") or ""),
            )
            if identity in seen:
                continue
            seen.add(identity)
            candidate_pool.append(candidate)

    if not candidate_pool:
        # Final structural fallback: never hand control back to the legacy main()
        # max-score branch, which cannot distinguish archive recovery from current
        # reporting. Keep the site renderable while still preferring non-sports and
        # non-Florida section leads.
        structural = []
        for cat in all_categories:
            item = cat.get("hero") or {}
            if not item.get("headline") or _is_nonstory_placeholder(item):
                continue
            structural.append(_candidate_view(cat, item, "hero"))
        non_florida = [c for c in structural if c.get("category_key") != "florida"]
        if non_florida:
            structural = non_florida
        non_sports = [c for c in structural if c.get("category_key") != "sports"]
        if non_sports:
            structural = non_sports
        if not structural:
            return None
        candidate_pool = structural
        return _materialize(max(structural, key=_priority), "structural_non_sports_fallback")

    active_candidates = [
        c for c in candidate_pool
        if not (c.get("hero") or {}).get("_archive_only")
        or (c.get("hero") or {}).get("_custom_active_queue")
    ]
    active_ids = {id(candidate) for candidate in active_candidates}
    archive_candidates = [
        candidate for candidate in candidate_pool if id(candidate) not in active_ids
    ]
    working = active_candidates if active_candidates else list(candidate_pool)

    forced = [c for c in working if (c.get("hero") or {}).get("force_hero")]
    if forced:
        return _materialize(max(forced, key=_priority), "explicit_force_hero")

    fresh_candidates = []
    global HERO_PREFILTER_AUDIT
    HERO_PREFILTER_AUDIT = []
    for candidate in working:
        assessment = _stale_assessment(candidate)
        if assessment.get("stale"):
            HERO_PREFILTER_AUDIT.append(_candidate_audit(candidate))
        else:
            fresh_candidates.append(candidate)

    selection_mode = "fresh_live_candidate" if active_candidates else "fresh_archive_recovery"

    # The final canonical-freshness barrier evaluates every eligible canonical
    # placement, including recent archive-recovery stories.  Hero selection must use
    # the same universe.  Previously, any stale live placement caused fresh archive
    # candidates to be discarded before reselection, so the selector returned a stale
    # hero while the barrier correctly observed fresh alternatives and stopped the run.
    # A fresh canonical archive story is preferable to a stale live fallback; archive
    # recovery remains unavailable whenever at least one fresh live candidate exists.
    if not fresh_candidates and active_candidates and archive_candidates:
        fresh_archive_candidates = []
        for candidate in archive_candidates:
            assessment = _stale_assessment(candidate)
            if assessment.get("stale"):
                HERO_PREFILTER_AUDIT.append(_candidate_audit(candidate))
            else:
                fresh_archive_candidates.append(candidate)
        if fresh_archive_candidates:
            fresh_candidates = fresh_archive_candidates
            selection_mode = "fresh_archive_recovery"
            print(
                "  Hero pre-filter: no fresh live candidates; "
                "using fresh canonical archive recovery"
            )

    if fresh_candidates:
        for row in HERO_PREFILTER_AUDIT:
            print(
                "  Hero pre-filter excluded stale candidate: "
                f"{row['headline'][:60]} | reason={row['reason']} | "
                f"date={row.get('date_value') or 'unknown'} | age_hours={row.get('age_hours')}"
            )
        working = fresh_candidates
        non_sports = [c for c in working if c.get("category_key") != "sports"]
        if non_sports:
            working = [
                c for c in working
                if c.get("category_key") != "sports" or _is_major_sports_story(c.get("hero") or {})
            ]
    else:
        print("  Hero pre-filter: no fresh canonical candidates; using deterministic stale fallback")
        non_sports = [c for c in working if c.get("category_key") != "sports"]
        if non_sports:
            working = non_sports
        return _materialize(max(working, key=_priority), "deterministic_stale_fallback")

    working = sorted(working, key=_priority, reverse=True)[:12]
    if deterministic_only:
        reason = (
            "deterministic_post_canonical_archive_recovery"
            if selection_mode == "fresh_archive_recovery"
            else "deterministic_post_canonical_freshness"
        )
        return _materialize(working[0], reason)
    if len(working) == 1:
        return _materialize(working[0], "only_fresh_candidate")

    def _age_label(candidate):
        assessment = _stale_assessment(candidate)
        age = assessment.get("age_hours")
        if age is None:
            return "unknown age"
        if age < 1:
            return f"{max(1, int(age * 60))} minutes ago"
        if age < 24:
            return f"{int(age)} hours ago"
        days = int(age / 24)
        return f"{days} day{'s' if days != 1 else ''} ago"

    listing = "\n\n".join(
        f"{i+1}. [{candidate['category_label']}] (timestamp: {_age_label(candidate)}) "
        f"{candidate['hero'].get('headline','')}\n"
        f"   Content: {(candidate['hero'].get('teaser','') + ' ' + candidate['hero'].get('body','')[:500]).strip()}"
        for i, candidate in enumerate(working)
    )
    today_label = _now.strftime("%A, %B %d, %Y")
    prompt = (
        f"TODAY IS: {today_label}\n\n"
        "Select the SINGLE strongest front-page story for Treasure Coast Today, a hyperlocal news site "
        "covering Martin, St. Lucie, and Indian River counties. All listed candidates have already passed "
        "hard freshness, locality, publication-quality, and archive-safety gates.\n\n"
        f"{listing}\n\n"
        "Rank local impact first and freshness second. Major public safety, local government, infrastructure, "
        "and consequential development stories outrank routine events and routine sports results. A routine "
        "baseball game recap must not beat a meaningful local civic or public-safety story. Custom reporting is "
        "editorially authoritative but should win only when its impact and freshness justify it.\n\n"
        "Return exactly:\nReasoning: <brief comparison>\nPICK: <number>\n"
    )
    try:
        response = client.messages.create(
            model=MODEL_SELECTION,
            max_tokens=500,
            messages=[{"role": "user", "content": prompt}],
        )
        raw = response.content[0].text.strip()
        pick_match = re.search(r"PICK:\s*(\d+)", raw, re.IGNORECASE)
        if pick_match:
            idx = int(pick_match.group(1)) - 1
        else:
            nums = re.findall(r"\d+", raw)
            idx = int(nums[-1]) - 1 if nums else -1
        if 0 <= idx < len(working):
            return _materialize(working[idx], "model_choice_within_guarded_pool")
    except Exception as exc:
        print(f"  Front page hero selection failed ({exc}), using deterministic priority")

    return _materialize(max(working, key=_priority), selection_mode + "_priority_fallback")



def _extract_model_text(response):
    """Return all text blocks from an Anthropic response as one string."""
    chunks = []
    for block in getattr(response, "content", []) or []:
        value = getattr(block, "text", None)
        if value:
            chunks.append(str(value))
    return "\n".join(chunks).strip()



def _queue_model_bakeoff_category(
    *, category_key, category_label, headlines, request_kwargs,
    baseline_output, baseline_response,
):
    """Queue one exact successful live category packet for post-build shadow review."""
    try:
        source_pool = []
        for source in headlines or []:
            source_pool.append({
                "title": str(source.get("title") or ""),
                "published": str(source.get("published") or ""),
                "source_type": str(source.get("source_type") or ""),
                "source_quality": str(source.get("source_quality") or ""),
                "hero_eligible": source.get("hero_eligible"),
                "category_match_score": source.get("category_match_score"),
            })
        baseline_model = str(
            getattr(baseline_response, "model", None)
            or request_kwargs.get("model")
            or MODEL_ARTICLES
        )
        # A retry replaces an earlier unusable attempt for the same category. Nothing
        # here is written to the publication data structures or generation cache.
        MODEL_BAKEOFF_PENDING[str(category_key)] = {
            "category_key": str(category_key),
            "category_label": str(category_label),
            "source_pool": source_pool,
            "request_kwargs": copy.deepcopy(request_kwargs),
            "raw_baseline_output": copy.deepcopy(baseline_output),
            "baseline_output": copy.deepcopy(baseline_output),
            "baseline_model": baseline_model,
        }
    except Exception as exc:
        print(
            f"  Model bake-off queue unavailable for {category_label} "
            f"({type(exc).__name__}); live generation unchanged"
        )


def _parse_model_bakeoff_category_json(raw):
    """Parse challenger structured output without participating in live generation."""
    text = str(raw or "").strip()
    if text.startswith("```"):
        parts = text.split("```")
        text = parts[1] if len(parts) > 1 else text
        if text.lstrip().startswith("json"):
            text = text.lstrip()[4:]
        text = text.strip()
    try:
        from json_repair import repair_json
        data = json.loads(repair_json(text))
    except Exception:
        try:
            data = json.loads(text, strict=False)
        except Exception:
            cleaned = text.encode("ascii", "ignore").decode("ascii")
            start = cleaned.find("{")
            end = cleaned.rfind("}") + 1
            if start == -1 or end <= start:
                raise ValueError(
                    f"Challenger returned no JSON object ({len(cleaned)} chars)"
                )
            data = json.loads(cleaned[start:end], strict=False)
    if isinstance(data, list):
        if len(data) == 1 and isinstance(data[0], dict):
            data = data[0]
        elif data and isinstance(data[0], dict) and "hero" in data[0]:
            data = data[0]
        elif data and all(isinstance(item, dict) for item in data):
            data = {"hero": data[0], "cards": data[1:]}
        else:
            data = {"hero": {}, "cards": []}
    if not isinstance(data, dict):
        data = {"hero": {}, "cards": []}
    return data


def _run_model_bakeoff_variant(packet):
    """Run the challenger only; failures are contained and never affect publication."""
    request_kwargs = copy.deepcopy(packet.get("request_kwargs") or {})
    request_kwargs["model"] = MODEL_BAKEOFF_CHALLENGER
    # Sonnet 5 enables adaptive thinking by default. Disable it for the first bake-off
    # so we compare direct structured writing/selection against the non-thinking
    # Sonnet 4.5 baseline. 8000 leaves headroom for Sonnet 5's newer tokenizer.
    request_kwargs["thinking"] = {"type": "disabled"}
    request_kwargs["max_tokens"] = MODEL_BAKEOFF_MAX_TOKENS
    request_kwargs.pop("timeout", None)
    request_client = client
    if hasattr(client, "with_options"):
        request_client = client.with_options(
            timeout=MODEL_BAKEOFF_TIMEOUT_SECONDS,
            max_retries=0,
        )
    started = time.perf_counter()
    response = request_client.messages.create(**request_kwargs)
    duration = time.perf_counter() - started
    raw = _extract_model_text(response)
    parsed = _parse_model_bakeoff_category_json(raw)
    actual_model = str(
        getattr(response, "model", None)
        or MODEL_BAKEOFF_CHALLENGER
    )
    return parsed, actual_model, duration


def _run_model_bakeoff_after_build():
    """Execute queued Sonnet 5 comparisons after the normal site build has finished."""
    if not MODEL_BAKEOFF_ENABLED:
        return None

    results = []
    baseline_models = []
    pending = list(MODEL_BAKEOFF_PENDING.values())
    print(
        f"  Model bake-off: {len(pending)} live-generated category packet(s) queued; "
        f"challenger={MODEL_BAKEOFF_CHALLENGER}"
    )
    for packet in pending:
        category_label = packet.get("category_label") or packet.get("category_key") or "category"
        baseline_models.append(str(packet.get("baseline_model") or MODEL_ARTICLES))
        result = {
            "category_key": packet.get("category_key"),
            "category_label": category_label,
            "source_pool": packet.get("source_pool") or [],
            "baseline_output": packet.get("baseline_output") or {},
            "challenger_output": {},
            "challenger_error": "",
            "challenger_duration_seconds": None,
        }
        try:
            challenger, actual_model, duration = _run_model_bakeoff_variant(packet)
            result["challenger_output"] = challenger
            result["challenger_duration_seconds"] = round(duration, 3)
            result["challenger_actual_model"] = actual_model
            print(
                f"    {category_label}: challenger completed in {duration:.1f}s"
            )
        except Exception as exc:
            result["challenger_error"] = (
                f"{type(exc).__name__}: {_safe_exception_summary(exc, limit=220)}"
            )
            print(
                f"    {category_label}: challenger failed ({type(exc).__name__}); "
                "live publication unaffected"
            )
        results.append(result)

    baseline_model = baseline_models[0] if baseline_models else MODEL_ARTICLES
    if baseline_models and len(set(baseline_models)) > 1:
        baseline_model = MODEL_ARTICLES
    blind_salt = str(
        os.environ.get("GITHUB_RUN_ID")
        or os.environ.get("GITHUB_SHA")
        or datetime.now(timezone.utc).isoformat()
    )
    report = write_bakeoff_artifacts(
        results=results,
        report_path=MODEL_BAKEOFF_REPORT_PATH,
        review_path=MODEL_BAKEOFF_REVIEW_PATH,
        answer_key_path=MODEL_BAKEOFF_ANSWER_KEY_PATH,
        baseline_model=baseline_model,
        challenger_model=MODEL_BAKEOFF_CHALLENGER,
        blind_salt=blind_salt,
        enabled=True,
    )
    print(
        "  Model bake-off complete: "
        f"{report.get('completed_categories', 0)} scoreable, "
        f"{report.get('failed_categories', 0)} challenger failure(s). "
        "Review data/model-bakeoff-review.md before opening the answer key."
    )
    return report



