def _page_header(active=""):
    def cat_link(label, href, key):
        cls = "cat-btn active" if key == active else "cat-btn"
        if key == active:
            return f'<span class="{cls}">{label}</span>'
        return f'<a href="{href}" class="{cls}" style="text-decoration:none">{label}</a>'

    # Build the category links from CATEGORIES so these labels always match the
    # homepage nav. Previously they were hardcoded abbreviations ("Crime",
    # "Martin Co.") which drifted from the real labels ("Crime & Safety",
    # "Martin County") shown on the homepage.
    cat_links = "\n        ".join(
        cat_link(cfg["label"], f"/?cat={key}", key)
        for key, cfg in CATEGORIES.items()
    )
    return f"""  <header>
    <div class="header-inner">
      <div class="header-top">
        <a href="/" class="wordmark" aria-label="Treasure Coast Today"><span class="wordmark-tct">TCT</span><span class="wordmark-divider"></span><span class="wordmark-full">TREASURE<br>COAST<br>TODAY</span></a>
      </div>
      <nav class="category-nav">
        {cat_link("Top News", "/", "news")}
        {cat_links}
        {cat_link("Weather", "/weather.html", "weather")}
        {cat_link("Archive", "/archive.html", "archive")}
      </nav>
      <div class="header-actions">
        {_header_primary_cta_html()}
      </div>
    </div>
  </header>"""


KIT_INLINE_FORM_UID = "30e15672d3"
KIT_INLINE_FORM_SRC = (
    "https://treasure-coast-today.kit.com/30e15672d3/index.js"
)


def _newsletter_inline_embed(placement):
    """Return the one inline Kit signup module used on a rendered page.

    All visible newsletter CTA copy is owned by Kit. TCT supplies only the
    layout slot and the Kit embed so form wording can be managed in one place.
    """
    placement_key = re.sub(
        r"[^a-z0-9_-]+",
        "-",
        str(placement or "inline").lower(),
    ).strip("-")
    return (
        f'\n      <aside class="newsletter-inline-slot newsletter-inline-slot--{placement_key}" '
        'aria-label="Subscribe to the Treasure Coast Morning Brief">\n'
        f'        <script async data-uid="{KIT_INLINE_FORM_UID}" '
        f'src="{KIT_INLINE_FORM_SRC}"></script>\n'
        '      </aside>'
    )


